PUBLIC_DEFAULT_INSTANCE = ROOT / "instances" / "example-openwrt-pi"


def default_instance_path() -> Path:
    env_instance = os.environ.get("HOMENET_INSTANCE")
    if env_instance:
        return Path(env_instance).expanduser()
    instances_dir = ROOT / "instances"
    if instances_dir.exists():
        for path in sorted(instances_dir.iterdir(), key=lambda item: item.name):
            if path.is_dir() and not path.name.startswith("example-"):
                return path
    return PUBLIC_DEFAULT_INSTANCE


DEFAULT_INSTANCE = default_instance_path()
