def is_public_instance_rel(rel: str) -> bool:
    return rel.startswith("instances/example-")


def is_private_instance_rel(rel: str) -> bool:
    return rel.startswith("instances/") and not is_public_instance_rel(rel)


def private_instance_roots() -> list[str]:
    instances_dir = ROOT / "instances"
    if not instances_dir.exists():
        return []
    rows = []
    for path in sorted(instances_dir.iterdir(), key=lambda item: item.name):
        if path.is_dir() and not path.name.startswith("example-"):
            rows.append(f"instances/{path.name}/")
    return rows


def release_path_status(path: Path) -> tuple[str, str]:
    rel = path.relative_to(ROOT).as_posix() if path.is_absolute() and path.is_relative_to(ROOT) else path.as_posix()
    if is_private_instance_rel(rel):
        return "excluded", "private-deployment-instance"
    if any(rel == item.rstrip("/") or rel.startswith(item) for item in RELEASE_EXCLUDED_ROOTS):
        return "excluded", "private-runtime-or-deployment-specific"
    if any(rel == item.rstrip("/") or rel.startswith(item) for item in RELEASE_INCLUDED_ROOTS):
        return "included", "public-core"
    return "excluded", "not-in-release-scope"


def release_file_count(root: Path, expected_status: str) -> int:
    if not root.exists():
        return 0
    if root.is_file():
        status, _ = release_path_status(root)
        return 1 if status == expected_status else 0
    count = 0
    for dirpath, dirnames, filenames in os.walk(root):
        current = Path(dirpath)
        dirnames[:] = [
            name
            for name in dirnames
            if release_path_status(current / name)[0] == "included"
        ]
        for filename in filenames:
            path = current / filename
            status, _ = release_path_status(path)
            if status == expected_status:
                count += 1
    return count


def git_tracked_files(root: Path = ROOT) -> list[str]:
    output, error = git_command(root, ["ls-files"])
    if error:
        return []
    return sorted(line.strip() for line in output.splitlines() if line.strip())


def load_exported_package_manifest(root: Path = ROOT) -> dict[str, Any] | None:
    manifest_path = root / "PUBLIC_PACKAGE_MANIFEST.json"
    if not manifest_path.is_file():
        return None
    try:
        loaded = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        return None
    return loaded if isinstance(loaded, dict) else None


def build_public_package_manifest(instance: Path) -> dict[str, Any]:
    release = build_release_manifest(instance)
    tracked = git_tracked_files(ROOT)
    exported_manifest = load_exported_package_manifest(ROOT) if not tracked else None
    included_files: list[dict[str, Any]] = []
    excluded_tracked: list[dict[str, Any]] = []
    files_by_root: dict[str, int] = {}

    if exported_manifest:
        included_files = [
            row
            for row in as_list(exported_manifest.get("included_files"))
            if isinstance(row, dict) and row.get("path")
        ]
        excluded_tracked = [
            row
            for row in as_list(exported_manifest.get("excluded_tracked_files"))
            if isinstance(row, dict) and row.get("path")
        ]
        for row in included_files:
            rel = str(row.get("path") or "")
            root = next(
                (item for item in RELEASE_INCLUDED_ROOTS if rel == item.rstrip("/") or rel.startswith(item)),
                "other",
            )
            files_by_root[root] = files_by_root.get(root, 0) + 1
    else:
        for rel in tracked:
            status, reason = release_path_status(Path(rel))
            row = {
                "path": rel,
                "status": status,
                "reason": reason,
            }
            if status == "included":
                included_files.append(row)
                root = next(
                    (item for item in RELEASE_INCLUDED_ROOTS if rel == item.rstrip("/") or rel.startswith(item)),
                    "other",
                )
                files_by_root[root] = files_by_root.get(root, 0) + 1
            else:
                excluded_tracked.append(row)

    package_ready = bool(release.get("public_core_ready")) and bool(included_files)
    return {
        "schema": "homenet.public_package.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "instance": public_instance_label(instance),
        "package_ready": package_ready,
        "summary": {
            "tracked_files": len(tracked),
            "included_files": len(included_files),
            "excluded_tracked_files": len(excluded_tracked),
            "included_roots": len(files_by_root),
            "source": "exported-manifest" if exported_manifest else "git-tracked-files",
            "public_core_ready": release.get("public_core_ready"),
            "whole_worktree_publishable": release.get("whole_worktree_publishable"),
        },
        "files_by_root": dict(sorted(files_by_root.items())),
        "entrypoints": [
            {
                "path": "PUBLIC_PACKAGE.md",
                "purpose": "Start here after receiving an exported public package.",
            },
            {
                "path": "README.md",
                "purpose": "Lightweight project entry: purpose, shortest deployment path, daily operations, and workspace boundaries.",
            },
            {
                "path": "docs/operator-path.md",
                "purpose": "Short operator path for daily use, troubleshooting, and review.",
            },
            {
                "path": "instances/example-openwrt-pi/",
                "purpose": "Server-runtime example deployment profile.",
            },
            {
                "path": "instances/example-openwrt-only/",
                "purpose": "OpenWrt-only example deployment profile.",
            },
        ],
        "included_files": included_files,
        "excluded_tracked_files": excluded_tracked,
        "copy_rules": [
            "Copy only git-tracked files whose release status is included.",
            "Preserve relative paths inside the package directory.",
            "Write PUBLIC_PACKAGE_MANIFEST.json next to the copied files when --output-dir is used.",
            "Do not copy ignored runtime state, private deployment data, nested repositories, caches, databases, credentials, or secrets.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Package manifest is based on tracked paths and release status only; it does not read or print excluded file contents.",
        },
    }


def write_public_package_output(instance: Path, output: Path, *, force: bool) -> dict[str, Any]:
    manifest = build_public_package_manifest(instance)
    errors: list[dict[str, Any]] = []
    copied = 0

    if output.exists() and any(output.iterdir()) and not force:
        errors.append({
            "id": "output-dir-not-empty",
            "path": str(output),
            "detail": "use --force to overwrite known package files",
        })
    if not errors:
        try:
            output.mkdir(parents=True, exist_ok=True)
        except Exception as exc:  # noqa: BLE001 - report shape
            errors.append({"id": "output-dir-create-failed", "path": str(output), "detail": str(exc)})

    if not errors:
        for row in as_list(manifest.get("included_files")):
            if not isinstance(row, dict):
                continue
            rel = str(row.get("path") or "")
            if not rel:
                continue
            source = (ROOT / rel).resolve()
            target = (output / rel).resolve()
            if not source.is_file() or not source.is_relative_to(ROOT) or not target.is_relative_to(output):
                continue
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, target)
                copied += 1
            except Exception as exc:  # noqa: BLE001 - report shape
                errors.append({"id": "copy-failed", "path": rel, "detail": str(exc)})
                break

    if not errors:
        manifest_with_result = dict(manifest)
        manifest_with_result["read_only"] = False
        manifest_with_result["writes_files"] = True
        manifest_with_result["output_dir"] = str(output)
        manifest_with_result["copied_files"] = copied
        try:
            (output / "PUBLIC_PACKAGE_MANIFEST.json").write_text(
                json.dumps(manifest_with_result, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
        except Exception as exc:  # noqa: BLE001 - report shape
            errors.append({"id": "manifest-write-failed", "path": "PUBLIC_PACKAGE_MANIFEST.json", "detail": str(exc)})

    return {
        "schema": "homenet.public_package_write.v1",
        "read_only": False,
        "writes_files": True,
        "writes_live_config": False,
        "instance": str(instance),
        "output_dir": str(output),
        "ok": bool(manifest.get("package_ready")) and not errors,
        "summary": {
            "package_ready": bool(manifest.get("package_ready")),
            "included_files": (manifest.get("summary") or {}).get("included_files") if isinstance(manifest.get("summary"), dict) else None,
            "copied_files": copied,
            "errors": len(errors),
        },
        "manifest": {
            "schema": manifest.get("schema"),
            "package_ready": manifest.get("package_ready"),
            "summary": manifest.get("summary") if isinstance(manifest.get("summary"), dict) else {},
        },
        "errors": errors,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Package writer copies only release-included tracked files and writes a public package manifest.",
        },
    }


def print_public_package_markdown(manifest: dict[str, Any]) -> None:
    summary = manifest.get("summary", {}) if isinstance(manifest.get("summary"), dict) else {}
    print("# Public Package")
    print()
    print(f"- schema: `{manifest.get('schema')}`")
    print(f"- package ready: {manifest.get('package_ready')}")
    print(f"- read only: {manifest.get('read_only')}")
    print(f"- writes files: {manifest.get('writes_files')}")
    print(f"- writes live config: {manifest.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in summary.items():
        print(f"- {key}: {value}")
    print()
    print("## Files By Root")
    print()
    for root, count in (manifest.get("files_by_root") or {}).items():
        print(f"- `{root}`: {count}")
    print()
    print("## Entrypoints")
    print()
    for row in as_list(manifest.get("entrypoints")):
        if isinstance(row, dict):
            print(f"- `{row.get('path')}`: {row.get('purpose')}")
    print()
    print("## Excluded Tracked Files")
    print()
    excluded = as_list(manifest.get("excluded_tracked_files"))
    if not excluded:
        print("- none")
    else:
        for row in excluded:
            if isinstance(row, dict):
                print(f"- `{row.get('path')}`: {row.get('reason')}")
    print()
    print("## Copy Rules")
    print()
    for rule in manifest.get("copy_rules", []):
        print(f"- {rule}")
    print()


def build_public_package_check(output_dir: Path | None) -> dict[str, Any]:
    required_files = {
        "README.md",
        "LICENSE",
        "CONTRIBUTING.md",
        "SECURITY.md",
        "PUBLISHING.md",
        "PUBLIC_PACKAGE.md",
        ".github/workflows/ci.yml",
        "homenet",
        "tools/homenet.py",
        "modules/catalog.yaml",
        "modules/artifacts.yaml",
        "modules/renderers.yaml",
        "modules/implementations.yaml",
        "modules/executors.yaml",
        "modules/backups.yaml",
        "schemas/site.schema.yaml",
        "schemas/devices.schema.yaml",
        "schemas/services.schema.yaml",
        "instances/example-openwrt-pi/site.yaml",
        "instances/example-openwrt-only/site.yaml",
        "templates/compose/README.md",
        "templates/compose/docker-compose.yml",
        "templates/compose/env.example",
        "PUBLIC_PACKAGE_MANIFEST.json",
    }
    forbidden_prefixes = {
        ".env",
        "sub/",
        "adguard/",
        "backups/",
        "caddy/",
        "cloudflared/",
        "ddns-go/",
        "mihomo/",
        "wg-easy/",
    }
    ignored_prefixes = {
        ".git/",
        "__pycache__/",
    }
    ignored_fragments = {
        "/__pycache__/",
    }
    ignored_suffixes = {
        ".pyc",
        ".pyo",
    }
    errors: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    files: list[str] = []
    manifest: dict[str, Any] = {}
    manifest_included: set[str] = set()

    if output_dir is None:
        errors.append({"id": "output-dir-required", "path": "", "detail": "--dir is required"})
    elif not output_dir.exists():
        errors.append({"id": "output-dir-missing", "path": str(output_dir), "detail": "directory does not exist"})
    elif not output_dir.is_dir():
        errors.append({"id": "output-dir-not-directory", "path": str(output_dir), "detail": "path is not a directory"})
    else:
        for path in sorted(output_dir.rglob("*")):
            if path.is_file():
                try:
                    rel = path.relative_to(output_dir).as_posix()
                except ValueError:
                    continue
                if any(rel == prefix.rstrip("/") or rel.startswith(prefix) for prefix in ignored_prefixes):
                    continue
                if any(fragment in rel for fragment in ignored_fragments):
                    continue
                if any(rel.endswith(suffix) for suffix in ignored_suffixes):
                    continue
                files.append(rel)
        manifest_path = output_dir / "PUBLIC_PACKAGE_MANIFEST.json"
        if not manifest_path.is_file():
            errors.append({"id": "manifest-missing", "path": "PUBLIC_PACKAGE_MANIFEST.json", "detail": "package manifest is missing"})
        else:
            try:
                loaded = json.loads(manifest_path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    manifest = loaded
                    manifest_included = {
                        str(item.get("path") or "")
                        for item in as_list(manifest.get("included_files"))
                        if isinstance(item, dict) and item.get("path")
                    }
                else:
                    errors.append({"id": "manifest-invalid", "path": "PUBLIC_PACKAGE_MANIFEST.json", "detail": "manifest must contain a JSON object"})
            except Exception as exc:  # noqa: BLE001 - report shape only
                errors.append({"id": "manifest-invalid-json", "path": "PUBLIC_PACKAGE_MANIFEST.json", "detail": str(exc)})

    file_set = set(files)
    for rel in sorted(required_files - file_set):
        errors.append({"id": "required-file-missing", "path": rel, "detail": "required public package file is missing"})
    for rel in files:
        if any(rel == prefix.rstrip("/") or rel.startswith(prefix) for prefix in forbidden_prefixes):
            errors.append({"id": "forbidden-path-present", "path": rel, "detail": "private or runtime path is present in public package"})
        if is_private_instance_rel(rel):
            errors.append({"id": "private-instance-present", "path": rel, "detail": "only instances/example-* may be present in public package"})
    if manifest and manifest.get("schema") != "homenet.public_package.v1":
        errors.append({"id": "manifest-schema", "path": "PUBLIC_PACKAGE_MANIFEST.json", "detail": "unexpected package manifest schema"})
    if manifest and not manifest.get("package_ready"):
        errors.append({"id": "manifest-not-ready", "path": "PUBLIC_PACKAGE_MANIFEST.json", "detail": "manifest package_ready is not true"})
    if manifest_included:
        missing_from_manifest = sorted(file_set - manifest_included - {"PUBLIC_PACKAGE_MANIFEST.json"})
        missing_from_disk = sorted(manifest_included - file_set)
        for rel in missing_from_disk:
            errors.append({"id": "manifest-file-missing-on-disk", "path": rel, "detail": "manifest lists a file that is absent"})
        for rel in missing_from_manifest:
            warnings.append({"id": "extra-file-not-in-manifest", "path": rel, "detail": "file exists but is not listed in manifest"})

    return {
        "schema": "homenet.public_package_check.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "dir": str(output_dir) if output_dir else "",
        "ok": not errors,
        "summary": {
            "files": len(files),
            "required_files": len(required_files),
            "missing_required": sum(1 for item in errors if item.get("id") == "required-file-missing"),
            "forbidden_paths": sum(1 for item in errors if item.get("id") == "forbidden-path-present"),
            "manifest_files": len(manifest_included),
            "ignored_prefixes": len(ignored_prefixes),
            "warnings": len(warnings),
            "errors": len(errors),
        },
        "required_files": sorted(required_files),
        "forbidden_prefixes": sorted(forbidden_prefixes),
        "ignored_prefixes": sorted(ignored_prefixes),
        "errors": errors,
        "warnings": warnings,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "file_contents_scanned": False,
            "note": "Package check validates paths, manifest shape, and required public files only; it does not read package file contents except PUBLIC_PACKAGE_MANIFEST.json.",
        },
    }


def print_public_package_check_markdown(report: dict[str, Any]) -> None:
    print("# Public Package Check")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- ok: {report.get('ok')}")
    print(f"- dir: `{report.get('dir')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in (report.get("summary") or {}).items():
        print(f"- {key}: {value}")
    print()
    if report.get("errors"):
        print("## Errors")
        print()
        print("| ID | Path | Detail |")
        print("| --- | --- | --- |")
        for item in as_list(report.get("errors")):
            if isinstance(item, dict):
                print(f"| {item.get('id', '')} | `{item.get('path', '')}` | {item.get('detail', '')} |")
        print()
    if report.get("warnings"):
        print("## Warnings")
        print()
        print("| ID | Path | Detail |")
        print("| --- | --- | --- |")
        for item in as_list(report.get("warnings")):
            if isinstance(item, dict):
                print(f"| {item.get('id', '')} | `{item.get('path', '')}` | {item.get('detail', '')} |")
        print()


def run_package_smoke_command(output_dir: Path, args: list[str], *, timeout: int = 45) -> dict[str, Any]:
    homenet = output_dir / "homenet"
    env = dict(os.environ)
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    result: dict[str, Any] = {
        "command": ["./homenet", *args],
        "ok": False,
        "returncode": None,
        "summary": {},
        "error": "",
    }
    try:
        completed = subprocess.run(
            [str(homenet), *args],
            cwd=output_dir,
            env=env,
            text=True,
            capture_output=True,
            timeout=timeout,
            check=False,
        )
    except subprocess.TimeoutExpired:
        result["error"] = f"timeout after {timeout}s"
        return result
    except Exception as exc:  # noqa: BLE001 - command smoke result
        result["error"] = str(exc)
        return result

    result["returncode"] = completed.returncode
    stdout = completed.stdout.strip()
    stderr = completed.stderr.strip()
    if stderr:
        result["stderr"] = stderr[:400]
    try:
        parsed = json.loads(stdout) if stdout else {}
    except json.JSONDecodeError:
        parsed = {}
        if stdout:
            result["stdout"] = stdout[:400]
    result["ok"] = completed.returncode == 0 and (not isinstance(parsed, dict) or parsed.get("ok", True) is not False)
    if isinstance(parsed, dict):
        summary = parsed.get("summary") if isinstance(parsed.get("summary"), dict) else {}
        result["schema"] = parsed.get("schema")
        result["summary"] = {
            "ok": parsed.get("ok"),
            **summary,
        }
        if parsed.get("schema") == "homenet.public_package.v1":
            result["summary"]["source"] = summary.get("source")
            result["summary"]["package_ready"] = parsed.get("package_ready")
        if parsed.get("schema") == "homenet.ci.v1":
            result["summary"]["ci_ok"] = parsed.get("ok")
            result["summary"]["failures"] = summary.get("failures")
            result["summary"]["checks"] = summary.get("checks")
            result["summary"]["public_package_files"] = summary.get("public_package_files")
    return result


def build_public_package_smoke(output_dir: Path | None) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    commands: list[dict[str, Any]] = []
    if output_dir is None:
        errors.append({"id": "output-dir-required", "path": "", "detail": "--dir is required"})
    elif not output_dir.exists():
        errors.append({"id": "output-dir-missing", "path": str(output_dir), "detail": "directory does not exist"})
    elif not output_dir.is_dir():
        errors.append({"id": "output-dir-not-directory", "path": str(output_dir), "detail": "path is not a directory"})
    elif not (output_dir / "homenet").is_file():
        errors.append({"id": "homenet-missing", "path": "homenet", "detail": "exported CLI entrypoint is missing"})
    else:
        command_args = [
            ["package-check", "--dir", str(output_dir), "--format", "json"],
            ["package", "--instance", "instances/example-openwrt-pi", "--format", "json"],
            ["check", "--instance", "instances/example-openwrt-pi"],
            ["check", "--instance", "instances/example-openwrt-only"],
        ]
        for args in command_args:
            row = run_package_smoke_command(output_dir, args)
            commands.append(row)
            if not row.get("ok"):
                errors.append({
                    "id": "command-failed",
                    "path": " ".join(str(part) for part in row.get("command", [])),
                    "detail": row.get("error") or row.get("stderr") or f"returncode={row.get('returncode')}",
                })
    return {
        "schema": "homenet.public_package_smoke.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "dir": str(output_dir) if output_dir else "",
        "ok": not errors,
        "summary": {
            "commands": len(commands),
            "passed": sum(1 for row in commands if row.get("ok")),
            "failed": sum(1 for row in commands if not row.get("ok")),
            "errors": len(errors),
        },
        "commands": commands,
        "errors": errors,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Package smoke executes read-only exported package commands and records status summaries only.",
        },
    }


def print_public_package_smoke_markdown(report: dict[str, Any]) -> None:
    print("# Public Package Smoke")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- ok: {report.get('ok')}")
    print(f"- dir: `{report.get('dir')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in (report.get("summary") or {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Commands")
    print()
    print("| Command | OK | Return | Summary |")
    print("| --- | --- | --- | --- |")
    for row in as_list(report.get("commands")):
        if not isinstance(row, dict):
            continue
        summary = row.get("summary") if isinstance(row.get("summary"), dict) else {}
        parts = [f"{key}={value}" for key, value in summary.items() if value is not None]
        print(f"| `{' '.join(as_list(row.get('command')))}` | {row.get('ok')} | {row.get('returncode')} | {', '.join(parts)} |")
    print()
    if report.get("errors"):
        print("## Errors")
        print()
        for item in as_list(report.get("errors")):
            if isinstance(item, dict):
                print(f"- {item.get('id')}: `{item.get('path')}` - {item.get('detail')}")
        print()


def _is_safe_tmp_path(path: Path) -> bool:
    try:
        path.resolve().relative_to(Path("/tmp").resolve())
        return True
    except ValueError:
        return False


def prepare_package_onboarding_work_dir(work_dir: Path, *, force: bool) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    if work_dir.exists() and not work_dir.is_dir():
        return [{"id": "work-dir-not-directory", "path": str(work_dir), "detail": "path exists but is not a directory"}]
    if work_dir.exists() and any(work_dir.iterdir()):
        if not force:
            return [{"id": "work-dir-not-empty", "path": str(work_dir), "detail": "use --force to replace this temporary onboarding workspace"}]
        if not _is_safe_tmp_path(work_dir):
            return [{"id": "unsafe-work-dir", "path": str(work_dir), "detail": "--force may only replace directories under /tmp"}]
        shutil.rmtree(work_dir)
    try:
        work_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:  # noqa: BLE001 - report shape
        errors.append({"id": "work-dir-create-failed", "path": str(work_dir), "detail": str(exc)})
    return errors


def build_public_package_onboarding(output_dir: Path | None, work_dir: Path | None, *, force: bool) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    commands: list[dict[str, Any]] = []
    generated_instances: list[dict[str, Any]] = []
    resolved_work_dir = work_dir or Path("/tmp/homenet-package-onboarding")

    package_check = build_public_package_check(output_dir)
    for item in as_list(package_check.get("errors")):
        if isinstance(item, dict):
            errors.append({"id": f"package-check:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})

    if output_dir is None:
        errors.append({"id": "output-dir-required", "path": "", "detail": "--dir is required"})
    elif not output_dir.exists():
        errors.append({"id": "output-dir-missing", "path": str(output_dir), "detail": "directory does not exist"})
    elif not output_dir.is_dir():
        errors.append({"id": "output-dir-not-directory", "path": str(output_dir), "detail": "path is not a directory"})
    elif not (output_dir / "homenet").is_file():
        errors.append({"id": "homenet-missing", "path": "homenet", "detail": "exported CLI entrypoint is missing"})

    if not errors:
        errors.extend(prepare_package_onboarding_work_dir(resolved_work_dir.resolve(), force=force))

    if not errors and output_dir is not None:
        scenarios = [
            ("generated-openwrt-pi", "openwrt-pi"),
            ("generated-openwrt-only", "openwrt-only"),
        ]
        for name, profile in scenarios:
            instance_dir = resolved_work_dir.resolve() / name
            new_args = [
                "init",
                "--yes",
                "--name",
                name,
                "--profile",
                profile,
                "--output",
                str(instance_dir),
                "--force",
            ]
            new_result = run_package_smoke_command(output_dir, new_args, timeout=45)
            commands.append(new_result)
            generated_instances.append({
                "name": name,
                "profile": profile,
                "path": str(instance_dir),
                "created": bool(new_result.get("ok") and instance_dir.exists()),
            })
            if not new_result.get("ok"):
                errors.append({
                    "id": "init-instance-failed",
                    "path": " ".join(str(part) for part in new_result.get("command", [])),
                    "detail": new_result.get("error") or new_result.get("stderr") or f"returncode={new_result.get('returncode')}",
                })
                continue
            check_args = ["check", "--instance", str(instance_dir)]
            check_result = run_package_smoke_command(output_dir, check_args, timeout=45)
            commands.append(check_result)
            if not check_result.get("ok"):
                errors.append({
                    "id": "generated-check-failed",
                    "path": " ".join(str(part) for part in check_result.get("command", [])),
                    "detail": check_result.get("error") or check_result.get("stderr") or f"returncode={check_result.get('returncode')}",
                })

    return {
        "schema": "homenet.public_package_onboarding.v1",
        "read_only": False,
        "writes_files": True,
        "writes_live_config": False,
        "dir": str(output_dir) if output_dir else "",
        "work_dir": str(resolved_work_dir.resolve()),
        "ok": not errors,
        "summary": {
            "commands": len(commands),
            "passed": sum(1 for row in commands if row.get("ok")),
            "failed": sum(1 for row in commands if not row.get("ok")),
            "generated_instances": len(generated_instances),
            "errors": len(errors),
        },
        "generated_instances": generated_instances,
        "commands": commands,
        "errors": errors,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Onboarding smoke writes only generated example instances into the requested work directory and records command summaries only.",
        },
    }


