def _publish_audit_check(check_id: str, status: str, detail: str, *, evidence: dict[str, Any] | None = None) -> dict[str, Any]:
    return {
        "id": check_id,
        "status": status,
        "ok": status != "fail",
        "detail": detail,
        "evidence": evidence or {},
    }


def build_public_publish_audit(
    instance: Path,
    output_dir: Path | None,
    repo_dir: Path | None,
    work_dir: Path | None,
    *,
    force: bool,
    run_publish_check: bool,
) -> dict[str, Any]:
    release = build_release_manifest(instance)
    package = build_public_package_manifest(instance)
    checks: list[dict[str, Any]] = []
    blockers: list[dict[str, str]] = []
    warnings: list[dict[str, str]] = []

    def add_blocker(blocker_id: str, detail: str) -> None:
        blockers.append({"id": blocker_id, "detail": detail})

    def add_warning(warning_id: str, detail: str) -> None:
        warnings.append({"id": warning_id, "detail": detail})

    release_summary = release.get("summary") if isinstance(release.get("summary"), dict) else {}
    package_summary = package.get("summary") if isinstance(package.get("summary"), dict) else {}
    checks.append(_publish_audit_check(
        "public-release-boundary",
        "pass" if release.get("public_core_ready") else "fail",
        "public core release boundary is ready" if release.get("public_core_ready") else "public core release boundary is not ready",
        evidence={
            "public_privacy_findings": release_summary.get("public_privacy_findings"),
            "example_failures": release_summary.get("example_failures"),
        },
    ))
    if not release.get("public_core_ready"):
        add_blocker("public-release-boundary", "release reports public_core_ready=false")

    checks.append(_publish_audit_check(
        "whole-worktree-boundary",
        "warn",
        "the mixed private workspace is intentionally not publishable; publish only an exported public package",
        evidence={"whole_worktree_publishable": release.get("whole_worktree_publishable")},
    ))
    add_warning("whole-worktree-boundary", "publish only the exported public package, not the mixed private workspace")

    public_privacy_findings = int(release_summary.get("public_privacy_findings") or 0)
    checks.append(_publish_audit_check(
        "public-privacy",
        "pass" if public_privacy_findings == 0 else "fail",
        "public roots have no private-value findings" if public_privacy_findings == 0 else "public roots have privacy findings",
        evidence={"findings": public_privacy_findings},
    ))
    if public_privacy_findings:
        add_blocker("public-privacy", "public privacy scan has findings")

    instance_privacy_findings = int(release_summary.get("instance_privacy_findings") or 0)
    checks.append(_publish_audit_check(
        "private-instance-contained",
        "pass" if instance_privacy_findings == 0 else "warn",
        "selected instance does not add privacy findings to the current scan" if instance_privacy_findings == 0 else "private instance has private findings and must stay excluded",
        evidence={"findings": instance_privacy_findings},
    ))
    if instance_privacy_findings:
        add_warning("private-instance-contained", "private instance findings are acceptable only because private instance roots are excluded")

    checks.append(_publish_audit_check(
        "public-package-manifest",
        "pass" if package.get("package_ready") else "fail",
        "public package manifest can be built" if package.get("package_ready") else "public package manifest is not ready",
        evidence={
            "included_files": package_summary.get("included_files"),
            "excluded_tracked_files": package_summary.get("excluded_tracked_files"),
        },
    ))
    if not package.get("package_ready"):
        add_blocker("public-package-manifest", "package reports package_ready=false")

    included_paths = {str(row.get("path") or "") for row in as_list(package.get("included_files")) if isinstance(row, dict)}
    for rel in ["LICENSE", "CONTRIBUTING.md", "SECURITY.md", "PUBLISHING.md"]:
        checks.append(_publish_audit_check(
            f"required-file-{rel.lower().replace('.', '-')}",
            "pass" if rel in included_paths else "fail",
            f"{rel} is included in the public package manifest" if rel in included_paths else f"{rel} is missing from the public package manifest",
            evidence={"path": rel},
        ))
        if rel not in included_paths:
            add_blocker(f"required-file-{rel}", f"{rel} must be included before public publishing")

    example_failures = int(release_summary.get("example_failures") or 0)
    checks.append(_publish_audit_check(
        "public-examples",
        "pass" if example_failures == 0 else "fail",
        "public example instances validate" if example_failures == 0 else "one or more public examples fail validation",
        evidence={"examples": release_summary.get("examples"), "example_failures": example_failures},
    ))
    if example_failures:
        add_blocker("public-examples", "public example validation has failures")

    package_check: dict[str, Any] | None = None
    if output_dir is None:
        checks.append(_publish_audit_check(
            "exported-package",
            "warn",
            "no --dir was provided, so an exported package directory was not verified",
        ))
        add_warning("exported-package", "run package --output-dir and audit the exported directory before publishing")
    else:
        package_check = build_public_package_check(output_dir)
        checks.append(_publish_audit_check(
            "exported-package",
            "pass" if package_check.get("ok") else "fail",
            "exported package directory passes package-check" if package_check.get("ok") else "exported package directory fails package-check",
            evidence=package_check.get("summary") if isinstance(package_check.get("summary"), dict) else {},
        ))
        if not package_check.get("ok"):
            add_blocker("exported-package", "provided --dir does not pass package-check")

    repo_info: dict[str, Any] | None = None
    if repo_dir is None:
        checks.append(_publish_audit_check(
            "public-repo",
            "warn",
            "no --repo-dir was provided, so a public git repo review was not verified",
        ))
        add_warning("public-repo", "run repo-init or provide --repo-dir before final publish")
    else:
        repo_info = git_workspace_info(repo_dir)
        repo_ok = bool(repo_info.get("git_repo")) and not bool(repo_info.get("dirty")) and bool(repo_info.get("commit"))
        checks.append(_publish_audit_check(
            "public-repo",
            "pass" if repo_ok else "fail",
            "public repo directory is a clean git repo with a commit" if repo_ok else "public repo directory is missing, not a git repo, dirty, or has no commit",
            evidence={
                "exists": repo_info.get("exists"),
                "git_repo": repo_info.get("git_repo"),
                "dirty": repo_info.get("dirty"),
                "changes": repo_info.get("changes"),
                "commit_short": repo_info.get("commit_short"),
            },
        ))
        if not repo_ok:
            add_blocker("public-repo", "provided --repo-dir is not clean publishable evidence")

    publish_check: dict[str, Any] | None = None
    writes_files = False
    resolved_work_dir = work_dir or Path("/tmp/homenet-publish-audit")
    if run_publish_check:
        publish_check = build_public_publish_check(output_dir, resolved_work_dir, force=force)
        writes_files = bool(publish_check.get("writes_files"))
        checks.append(_publish_audit_check(
            "publish-check",
            "pass" if publish_check.get("ok") else "fail",
            "full exported package publish-check passed" if publish_check.get("ok") else "full exported package publish-check failed",
            evidence=publish_check.get("summary") if isinstance(publish_check.get("summary"), dict) else {},
        ))
        if not publish_check.get("ok"):
            add_blocker("publish-check", "full exported package publish-check failed")
    else:
        checks.append(_publish_audit_check(
            "publish-check",
            "info",
            "not run in this audit; pass --run-publish-check to execute the full exported package gate",
        ))
        add_warning("publish-check", "final review should run publish-check on the exported package")

    for row in as_list(release.get("review_required")):
        if isinstance(row, dict):
            add_warning(f"review-required:{row.get('path')}", str(row.get("reason") or "manual review required"))

    publish_check_verified = bool(run_publish_check and publish_check and publish_check.get("ok"))
    ready_for_public_repo = (
        not blockers
        and output_dir is not None
        and package_check is not None
        and package_check.get("ok")
        and repo_dir is not None
        and repo_info is not None
        and repo_info.get("git_repo")
        and not repo_info.get("dirty")
        and publish_check_verified
    )
    next_actions: list[str] = []
    if output_dir is None:
        next_actions.append(f"./homenet package --instance {instance} --output-dir /tmp/homenet-public --force")
    elif not publish_check_verified:
        next_actions.append(f"./homenet publish-check --dir {output_dir} --work-dir /tmp/homenet-publish-check --force")
    if output_dir is not None and repo_dir is None:
        next_actions.append(f"./homenet repo-init --dir {output_dir} --repo-dir /tmp/homenet-public-repo --force")
    elif repo_dir is not None:
        next_actions.append(f"./homenet repo-publish --instance {instance} --dir {output_dir or repo_dir} --repo-dir {repo_dir} --remote <public-repo-url> --confirm-push PUSH-HOMENET-PUBLIC --force")
    next_actions.append("publish only the clean public repo/package; keep private instance, runtime data, and sub/ excluded")
    next_actions.append("HomeNet Ops source is included under apps/ops; keep only runtime mounts and private data out of public git")

    return {
        "schema": "homenet.public_publish_audit.v1",
        "read_only": not run_publish_check,
        "writes_files": writes_files,
        "writes_live_config": False,
        "instance": str(instance),
        "dir": str(output_dir) if output_dir else "",
        "repo_dir": str(repo_dir) if repo_dir else "",
        "work_dir": str(resolved_work_dir.resolve()) if run_publish_check else "",
        "public_core_ready": bool(release.get("public_core_ready")),
        "ready_for_public_repo": bool(ready_for_public_repo),
        "summary": {
            "checks": len(checks),
            "passed": sum(1 for row in checks if row.get("status") == "pass"),
            "warnings": len(warnings),
            "blockers": len(blockers),
            "public_package_ready": bool(package.get("package_ready")),
            "exported_package_checked": output_dir is not None,
            "public_repo_checked": repo_dir is not None,
            "publish_check_run": bool(run_publish_check),
            "publish_check_verified": publish_check_verified,
        },
        "checks": checks,
        "blockers": blockers,
        "warnings": warnings,
        "next_actions": next_actions,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Audit reports only aggregate readiness, paths, and counts. It does not print secret values or inspect excluded runtime data.",
        },
    }


