def run_public_repo_git_command(repo_dir: Path, args: list[str], *, timeout: int = 60) -> dict[str, Any]:
    result: dict[str, Any] = {
        "command": ["git", *args],
        "ok": False,
        "returncode": None,
        "error": "",
    }
    try:
        completed = subprocess.run(
            ["git", *args],
            cwd=repo_dir,
            text=True,
            capture_output=True,
            timeout=timeout,
            check=False,
        )
    except subprocess.TimeoutExpired:
        result["error"] = f"timeout after {timeout}s"
        return result
    except Exception as exc:  # noqa: BLE001 - command result
        result["error"] = str(exc)
        return result
    result["returncode"] = completed.returncode
    result["ok"] = completed.returncode == 0
    stdout = completed.stdout.strip()
    stderr = completed.stderr.strip()
    if stdout:
        result["stdout"] = stdout[:400]
    if stderr:
        result["stderr"] = stderr[:400]
    return result


def copy_public_package_to_repo(output_dir: Path, repo_dir: Path) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    try:
        for item in output_dir.iterdir():
            target = repo_dir / item.name
            if item.name == ".git":
                continue
            if item.is_dir():
                shutil.copytree(item, target, dirs_exist_ok=True)
            else:
                shutil.copy2(item, target)
    except Exception as exc:  # noqa: BLE001 - report shape
        errors.append({"id": "copy-failed", "path": str(repo_dir), "detail": str(exc)})
    return errors


def build_public_repo_init(
    output_dir: Path | None,
    repo_dir: Path | None,
    work_dir: Path | None,
    *,
    force: bool,
    run_publish_check: bool,
    commit_message: str,
) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    commands: list[dict[str, Any]] = []
    resolved_repo_dir = repo_dir or Path("/tmp/homenet-public-repo")
    resolved_work_dir = work_dir or Path("/tmp/homenet-repo-init-check")

    precheck = (
        build_public_publish_check(output_dir, resolved_work_dir, force=force)
        if run_publish_check
        else build_public_repo_review_check(output_dir)
    )
    if not precheck.get("ok"):
        for item in as_list(precheck.get("errors")):
            if isinstance(item, dict):
                errors.append({"id": f"precheck:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})

    if output_dir is None:
        errors.append({"id": "output-dir-required", "path": "", "detail": "--dir is required"})
    elif not output_dir.exists():
        errors.append({"id": "output-dir-missing", "path": str(output_dir), "detail": "directory does not exist"})
    elif not output_dir.is_dir():
        errors.append({"id": "output-dir-not-directory", "path": str(output_dir), "detail": "path is not a directory"})

    repo_dir_resolved = resolved_repo_dir.resolve()
    if output_dir is not None:
        output_resolved = output_dir.resolve()
        if repo_dir_resolved == output_resolved:
            errors.append({"id": "repo-dir-same-as-package", "path": str(repo_dir_resolved), "detail": "--repo-dir must be separate from --dir"})
        else:
            try:
                repo_dir_resolved.relative_to(output_resolved)
                errors.append({"id": "repo-dir-inside-package", "path": str(repo_dir_resolved), "detail": "--repo-dir must not be inside the exported package"})
            except ValueError:
                pass
    if not errors:
        errors.extend(prepare_package_onboarding_work_dir(repo_dir_resolved, force=force))
    if not errors and output_dir is not None:
        errors.extend(copy_public_package_to_repo(output_dir, repo_dir_resolved))

    if not errors:
        init_result = run_public_repo_git_command(repo_dir_resolved, ["init", "-b", "main"])
        if not init_result.get("ok"):
            init_result = run_public_repo_git_command(repo_dir_resolved, ["init"])
            warnings.append({"id": "git-init-default-branch", "path": str(repo_dir_resolved), "detail": "git init -b main failed; used default branch init"})
        commands.append(init_result)
        if not init_result.get("ok"):
            errors.append({"id": "git-init-failed", "path": str(repo_dir_resolved), "detail": init_result.get("error") or init_result.get("stderr") or f"returncode={init_result.get('returncode')}"})

    if not errors:
        add_result = run_public_repo_git_command(repo_dir_resolved, ["add", "."])
        commands.append(add_result)
        if not add_result.get("ok"):
            errors.append({"id": "git-add-failed", "path": str(repo_dir_resolved), "detail": add_result.get("error") or add_result.get("stderr") or f"returncode={add_result.get('returncode')}"})

    if not errors:
        commit_args = [
            "-c",
            "user.name=HomeNet Package",
            "-c",
            "user.email=homenet.invalid",
            "commit",
            "-m",
            commit_message,
        ]
        commit_result = run_public_repo_git_command(repo_dir_resolved, commit_args, timeout=120)
        commands.append(commit_result)
        if not commit_result.get("ok"):
            errors.append({"id": "git-commit-failed", "path": str(repo_dir_resolved), "detail": commit_result.get("error") or commit_result.get("stderr") or f"returncode={commit_result.get('returncode')}"})

    git_info = git_workspace_info(repo_dir_resolved) if repo_dir_resolved.exists() else {}
    return {
        "schema": "homenet.public_repo_init.v1",
        "read_only": False,
        "writes_files": True,
        "writes_live_config": False,
        "dir": str(output_dir) if output_dir else "",
        "repo_dir": str(repo_dir_resolved),
        "work_dir": str(resolved_work_dir.resolve()),
        "ok": not errors,
        "summary": {
            "precheck_ok": bool(precheck.get("ok")),
            "precheck_schema": precheck.get("schema"),
            "run_publish_check": run_publish_check,
            "commands": len(commands),
            "passed": sum(1 for row in commands if row.get("ok")),
            "failed": sum(1 for row in commands if not row.get("ok")),
            "errors": len(errors),
            "warnings": len(warnings),
            "repo_initialized": bool(git_info.get("git_repo")),
            "repo_dirty": git_info.get("dirty") if git_info else None,
            "commit": git_info.get("commit_short") if git_info else "",
        },
        "publish_check": _public_check_row("precheck", precheck),
        "git": git_info,
        "commands": commands,
        "errors": errors,
        "warnings": warnings,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Repo init copies an already checked public package into a local git repository and records git command summaries only.",
        },
    }


def print_public_repo_init_markdown(report: dict[str, Any]) -> None:
    print("# Public Repo Init")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- ok: {report.get('ok')}")
    print(f"- package dir: `{report.get('dir')}`")
    print(f"- repo dir: `{report.get('repo_dir')}`")
    print(f"- work dir: `{report.get('work_dir')}`")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in (report.get("summary") or {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Commands")
    print()
    print("| Command | OK | Return |")
    print("| --- | --- | --- |")
    for row in as_list(report.get("commands")):
        if isinstance(row, dict):
            print(f"| `{' '.join(as_list(row.get('command')))}` | {row.get('ok')} | {row.get('returncode')} |")
    print()
    if report.get("errors"):
        print("## Errors")
        print()
        for item in as_list(report.get("errors")):
            if isinstance(item, dict):
                print(f"- {item.get('id')}: `{item.get('path')}` - {item.get('detail')}")
        print()


def build_public_repo_plan(output_dir: Path | None) -> dict[str, Any]:
    package_check = build_public_package_check(output_dir)
    errors: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    git_info: dict[str, Any] = {}
    manifest_summary: dict[str, Any] = {}
    repo_initialized = False
    repo_dirty = None

    if output_dir is None:
        errors.append({"id": "output-dir-required", "path": "", "detail": "--dir is required"})
    elif not output_dir.exists():
        errors.append({"id": "output-dir-missing", "path": str(output_dir), "detail": "directory does not exist"})
    elif not output_dir.is_dir():
        errors.append({"id": "output-dir-not-directory", "path": str(output_dir), "detail": "path is not a directory"})
    else:
        manifest = load_exported_package_manifest(output_dir)
        if isinstance(manifest, dict):
            summary = manifest.get("summary") if isinstance(manifest.get("summary"), dict) else {}
            manifest_summary = {
                "schema": manifest.get("schema"),
                "package_ready": manifest.get("package_ready"),
                "included_files": summary.get("included_files"),
                "source": summary.get("source"),
                "whole_worktree_publishable": summary.get("whole_worktree_publishable"),
            }
        git_info = git_workspace_info(output_dir)
        repo_initialized = bool(git_info.get("git_repo"))
        repo_dirty = git_info.get("dirty") if repo_initialized else None
        if repo_initialized and git_info.get("dirty"):
            warnings.append({"id": "repo-dirty", "path": ".git", "detail": "public repo has uncommitted changes"})
        instances_dir = output_dir / "instances"
        if instances_dir.exists():
            for path in sorted(instances_dir.iterdir(), key=lambda item: item.name):
                if path.is_dir() and not path.name.startswith("example-"):
                    errors.append({"id": "private-instance-present", "path": f"instances/{path.name}", "detail": "only instances/example-* may be present in public repo"})

    for item in as_list(package_check.get("errors")):
        if isinstance(item, dict):
            errors.append({"id": f"package-check:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})
    for item in as_list(package_check.get("warnings")):
        if isinstance(item, dict):
            warnings.append({"id": f"package-check:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})

    steps = [
        {
            "id": "export-package",
            "command": "./homenet package --instance instances/my-home --output-dir /tmp/homenet-public --force",
            "purpose": "Create the sanitized public core package from the mixed private workspace.",
            "run_from": "private workspace root",
        },
        {
            "id": "check-package",
            "command": f"./homenet package-check --dir {output_dir}" if output_dir else "./homenet package-check --dir <public-package-dir>",
            "purpose": "Validate required files and confirm private/runtime paths are absent.",
            "run_from": "private workspace root or any machine with the package",
        },
        {
            "id": "smoke-package",
            "command": f"./homenet package-smoke --dir {output_dir}" if output_dir else "./homenet package-smoke --dir <public-package-dir>",
            "purpose": "Run read-only package and example CI commands inside the exported package.",
            "run_from": "private workspace root or any machine with the package",
        },
        {
            "id": "onboard-from-package",
            "command": f"./homenet package-onboarding --dir {output_dir} --work-dir /tmp/homenet-package-onboarding --force" if output_dir else "./homenet package-onboarding --dir <public-package-dir> --work-dir /tmp/homenet-package-onboarding --force",
            "purpose": "Generate fresh OpenWrt-only and OpenWrt+server instances from the exported package and run CI on them.",
            "run_from": "private workspace root or any machine with the package",
        },
        {
            "id": "publish-check",
            "command": f"./homenet publish-check --dir {output_dir} --work-dir /tmp/homenet-publish-check --force" if output_dir else "./homenet publish-check --dir <public-package-dir> --work-dir /tmp/homenet-publish-check --force",
            "purpose": "Run the aggregate review gate before creating or publishing a public repo.",
            "run_from": "private workspace root or any machine with the package",
        },
        {
            "id": "init-local-public-repo",
            "command": f"./homenet repo-init --dir {output_dir} --repo-dir /tmp/homenet-public-repo --force" if output_dir else "./homenet repo-init --dir <public-package-dir> --repo-dir /tmp/homenet-public-repo --force",
            "purpose": "Copy the checked package into a local git repository and create the initial commit.",
            "run_from": "private workspace root or any machine with the package",
        },
        {
            "id": "publish-public-repo",
            "command": "./homenet repo-publish --dir <public-package-dir> --repo-dir /tmp/homenet-public-repo --remote <public-repo-url> --confirm-push PUSH-HOMENET-PUBLIC --force",
            "purpose": "Audit again, then publish only the initialized public repo, not the mixed private workspace.",
            "run_from": "/tmp/homenet-public-repo or the repo-init --repo-dir path",
        },
    ]
    return {
        "schema": "homenet.public_repo_plan.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "dir": str(output_dir) if output_dir else "",
        "ok": not errors,
        "summary": {
            "package_check_ok": package_check.get("ok"),
            "repo_initialized": repo_initialized,
            "repo_dirty": repo_dirty,
            "steps": len(steps),
            "warnings": len(warnings),
            "errors": len(errors),
        },
        "manifest": manifest_summary,
        "git": git_info,
        "steps": steps,
        "rules": [
            "Do not publish the mixed private workspace as the public repo.",
            "Publish only the exported package after package-check, package-smoke, and package-onboarding pass.",
            "Keep real instances, runtime data, secrets, service databases, backups, and private subscription projects out of the public repo.",
            "HomeNet Ops source under apps/ops is part of the public root; keep only private runtime data out of the public repo.",
        ],
        "errors": errors,
        "warnings": warnings,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Repo plan reads package path names, package manifest summary, and git status only.",
        },
    }


