def build_public_release_candidate(
    instance: Path,
    output_dir: Path,
    repo_dir: Path,
    work_dir: Path | None,
    *,
    force: bool,
    run_publish_check: bool,
    remote_url: str,
) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    resolved_work_dir = work_dir or Path("/tmp/homenet-release-candidate-check")

    package_write = write_public_package_output(instance, output_dir, force=force)
    if not package_write.get("ok"):
        for item in as_list(package_write.get("errors")):
            if isinstance(item, dict):
                errors.append({"id": f"package:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})

    package_check = build_public_package_check(output_dir) if not errors else {}
    if package_check and not package_check.get("ok"):
        for item in as_list(package_check.get("errors")):
            if isinstance(item, dict):
                errors.append({"id": f"package-check:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})

    repo_init: dict[str, Any] = {}
    if not errors:
        repo_init = build_public_repo_init(
            output_dir,
            repo_dir,
            resolved_work_dir,
            force=force,
            run_publish_check=False,
            commit_message="Initial HomeNet public package",
        )
        if not repo_init.get("ok"):
            for item in as_list(repo_init.get("errors")):
                if isinstance(item, dict):
                    errors.append({"id": f"repo-init:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})

    audit: dict[str, Any] = {}
    if not errors:
        audit = build_public_publish_audit(
            instance,
            output_dir,
            repo_dir,
            resolved_work_dir,
            force=force,
            run_publish_check=run_publish_check,
        )
        for item in as_list(audit.get("blockers")):
            if isinstance(item, dict):
                errors.append({"id": f"audit:{item.get('id')}", "path": "", "detail": str(item.get("detail") or "")})

    repo_publish: dict[str, Any] = {}
    if remote_url and not errors:
        repo_publish = build_public_repo_publish(
            instance,
            output_dir,
            repo_dir,
            resolved_work_dir,
            remote_url=remote_url,
            branch="main",
            force=force,
            replace_remote=False,
            run_publish_check=run_publish_check,
            confirm_push="",
        )
        if not repo_publish.get("ok") and not repo_publish.get("ready_to_push"):
            for item in as_list(repo_publish.get("errors")):
                if isinstance(item, dict):
                    errors.append({"id": f"repo-publish:{item.get('id')}", "path": item.get("path", ""), "detail": item.get("detail", "")})
    elif not remote_url:
        warnings.append({"id": "remote-missing", "path": "", "detail": "no public remote was provided; candidate stops before push plan"})

    repo_info = git_workspace_info(repo_dir)
    publish_check_verified = bool((audit.get("summary") or {}).get("publish_check_verified")) if isinstance(audit.get("summary"), dict) else False
    package_check_ok = bool(package_check.get("ok")) if package_check else False
    ready_for_remote = bool(not errors and package_write.get("ok") and package_check_ok)
    ready_for_remote = bool(
        ready_for_remote
        and repo_info.get("git_repo")
        and not repo_info.get("dirty")
        and not as_list(audit.get("blockers"))
    )
    next_actions = []
    if remote_url:
        next_actions.append(f"./homenet repo-publish --instance {instance} --dir {output_dir} --repo-dir {repo_dir} --remote <public-repo-url> --confirm-push PUSH-HOMENET-PUBLIC --force")
    else:
        next_actions.append(f"./homenet repo-publish --instance {instance} --dir {output_dir} --repo-dir {repo_dir} --remote <public-repo-url> --confirm-push PUSH-HOMENET-PUBLIC --force")
    if not run_publish_check:
        next_actions.insert(0, f"./homenet publish-check --dir {output_dir} --work-dir /tmp/homenet-publish-check --force")

    return {
        "schema": "homenet.public_release_candidate.v1",
        "read_only": False,
        "writes_files": True,
        "writes_live_config": False,
        "writes_remote_repo": False,
        "instance": str(instance),
        "dir": str(output_dir),
        "repo_dir": str(repo_dir),
        "work_dir": str(resolved_work_dir.resolve()),
        "ok": not errors,
        "ready_for_remote": ready_for_remote,
        "publish_check_verified": publish_check_verified,
        "summary": {
            "package_written": bool(package_write.get("ok")),
            "package_check_ok": bool(package_check.get("ok")) if package_check else False,
            "repo_initialized": bool(repo_info.get("git_repo")),
            "repo_dirty": repo_info.get("dirty") if repo_info else None,
            "repo_commit": repo_info.get("commit_short") if repo_info else "",
            "audit_blockers": len(as_list(audit.get("blockers"))) if audit else None,
            "publish_check_run": bool(run_publish_check),
            "publish_check_verified": publish_check_verified,
            "remote_plan_checked": bool(repo_publish),
            "errors": len(errors),
            "warnings": len(warnings),
        },
        "package": {
            "schema": package_write.get("schema"),
            "ok": package_write.get("ok"),
            "summary": package_write.get("summary") if isinstance(package_write.get("summary"), dict) else {},
        },
        "package_check": _public_check_row("package-check", package_check) if package_check else {},
        "repo_init": {
            "schema": repo_init.get("schema"),
            "ok": repo_init.get("ok"),
            "summary": repo_init.get("summary") if isinstance(repo_init.get("summary"), dict) else {},
        },
        "audit": {
            "schema": audit.get("schema"),
            "ready_for_public_repo": audit.get("ready_for_public_repo"),
            "blockers": len(as_list(audit.get("blockers"))) if audit else None,
            "summary": audit.get("summary") if isinstance(audit.get("summary"), dict) else {},
        },
        "repo_publish": {
            "schema": repo_publish.get("schema"),
            "ready_to_push": repo_publish.get("ready_to_push"),
            "push_enabled": repo_publish.get("push_enabled"),
            "pushed": repo_publish.get("pushed"),
            "summary": repo_publish.get("summary") if isinstance(repo_publish.get("summary"), dict) else {},
        } if repo_publish else {},
        "git": repo_info,
        "next_actions": next_actions,
        "errors": errors,
        "warnings": warnings,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Release candidate reports aggregate package, repo, and audit evidence only. It never pushes and never writes live network configuration.",
        },
    }


