def build_release_manifest(instance: Path) -> dict[str, Any]:
    public_privacy = build_privacy_report(instance, scope="public")
    instance_privacy = build_privacy_report(instance, scope="all")
    examples = []
    for example in discover_instances(include_private=False):
        reporter = Reporter()
        check_instance(example, reporter)
        failures = sum(1 for finding in reporter.findings if finding.level == "FAIL")
        warnings = sum(1 for finding in reporter.findings if finding.level == "WARN")
        examples.append({
            "name": example.name,
            "path": str(example),
            "ok": failures == 0,
            "failures": failures,
            "warnings": warnings,
        })
    example_failures = [row for row in examples if not row.get("ok")]
    included = [
        {
            "path": item,
            "exists": (ROOT / item).exists(),
            "file_count": release_file_count(ROOT / item, "included"),
            "purpose": "public HomeNet source, schemas, examples, docs, or review-only tooling",
        }
        for item in RELEASE_INCLUDED_ROOTS
    ]
    excluded = [
        {
            "path": item,
            "exists": (ROOT / item).exists(),
            "file_count": release_file_count(ROOT / item, "excluded"),
            "reason": "private deployment data, runtime state, generated cache, service database, credentials, backup, or private subscription project",
        }
        for item in [*RELEASE_EXCLUDED_ROOTS, *private_instance_roots()]
    ]
    return {
        "schema": "homenet.release.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "public_core_ready": bool(public_privacy.get("ok")) and not example_failures,
        "whole_worktree_publishable": False,
        "instance": str(instance),
        "summary": {
            "included_roots": len(included),
            "excluded_roots": len(excluded),
            "review_required": len(RELEASE_REVIEW_REQUIRED),
            "public_privacy_findings": public_privacy.get("summary", {}).get("findings", 0),
            "instance_privacy_findings": instance_privacy.get("summary", {}).get("findings", 0),
            "examples": len(examples),
            "example_failures": len(example_failures),
        },
        "included_roots": included,
        "excluded_roots": excluded,
        "review_required": RELEASE_REVIEW_REQUIRED,
        "public_examples": examples,
        "release_rules": [
            "Publish only the included public core roots, not the whole /home/pi/network worktree.",
            "Keep private deployment instances, runtime service data, backups, databases, and subscription-worker config out of public releases.",
            "Run homenet privacy --scope public and homenet publish-check before publishing.",
            "Use examples as public fixtures; keep real home deployment details in private instance files.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Release manifest contains paths, counts, and rules only. It does not read or print excluded file contents.",
        },
    }


