def git_command(path: Path, args: list[str]) -> tuple[str, str | None]:
    try:
        proc = subprocess.run(
            ["git", "-C", str(path), *args],
            check=False,
            capture_output=True,
            text=True,
            timeout=8,
        )
    except Exception as exc:  # noqa: BLE001 - version reporting should degrade gracefully
        return "", str(exc)
    if proc.returncode != 0:
        return "", (proc.stderr or proc.stdout or "git command failed").strip()
    return proc.stdout.strip(), None


def git_workspace_info(path: Path) -> dict[str, Any]:
    exists = path.exists()
    is_repo = (path / ".git").exists()
    if not exists or not is_repo:
        return {
            "path": str(path.relative_to(ROOT)) if path.is_absolute() and path.is_relative_to(ROOT) else str(path),
            "exists": exists,
            "git_repo": False,
            "branch": "",
            "commit": "",
            "commit_short": "",
            "dirty": False,
            "changes": 0,
            "error": "" if exists else "path missing",
        }

    branch, branch_error = git_command(path, ["rev-parse", "--abbrev-ref", "HEAD"])
    commit, commit_error = git_command(path, ["rev-parse", "HEAD"])
    status, status_error = git_command(path, ["status", "--porcelain=v1"])
    changes = [line for line in status.splitlines() if line.strip()]
    rel = str(path.relative_to(ROOT)) if path.is_absolute() and path.is_relative_to(ROOT) else str(path)
    return {
        "path": rel,
        "exists": True,
        "git_repo": True,
        "branch": branch if branch != "HEAD" else "detached",
        "commit": commit,
        "commit_short": commit[:7] if commit else "",
        "dirty": bool(changes),
        "changes": len(changes),
        "error": branch_error or commit_error or status_error or "",
    }


def git_path_is_tracked(path: Path) -> bool:
    try:
        rel = path.resolve().relative_to(ROOT)
    except ValueError:
        return False
    proc = subprocess.run(
        ["git", "-C", str(ROOT), "ls-files", "--error-unmatch", rel.as_posix()],
        check=False,
        capture_output=True,
        text=True,
        timeout=5,
    )
    return proc.returncode == 0


def git_path_is_ignored(path: Path) -> bool:
    try:
        rel = path.resolve().relative_to(ROOT)
    except ValueError:
        return False
    proc = subprocess.run(
        ["git", "-C", str(ROOT), "check-ignore", "-q", rel.as_posix()],
        check=False,
        capture_output=True,
        text=True,
        timeout=5,
    )
    return proc.returncode == 0


def find_local_public_repo_evidence(public_release: dict[str, Any]) -> dict[str, Any]:
    candidates: list[Path] = []
    env_dir = os.environ.get("HOMENET_PUBLIC_REPO_DIR")
    if env_dir:
        candidates.append(Path(env_dir))
    candidates.extend([
        Path("/tmp/homenet-public-live"),
        Path("/tmp/homenet-public-repo"),
    ])

    expected_repository = str(public_release.get("repository") or "").removesuffix(".git")
    expected_branch = str(public_release.get("branch") or "main")
    for candidate in candidates:
        info = git_workspace_info(candidate)
        if not info.get("git_repo"):
            continue
        remote, remote_error = git_command(candidate, ["remote", "get-url", "origin"])
        remote_public = remote.removesuffix(".git") if remote else ""
        if expected_repository and remote_public and remote_public != expected_repository:
            continue
        info["remote"] = redact_git_remote_url(remote)
        info["remote_error"] = remote_error or ""
        info["matches_release_repository"] = bool(expected_repository and remote_public == expected_repository)
        info["matches_release_branch"] = bool(not expected_branch or info.get("branch") == expected_branch)
        return info
    return {
        "path": "",
        "exists": False,
        "git_repo": False,
        "branch": "",
        "commit": "",
        "commit_short": "",
        "dirty": False,
        "changes": 0,
        "remote": "",
        "remote_error": "",
        "matches_release_repository": False,
        "matches_release_branch": False,
    }


def build_version_report(instance: Path) -> dict[str, Any]:
    release = build_release_manifest(instance)
    reporter = Reporter()
    instance_state: dict[str, Any] = {}
    instance_valid = False
    instance_profile = ""
    if instance.exists():
        instance_state = check_instance(instance, reporter)
        instance_valid = not reporter.failed
        if instance_valid:
            instance_profile = str(build_plan(instance_state, instance).get("profile") or "")

    site = instance_state.get("site", {}) if isinstance(instance_state.get("site"), dict) else {}
    site_info = site.get("site", {}) if isinstance(site.get("site"), dict) else {}
    root_git = git_workspace_info(ROOT)
    instance_git = git_workspace_info(instance)
    workspace_projects = [
        {
            "id": "homenet",
            "role": "public-core-root",
            "ownership": "root repository",
            "release_scope": "public core root: CLI, schemas, docs, examples, maintenance modules, and Ops integration contracts",
            "git": root_git,
        },
        {
            "id": "homenet-ops",
            "role": "public-app",
            "ownership": "root repository under apps/ops",
            "release_scope": "HomeNet Ops source is part of the public core; runtime mounts and private instance data stay ignored",
            "git": root_git,
        },
        {
            "id": "private-instance",
            "role": "private-real-home-instance",
            "ownership": "own private git repository under workspace",
            "release_scope": "excluded from public core; contains the real home deployment description",
            "git": instance_git,
        },
        {
            "id": "sub",
            "role": "private-subscription-worker",
            "ownership": "own git repository under workspace",
            "release_scope": "excluded from public core",
            "git": git_workspace_info(ROOT / "sub"),
        },
    ]
    dirty_projects = [
        project.get("id")
        for project in workspace_projects
        if isinstance(project.get("git"), dict) and project["git"].get("dirty")
    ]
    instance_failures = [finding.message for finding in reporter.findings if finding.level == "FAIL"]
    return {
        "schema": "homenet.version.v1",
        "product": {
            "name": "HomeNet",
            "core_version": HOMENET_CORE_VERSION,
            "stage": "development",
        },
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "root": str(ROOT),
        "instance": {
            "path": str(instance),
            "exists": instance.exists(),
            "valid": instance_valid,
            "name": site_info.get("name", "") if instance_valid else "",
            "display_name": site_info.get("display_name", "") if instance_valid else "",
            "profile": instance_profile,
            "failures": instance_failures,
        },
        "workspace": {
            "projects": workspace_projects,
            "dirty_projects": dirty_projects,
            "dirty_project_count": len(dirty_projects),
        },
        "release": {
            "public_core_ready": release.get("public_core_ready"),
            "whole_worktree_publishable": release.get("whole_worktree_publishable"),
            "included_roots": release.get("summary", {}).get("included_roots"),
            "excluded_roots": release.get("summary", {}).get("excluded_roots"),
            "review_required": release.get("summary", {}).get("review_required"),
        },
        "version_rules": [
            "Version and publish the HomeNet public core root from the root repository.",
            "Do not publish the whole live workspace; use homenet release for the public boundary.",
            "Version HomeNet Ops together with the root repository; version the real-home instance and sub from their own private repositories.",
            "Keep real-home instances as private deployment instances of the reusable HomeNet model.",
            "Run homenet privacy, homenet check, and deploy --check-idempotent before committing normal deployment changes.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Version report contains git hashes, counts, paths, and release rules only; it does not print secret values or file contents.",
        },
    }


def print_version_markdown(report: dict[str, Any]) -> None:
    product = report.get("product", {}) if isinstance(report.get("product"), dict) else {}
    instance = report.get("instance", {}) if isinstance(report.get("instance"), dict) else {}
    release = report.get("release", {}) if isinstance(report.get("release"), dict) else {}
    workspace = report.get("workspace", {}) if isinstance(report.get("workspace"), dict) else {}
    print("# HomeNet Version")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- product: {product.get('name')}")
    print(f"- core version: `{product.get('core_version')}`")
    print(f"- stage: {product.get('stage')}")
    print(f"- read only: {report.get('read_only')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print()
    print("## Instance")
    print()
    print(f"- path: `{instance.get('path')}`")
    print(f"- exists: {instance.get('exists')}")
    print(f"- valid: {instance.get('valid')}")
    print(f"- profile: {instance.get('profile') or '-'}")
    if instance.get("failures"):
        print("- failures:")
        for failure in as_list(instance.get("failures")):
            print(f"  - {failure}")
    print()
    print("## Workspace Projects")
    print()
    print("| Project | Role | Git | Branch | Commit | Dirty | Changes | Scope |")
    print("| --- | --- | --- | --- | --- | --- | --- | --- |")
    for project in workspace.get("projects", []):
        if not isinstance(project, dict):
            continue
        git = project.get("git", {}) if isinstance(project.get("git"), dict) else {}
        print(
            f"| {project.get('id', '')} | {project.get('role', '')} | {git.get('git_repo')} | "
            f"{git.get('branch', '')} | `{git.get('commit_short', '')}` | {git.get('dirty')} | "
            f"{git.get('changes', 0)} | {project.get('release_scope', '')} |"
        )
    print()
    print("## Release Boundary")
    print()
    print(f"- public core ready: {release.get('public_core_ready')}")
    print(f"- whole worktree publishable: {release.get('whole_worktree_publishable')}")
    print(f"- included roots: {release.get('included_roots')}")
    print(f"- excluded roots: {release.get('excluded_roots')}")
    print(f"- review required: {release.get('review_required')}")
    print()
    print("## Version Rules")
    print()
    for rule in report.get("version_rules", []):
        print(f"- {rule}")
    print()


def build_workspace_report(instance: Path) -> dict[str, Any]:
    version = build_version_report(instance)
    release = build_release_manifest(instance)
    root_git = git_workspace_info(ROOT)
    sub_git = git_workspace_info(ROOT / "sub")
    instance_git = git_workspace_info(instance)
    instance_in_root = instance.resolve().is_relative_to(ROOT)
    instance_root_tracked = git_path_is_tracked(instance) if instance_in_root else False
    instance_root_ignored = git_path_is_ignored(instance) if instance_in_root else False
    instance_path_display = (
        str(instance.resolve().relative_to(ROOT)) + "/"
        if instance_in_root
        else f"{instance.as_posix().rstrip('/')}/"
    )
    instance_commit_from = "ignored workspace instance" if instance_root_ignored else ("." if instance_in_root else "private instance directory")
    if instance_git.get("git_repo"):
        instance_commit_from = instance_path_display
    boundaries = [
        {
            "id": "homenet-root",
            "path": ".",
            "kind": "git-repository",
            "owner": "HomeNet public core",
            "git": root_git,
            "publish_scope": "public core after privacy/CI gates",
            "commit_from": ".",
            "root_repo_tracks": True,
            "rule": "Owns reusable CLI, schemas, public docs, example instances, reusable maintenance modules, and sanitized instance declarations.",
        },
        {
            "id": "homenet-ops",
            "path": "apps/ops/",
            "kind": "public-app",
            "owner": "HomeNet Ops",
            "git": root_git,
            "publish_scope": "public HomeNet app source",
            "commit_from": ".",
            "root_repo_tracks": True,
            "rule": "Ops is the simple daily status and entry surface; source lives in apps/ops, while runtime mounts and private instance data stay ignored.",
        },
        {
            "id": "subscription-worker",
            "path": "sub/",
            "kind": "git-repository",
            "owner": "private subscription Worker",
            "git": sub_git,
            "publish_scope": "private worker, excluded from HomeNet public core",
            "commit_from": "sub/",
            "root_repo_tracks": False,
            "rule": "Do not absorb Worker source, wrangler state, generated files, or private routing policy into the root release.",
        },
        {
            "id": "selected-private-instance",
            "path": instance_path_display,
            "kind": "deployment-instance",
            "owner": "private deployment instance",
            "git": instance_git,
            "publish_scope": "private example of the reusable model; publish only after sanitization or replacement with example instances",
            "commit_from": instance_commit_from,
            "root_repo_tracks": instance_root_tracked,
            "rule": "Real-home instance files live in a private git repository inside the network workspace and stay ignored by the public root.",
        },
        {
            "id": "public-examples",
            "path": "instances/example-*/",
            "kind": "public-examples",
            "owner": "HomeNet public core",
            "git": {},
            "publish_scope": "public reusable templates",
            "commit_from": ".",
            "root_repo_tracks": True,
            "rule": "Examples must use placeholder domains, placeholder addresses, and no secret values.",
        },
        {
            "id": "runtime-state",
            "path": "adguard/, mihomo/, wg-easy/, caddy/, cloudflared/, ddns-go/, backups/, maintenance/state/",
            "kind": "runtime-or-secret-state",
            "owner": "source tools and live deployment",
            "git": {},
            "publish_scope": "never part of public core",
            "commit_from": "not committed",
            "root_repo_tracks": False,
            "rule": "Runtime configs, service databases, cache, certificates, subscription files, backups, and local secrets remain ignored.",
        },
    ]
    dirty_boundaries = [
        row.get("id")
        for row in boundaries
        if isinstance(row.get("git"), dict) and row["git"].get("dirty")
    ]
    instance_arg = str(instance)
    instance_name = instance.name or "my-home"
    review_checks = [
        f"./homenet release --instance {instance_arg}",
        f"./homenet package --instance {instance_arg} --output-dir /tmp/homenet-public --force",
        f"./homenet release-candidate --instance {instance_arg} --output-dir /tmp/homenet-public --repo-dir /tmp/homenet-public-repo --force",
        "./homenet publish-check --dir /tmp/homenet-public --work-dir /tmp/homenet-publish-check --force",
        "./homenet repo-init --dir /tmp/homenet-public --repo-dir /tmp/homenet-public-repo --force",
        f"./homenet publish-audit --instance {instance_arg} --dir /tmp/homenet-public --repo-dir /tmp/homenet-public-repo --run-publish-check --force",
        f"./homenet repo-publish --instance {instance_arg} --dir /tmp/homenet-public --repo-dir /tmp/homenet-public-repo --remote <public-repo-url> --confirm-push PUSH-HOMENET-PUBLIC --force",
        "./homenet repo-plan --dir /tmp/homenet-public",
        f"./homenet version --instance {instance_arg}",
        f"./homenet workspace --instance {instance_arg}",
        "./homenet privacy --scope public",
        f"./homenet privacy --scope all --instance {instance_arg}",
        f"./homenet deploy --instance {instance_arg} --force --check-idempotent",
    ]
    private_instance_review = {
        "status": "active" if instance_root_ignored or not instance_in_root else "planned",
        "current_shape": (
            "The selected real-home instance is an ignored private git repository inside the network workspace."
            if instance_git.get("git_repo") and instance_root_ignored
            else "The selected real-home instance is inside the network workspace and excluded from public git by ignore rules."
            if instance_root_ignored
            else (
                "The selected real-home instance is outside the public core root and can be passed to --instance."
                if not instance_in_root
                else "The selected real-home instance is inside the root repository and is not ignored; it must not be published until sanitized or ignored."
            )
        ),
        "target_shape": "Use /home/pi/network as both the public HomeNet checkout and the home-network deployment workspace; keep real-home instance and runtime state inside the workspace but outside public git.",
        "candidate_private_root": f"instances/{instance_name}",
        "copy_only": [
            f"{instance.as_posix().rstrip('/')}/site.yaml",
            f"{instance.as_posix().rstrip('/')}/devices.yaml",
            f"{instance.as_posix().rstrip('/')}/services.yaml",
            f"{instance.as_posix().rstrip('/')}/README.md",
        ],
        "keep_private_and_untracked": [
            ".env",
            "docker-compose.yml",
            "adguard/",
            "mihomo/",
            "wg-easy/",
            "caddy/",
            "cloudflared/",
            "ddns-go/",
            "backups/",
            "maintenance/state/",
            "sub/",
        ],
        "validation_commands": [
            f"./homenet check --instance instances/{instance_name}",
            f"./homenet quickstart --instance instances/{instance_name}",
            f"./homenet workspace --instance instances/{instance_name}",
            f"./homenet deploy --instance instances/{instance_name} --force --check-idempotent",
        ],
        "no_live_change_rules": [
            "Do not move runtime directories as part of instance review.",
            "Do not change OpenWrt, DNS, Proxy, Cloudflare, Kuma, Docker, or systemd while separating the instance files.",
            "Do not replace the active instance path in any service until the copied instance has passed check and deploy idempotency validation.",
        ],
    }
    git_repo_paths = {
        str(row["git"].get("path") or row.get("path") or "")
        for row in boundaries
        if isinstance(row.get("git"), dict) and row["git"].get("git_repo")
    }
    return {
        "schema": "homenet.workspace.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "root": str(ROOT),
        "instance": version.get("instance"),
        "summary": {
            "boundaries": len(boundaries),
            "git_repositories": len(git_repo_paths),
            "root_tracked_boundaries": sum(1 for row in boundaries if row.get("root_repo_tracks")),
            "excluded_boundaries": sum(1 for row in boundaries if not row.get("root_repo_tracks")),
            "dirty_boundaries": len(dirty_boundaries),
            "public_core_ready": release.get("public_core_ready"),
            "whole_worktree_publishable": release.get("whole_worktree_publishable"),
            "private_instance_review_ready": True,
        },
        "boundaries": boundaries,
        "dirty_boundaries": dirty_boundaries,
        "private_instance_review": private_instance_review,
        "review_checks": review_checks,
        "operator_rules": [
            "Commit root HomeNet changes from the root repository only.",
            "Commit HomeNet Ops changes from the root repository under apps/ops.",
            "Commit subscription Worker changes from sub only.",
            "Do not commit runtime state, live service databases, backups, proxy subscriptions, tokens, passwords, cookies, or private keys.",
            "Run the boundary checks before publishing, pushing, or asking another AI/operator to continue.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Workspace report lists ownership and git summaries only; it does not read or print ignored runtime files or secret values.",
        },
    }


def print_workspace_markdown(report: dict[str, Any]) -> None:
    summary = report.get("summary", {}) if isinstance(report.get("summary"), dict) else {}
    print("# HomeNet Workspace")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print(f"- root: `{report.get('root')}`")
    print()
    print("## Summary")
    print()
    for key in [
        "boundaries",
        "git_repositories",
        "root_tracked_boundaries",
        "excluded_boundaries",
        "dirty_boundaries",
        "public_core_ready",
        "whole_worktree_publishable",
        "private_instance_review_ready",
    ]:
        print(f"- {key}: {summary.get(key)}")
    print()
    print("## Boundaries")
    print()
    print("| ID | Path | Kind | Owner | Git | Dirty | Commit From | Root Tracks | Publish Scope |")
    print("| --- | --- | --- | --- | --- | --- | --- | --- | --- |")
    for row in report.get("boundaries", []):
        if not isinstance(row, dict):
            continue
        git = row.get("git", {}) if isinstance(row.get("git"), dict) else {}
        git_label = "-"
        dirty = "-"
        if git:
            git_label = f"{git.get('branch', '')} `{git.get('commit_short', '')}`".strip()
            dirty = str(git.get("dirty"))
        print(
            f"| {row.get('id', '')} | `{row.get('path', '')}` | {row.get('kind', '')} | "
            f"{row.get('owner', '')} | {git_label} | {dirty} | `{row.get('commit_from', '')}` | "
            f"{row.get('root_repo_tracks')} | {row.get('publish_scope', '')} |"
        )
    print()
    print("## Boundary Rules")
    print()
    for row in report.get("boundaries", []):
        if isinstance(row, dict):
            print(f"- {row.get('id')}: {row.get('rule')}")
    print()
    review = report.get("private_instance_review")
    if isinstance(review, dict):
        print("## Private Instance Boundary")
        print()
        print(f"- status: {review.get('status')}")
        print(f"- current shape: {review.get('current_shape')}")
        print(f"- target shape: {review.get('target_shape')}")
        print(f"- candidate private root: `{review.get('candidate_private_root')}`")
        print()
        print("### Copy Only")
        print()
        for item in as_list(review.get("copy_only")):
            print(f"- `{item}`")
        print()
        print("### Keep Private And Untracked")
        print()
        for item in as_list(review.get("keep_private_and_untracked")):
            print(f"- `{item}`")
        print()
        print("### Validation Commands")
        print()
        for command in as_list(review.get("validation_commands")):
            print(f"- `{command}`")
        print()
        print("### No Live Change Rules")
        print()
        for rule in as_list(review.get("no_live_change_rules")):
            print(f"- {rule}")
        print()
    print("## Boundary Checks")
    print()
    for command in report.get("review_checks", []):
        print(f"- `{command}`")
    print()
    print("## Operator Rules")
    print()
    for rule in report.get("operator_rules", []):
        print(f"- {rule}")
    print()


def progress_milestone(
    milestone_id: str,
    title: str,
    weight: int,
    score: int,
    evidence: list[str],
    remaining: list[str],
) -> dict[str, Any]:
    bounded_score = max(0, min(score, weight))
    if bounded_score >= weight:
        status = "complete"
    elif bounded_score > 0:
        status = "partial"
    else:
        status = "pending"
    return {
        "id": milestone_id,
        "title": title,
        "weight": weight,
        "score": bounded_score,
        "status": status,
        "percent": round((bounded_score / weight) * 100, 1) if weight else 0,
        "evidence": evidence,
        "remaining": remaining,
    }


def build_progress_report(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    def load_public_release_evidence() -> dict[str, Any]:
        path = ROOT / "docs" / "public-release.json"
        if not path.exists():
            return {}
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return loaded if isinstance(loaded, dict) else {}

    def service_count(source: dict[str, Any]) -> int:
        services = source.get("services")
        if isinstance(services, dict):
            return len(as_list(services.get("services")))
        return len(as_list(services))

    metadata = build_metadata(state, instance)
    artifacts = build_artifact_manifest(metadata)
    config_plan = build_config_plan(metadata, instance)
    release = build_release_manifest(instance)
    public_package = build_public_package_manifest(instance)
    workspace = build_workspace_report(instance)
    module_registry = build_module_registry(state, instance)
    module_artifacts = build_module_artifacts_report()
    module_renderers = build_module_renderers_report()
    module_implementations = build_module_implementations_report()
    module_executors = build_module_executors_report()
    module_backups = build_module_backups_report()
    privacy_public = build_privacy_report(instance, scope="public")
    privacy_all = build_privacy_report(instance, scope="all")
    examples: list[dict[str, Any]] = []
    for example in discover_instances(include_private=False):
        example_reporter = Reporter()
        example_state = check_instance(example, example_reporter)
        examples.append({
            "path": str(example),
            "ok": not example_reporter.failed,
            "failures": len([finding for finding in example_reporter.findings if finding.level == "FAIL"]),
            "services": service_count(example_state) if not example_reporter.failed else 0,
        })
    instance_reporter = Reporter()
    instance_state = check_instance(instance, instance_reporter)
    instance_ok = not instance_reporter.failed
    instance_plan = build_plan(instance_state, instance) if instance_ok else {}
    module_definitions = build_module_definitions_report()
    modules_catalog = build_modules_catalog(state, instance)
    profiles = build_profiles_export()
    incident = build_incident_report(state, instance, live=False)
    status = build_status_dashboard(state, instance, live=False)
    quickstart = build_quickstart_guide(str(instance_plan.get("profile") or "openwrt-pi"), instance=instance, instance_state=state)
    operator_path_doc = Path("docs/operator-path.md")
    deployment_doc = Path("docs/deployment-and-adoption.md")
    source_tool_doc = Path("docs/source-tool-runbook.md")
    readme_text = (ROOT / "README.md").read_text(encoding="utf-8") if (ROOT / "README.md").exists() else ""
    operator_path_text = (ROOT / operator_path_doc).read_text(encoding="utf-8") if (ROOT / operator_path_doc).exists() else ""
    deployment_doc_text = (ROOT / deployment_doc).read_text(encoding="utf-8") if (ROOT / deployment_doc).exists() else ""
    source_tool_doc_text = (ROOT / source_tool_doc).read_text(encoding="utf-8") if (ROOT / source_tool_doc).exists() else ""
    public_release = load_public_release_evidence()
    public_release_ci = public_release.get("ci") if isinstance(public_release.get("ci"), dict) else {}
    public_release_privacy = public_release.get("privacy") if isinstance(public_release.get("privacy"), dict) else {}
    local_public_repo = find_local_public_repo_evidence(public_release)
    public_repo_published = (
        public_release.get("schema") == "homenet.public_release.v1"
        and isinstance(public_release.get("repository"), str)
        and public_release.get("repository", "").startswith("https://github.com/")
        and isinstance(public_release.get("last_verified_commit"), str)
        and bool(public_release.get("last_verified_commit"))
    )
    public_repo_ci_green = public_release_ci.get("status") == "success"
    public_release_safe = (
        public_release_privacy.get("contains_private_instance") is False
        and public_release_privacy.get("contains_runtime_data") is False
        and public_release_privacy.get("contains_secrets") is False
    )
