def normalize_module_definition(definition: dict[str, Any]) -> dict[str, Any]:
    module_id = str(definition.get("id") or "")
    support = definition.get("profile_support") if isinstance(definition.get("profile_support"), dict) else {}
    surfaces = definition.get("surfaces") if isinstance(definition.get("surfaces"), dict) else {}
    return {
        "id": module_id,
        "title": definition.get("title") or module_id,
        "required": bool(definition.get("required")),
        "runtime_options": as_list(definition.get("runtimes")),
        "fallback": definition.get("fallback") or "",
        "openwrt_only": support.get("openwrt-only") or "",
        "with_server": support.get("openwrt-pi") or support.get("openwrt-mini-pc") or "",
        "notes": definition.get("description") or "",
        "description": definition.get("description") or "",
        "ownership": definition.get("ownership") or "",
        "module_boundary": definition.get("module_boundary") or "",
        "apply_policy": definition.get("apply_policy") or "",
        "source_tools": as_list(definition.get("source_tools")),
        "profile_support": dict(support),
        "surfaces": {
            "inputs": as_list(surfaces.get("inputs")),
            "outputs": as_list(surfaces.get("outputs")),
            "checks": as_list(surfaces.get("checks")),
            "rollback": as_list(surfaces.get("rollback")),
        },
        "source": "modules/catalog.yaml",
    }


def module_capabilities() -> list[dict[str, Any]]:
    global _MODULE_CAPABILITIES_CACHE
    if _MODULE_CAPABILITIES_CACHE is not None:
        return _MODULE_CAPABILITIES_CACHE
    definitions = load_module_definitions()
    modules = [
        normalize_module_definition(item)
        for item in as_list(definitions.get("modules"))
        if isinstance(item, dict) and item.get("id")
    ]
    if definitions.get("ok") and modules:
        _MODULE_CAPABILITIES_CACHE = modules
        return _MODULE_CAPABILITIES_CACHE
    _MODULE_CAPABILITIES_CACHE = [dict(item, source="tools/homenet.py:fallback") for item in MODULE_CAPABILITIES]
    return _MODULE_CAPABILITIES_CACHE


def default_site_for_profile(profile: str) -> dict[str, Any]:
    server_enabled = profile != "openwrt-only"
    preferred = "mini-pc" if profile == "openwrt-mini-pc" else ("pi" if server_enabled else "openwrt")
    base_runtime = "server" if server_enabled else "openwrt"
    return {
        "runtime": {
            "router": {"type": "openwrt", "host": "OpenWrt"},
            "server": {
                "enabled": server_enabled,
                "preferred": preferred,
                "host": "server" if server_enabled else "",
            },
        },
        "modules": {
            "gateway-openwrt": {"enabled": True, "runtime": "openwrt", "implementation": "openwrt"},
            "dns-layer": {"enabled": True, "runtime": base_runtime, "implementation": "auto"},
            "proxy-mihomo": {"enabled": True, "runtime": base_runtime, "implementation": "mihomo"},
            "remote-access": {"enabled": True, "runtime": "mixed" if server_enabled else "openwrt", "implementation": "auto"},
            "observability-homenet": {"enabled": True, "runtime": base_runtime, "implementation": "auto"},
            "smart-home": {"enabled": False, "runtime": "external", "implementation": "disabled"},
            "maintenance-wifi": {"enabled": True, "runtime": "openwrt", "implementation": "openwrt-isolated-ssid"},
            "server-runtime": {
                "enabled": server_enabled,
                "runtime": preferred if server_enabled else "none",
                "implementation": "docker+systemd" if server_enabled else "disabled",
            },
            "room-ap": {"enabled": False, "runtime": "none", "implementation": "disabled"},
        },
        "features": {},
    }


def build_module_decisions(profile: str, site: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    decision_site = site if isinstance(site, dict) else default_site_for_profile(profile)
    intents = module_intents(decision_site, profile)
    rows: list[dict[str, Any]] = []
    for capability in module_capabilities():
        module_id = str(capability.get("id") or "")
        intent = intents.get(module_id, {})
        guidance = MODULE_DECISION_GUIDANCE.get(module_id, {})
        rows.append({
            "id": module_id,
            "title": capability.get("title") or module_id,
            "required": bool(capability.get("required")),
            "recommended": guidance.get("recommendation") or ("required" if capability.get("required") else "optional"),
            "current_enabled": intent.get("enabled"),
            "runtime": intent.get("runtime"),
            "implementation": intent.get("implementation"),
            "fallback": intent.get("fallback") or capability.get("fallback") or "",
            "source": intent.get("source") or "derived",
            "when_to_enable": guidance.get("when_to_enable") or "",
            "when_to_disable": guidance.get("when_to_disable") or "",
            "disable_effect": guidance.get("disable_effect") or "",
            "edit": guidance.get("edit") or f"modules.{module_id}",
        })
    return rows


def current_capability_status(site: dict[str, Any], capability: dict[str, Any], profile: str) -> str:
    module_id = str(capability.get("id") or "")
    intent = module_intents(site, profile).get(module_id, {})
    if intent.get("enabled") is False:
        return "missing-required" if capability.get("required") else "optional-disabled"
    if module_id == "server-runtime":
        server = site.get("runtime", {}).get("server", {})
        if isinstance(server, dict) and server.get("enabled") is not False and server.get("host"):
            return "enabled"
        return "fallback"
    if module_id == "room-ap":
        room_ap = site.get("runtime", {}).get("room_ap", {})
        if isinstance(room_ap, dict) and room_ap.get("host"):
            return "enabled"
        return "not-configured"
    if capability.get("required"):
        return "enabled"
    if intent.get("enabled") is not False:
        return "enabled"
    return "optional-disabled" if profile != "openwrt-only" else "fallback"


def build_capability_matrix(state: dict[str, Any], profile: str, modules: list[dict[str, Any]]) -> list[dict[str, Any]]:
    site = state["site"]
    placements = {str(module.get("id") or ""): module.get("placement") for module in modules}
    intents = module_intents(site, profile)
    rows: list[dict[str, Any]] = []
    for capability in module_capabilities():
        module_id = str(capability.get("id") or "")
        row = dict(capability)
        intent = intents.get(module_id, {})
        row["current_status"] = current_capability_status(site, capability, profile)
        row["current_placement"] = placements.get(module_id, "") or module_runtime_placement(site, module_id, intent)
        row["intent"] = {
            "enabled": intent.get("enabled"),
            "runtime": intent.get("runtime"),
            "implementation": intent.get("implementation"),
            "fallback": intent.get("fallback"),
            "source": intent.get("source"),
        }
        rows.append(row)
    return rows


def build_module_definitions_report() -> dict[str, Any]:
    definitions = load_module_definitions()
    modules = [item for item in as_list(definitions.get("modules")) if isinstance(item, dict)]
    return {
        "schema": definitions.get("schema") or "homenet.module_definitions.v1",
        "version": definitions.get("version") or "",
        "source": definitions.get("source") or "modules/catalog.yaml",
        "read_only": True,
        "module_count": len(modules),
        "ok": bool(definitions.get("ok")),
        "errors": as_list(definitions.get("errors")),
        "missing_from_definitions": as_list(definitions.get("missing_from_definitions")),
        "extra_definitions": as_list(definitions.get("extra_definitions")),
        "principles": as_list(definitions.get("principles")),
        "modules": modules,
        "privacy": {
            "secrets_included": False,
            "note": "Module definitions are public product metadata only; instance-specific addresses, account names, passwords, tokens, cookies, and proxy subscriptions do not belong here.",
        },
    }


def print_module_definitions_markdown(report: dict[str, Any]) -> None:
    print("# HomeNet Module Definitions")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- version: `{report.get('version') or '-'}`")
    print(f"- source: `{report.get('source')}`")
    print(f"- ok: {report.get('ok')}")
    print(f"- modules: {report.get('module_count')}")
    if report.get("errors"):
        print(f"- errors: {', '.join(str(item) for item in as_list(report.get('errors')))}")
    if report.get("missing_from_definitions"):
        print(f"- missing: {', '.join(str(item) for item in as_list(report.get('missing_from_definitions')))}")
    print()
    print("## Principles")
    print()
    for item in as_list(report.get("principles")):
        print(f"- {item}")
    print()
    print("## Modules")
    print()
    print("| Module | Required | Runtimes | OpenWrt-only | With server | Fallback |")
    print("| --- | --- | --- | --- | --- | --- |")
    for module in as_list(report.get("modules")):
        if not isinstance(module, dict):
            continue
        support = module.get("profile_support", {}) if isinstance(module.get("profile_support"), dict) else {}
        print(
            f"| {module.get('title', '')} (`{module.get('id', '')}`) | "
            f"{'yes' if module.get('required') else 'optional'} | "
            f"{', '.join(str(item) for item in as_list(module.get('runtimes')))} | "
            f"{support.get('openwrt-only', '')} | {support.get('openwrt-pi', '')} | "
            f"{module.get('fallback', '')} |"
        )
    print()
    print("## Boundaries")
    for module in as_list(report.get("modules")):
        if not isinstance(module, dict):
            continue
        print()
        print(f"### {module.get('title')} (`{module.get('id')}`)")
        print()
        if module.get("description"):
            print(str(module.get("description")))
            print()
        print(f"- boundary: {module.get('module_boundary') or '-'}")
        print(f"- ownership: {module.get('ownership') or '-'}")
        print(f"- apply policy: {module.get('apply_policy') or '-'}")
        source_tools = [str(item) for item in as_list(module.get("source_tools")) if str(item)]
        if source_tools:
            print(f"- source tools: {', '.join(source_tools)}")


def build_module_artifacts_report() -> dict[str, Any]:
    contracts = load_module_artifact_contracts()
    modules = contracts.get("modules") if isinstance(contracts.get("modules"), dict) else {}
    rows: list[dict[str, Any]] = []
    for module_id, artifacts in sorted(modules.items()):
        for artifact in as_list(artifacts):
            if not isinstance(artifact, dict):
                continue
            rows.append({
                "id": f"{module_id}.{artifact.get('id')}",
                "module_id": module_id,
                "artifact_id": artifact.get("id"),
                "kind": artifact.get("kind"),
                "target": artifact.get("target"),
                "path": artifact.get("path"),
                "owner": artifact.get("owner"),
                "risk": artifact.get("risk"),
                "source": contracts.get("source") or "modules/artifacts.yaml",
            })
    by_module = {
        module_id: len([row for row in rows if row.get("module_id") == module_id])
        for module_id in sorted({str(row.get("module_id") or "") for row in rows})
    }
    return {
        "schema": contracts.get("schema") or "homenet.module_artifacts.v1",
        "version": contracts.get("version") or "",
        "source": contracts.get("source") or "modules/artifacts.yaml",
        "read_only": True,
        "ok": bool(contracts.get("ok")),
        "artifact_count": len(rows),
        "module_count": len(by_module),
        "by_module": by_module,
        "artifact_ids": [row.get("id") for row in rows],
        "errors": as_list(contracts.get("errors")),
        "missing_modules": as_list(contracts.get("missing_modules")),
        "extra_modules": as_list(contracts.get("extra_modules")),
        "principles": as_list(contracts.get("principles")),
        "artifacts": rows,
        "privacy": {
            "secrets_included": False,
            "note": "Module artifact contracts contain artifact names, target paths, owners, and risk classes only; rendered config and secret values do not belong here.",
        },
    }


