def build_module_implementations_report() -> dict[str, Any]:
    contracts = load_module_implementation_contracts()
    modules = contracts.get("modules") if isinstance(contracts.get("modules"), dict) else {}
    rows: list[dict[str, Any]] = []
    for module_id, implementations in sorted(modules.items()):
        for implementation in as_list(implementations):
            if not isinstance(implementation, dict):
                continue
            rows.append({
                "id": f"{module_id}.{implementation.get('id')}",
                "module_id": module_id,
                "implementation_id": implementation.get("id"),
                "implementation_surface": implementation.get("implementation_surface"),
                "implementation_status": implementation.get("implementation_status"),
                "write_support": implementation.get("write_support"),
                "adoption_target": implementation.get("adoption_target"),
                "source": contracts.get("source") or "modules/implementations.yaml",
            })
    by_module = {
        module_id: len([row for row in rows if row.get("module_id") == module_id])
        for module_id in sorted({str(row.get("module_id") or "") for row in rows})
    }
    centralized = [
        row for row in rows
        if str(row.get("implementation_status") or "").startswith("centralized")
    ]
    module_owned = [
        row for row in rows
        if str(row.get("implementation_status") or "").startswith("module-owned")
    ]
    return {
        "schema": contracts.get("schema") or "homenet.module_implementations.v1",
        "version": contracts.get("version") or "",
        "source": contracts.get("source") or "modules/implementations.yaml",
        "read_only": True,
        "ok": bool(contracts.get("ok")),
        "implementation_count": len(rows),
        "module_count": len(by_module),
        "centralized_count": len(centralized),
        "module_owned_count": len(module_owned),
        "write_enabled_count": sum(1 for row in rows if row.get("write_support") not in {"disabled", "review-only"}),
        "by_module": by_module,
        "implementation_ids": [row.get("id") for row in rows],
        "errors": as_list(contracts.get("errors")),
        "missing_modules": as_list(contracts.get("missing_modules")),
        "extra_modules": as_list(contracts.get("extra_modules")),
        "missing_renderer_contracts": as_list(contracts.get("missing_renderer_contracts")),
        "extra_implementations": as_list(contracts.get("extra_implementations")),
        "principles": as_list(contracts.get("principles")),
        "implementations": rows,
        "adoption": {
            "current_state": "indexed-centralized-cli",
            "target_state": "module-owned renderer/checker implementation boundaries",
            "next_step": "move implementation functions behind module-owned adapters without changing live network behavior",
        },
        "privacy": {
            "secrets_included": False,
            "note": "Module implementation contracts contain implementation IDs, source surfaces, readiness status, and adoption targets only; rendered config and secret values do not belong here.",
        },
    }


