def build_module_backups_report() -> dict[str, Any]:
    contracts = load_module_backup_contracts()
    capabilities = contracts.get("method_capabilities") if isinstance(contracts.get("method_capabilities"), dict) else {}
    rows = []
    for method in sorted(capabilities):
        capability = capabilities.get(method) if isinstance(capabilities.get(method), dict) else {}
        rows.append({
            "method": method,
            "owner": capability.get("owner"),
            "implementation_status": capability.get("implementation_status"),
            "supports_plan": capability.get("supports_plan"),
            "supports_capture": capability.get("supports_capture"),
            "supports_restore": capability.get("supports_restore"),
            "supports_verify": capability.get("supports_verify"),
            "disabled_reason": capability.get("disabled_reason"),
            "implementation_required": as_list(capability.get("implementation_required")),
        })
    return {
        "schema": contracts.get("schema") or "homenet.module_backups.v1",
        "version": contracts.get("version") or "",
        "source": contracts.get("source") or "modules/backups.yaml",
        "read_only": True,
        "ok": bool(contracts.get("ok")),
        "method_count": len(capabilities),
        "plan_capable_count": sum(1 for row in rows if row.get("supports_plan")),
        "capture_enabled_count": sum(1 for row in rows if row.get("supports_capture")),
        "restore_enabled_count": sum(1 for row in rows if row.get("supports_restore")),
        "verify_enabled_count": sum(1 for row in rows if row.get("supports_verify")),
        "errors": as_list(contracts.get("errors")),
        "principles": as_list(contracts.get("principles")),
        "methods": rows,
        "privacy": {
            "secrets_included": False,
            "captured_data_included": False,
            "note": "Module backup contracts contain method capabilities and disabled runner requirements only; captured content does not belong here.",
        },
    }


