def build_modules_catalog(state: dict[str, Any] | None = None, instance: Path | None = None) -> dict[str, Any]:
    profile = ""
    module_plans: list[dict[str, Any]] = []
    capability_matrix: list[dict[str, Any]] = []
    instance_info: dict[str, Any] = {}
    site_for_decisions: dict[str, Any] | None = None
    if state is not None and instance is not None:
        plan = build_plan(state, instance)
        profile = str(plan.get("profile") or "")
        module_plans = [item for item in plan.get("modules", []) if isinstance(item, dict)]
        capability_matrix = [item for item in plan.get("capability_matrix", []) if isinstance(item, dict)]
        instance_info = plan.get("instance") if isinstance(plan.get("instance"), dict) else {}
        site_for_decisions = state.get("site") if isinstance(state.get("site"), dict) else None

    plan_by_id = {str(item.get("id") or ""): item for item in module_plans}
    capability_by_id = {str(item.get("id") or ""): item for item in capability_matrix}

    definitions = build_module_definitions_report()
    definitions_by_id = {
        str(item.get("id") or ""): item
        for item in as_list(definitions.get("modules"))
        if isinstance(item, dict) and item.get("id")
    }

    modules: list[dict[str, Any]] = []
    for capability in module_capabilities():
        module_id = str(capability.get("id") or "")
        active = capability_by_id.get(module_id, {})
        plan_item = plan_by_id.get(module_id, {})
        definition = definitions_by_id.get(module_id, {})
        definition_support = definition.get("profile_support") if isinstance(definition.get("profile_support"), dict) else {}
        default_surfaces = capability.get("surfaces", {}) if isinstance(capability.get("surfaces"), dict) else {}
        modules.append({
            "id": module_id,
            "title": definition.get("title") or capability.get("title") or module_id,
            "required": bool(definition.get("required") if "required" in definition else capability.get("required")),
            "runtime_options": as_list(definition.get("runtimes")) or as_list(capability.get("runtime_options")),
            "profile_support": {
                "openwrt-only": definition_support.get("openwrt-only") or capability.get("openwrt_only") or "",
                "openwrt-pi": definition_support.get("openwrt-pi") or capability.get("with_server") or "",
                "openwrt-mini-pc": definition_support.get("openwrt-mini-pc") or capability.get("with_server") or "",
            },
            "fallback": definition.get("fallback") or capability.get("fallback") or "",
            "description": definition.get("description") or capability.get("notes") or "",
            "definition": {
                "source": definitions.get("source") or "modules/catalog.yaml",
                "status": "defined" if definition else "missing",
                "ownership": definition.get("ownership") or "",
                "module_boundary": definition.get("module_boundary") or "",
                "apply_policy": definition.get("apply_policy") or "",
                "source_tools": as_list(definition.get("source_tools")),
            },
            "current": {
                "status": active.get("current_status") or "",
                "placement": active.get("current_placement") or plan_item.get("placement") or "",
                "intent": active.get("intent") if isinstance(active.get("intent"), dict) else {},
            },
            "surfaces": {
                "inputs": as_list(plan_item.get("inputs")) or as_list(default_surfaces.get("inputs")),
                "outputs": as_list(plan_item.get("outputs")) or as_list(default_surfaces.get("outputs")),
                "checks": as_list(plan_item.get("checks")) or as_list(default_surfaces.get("checks")),
                "rollback": as_list(plan_item.get("rollback")) or as_list(default_surfaces.get("rollback")),
            },
        })

    return {
        "schema": "homenet.modules.v1",
        "definition_schema": definitions.get("schema"),
        "definition_version": definitions.get("version"),
        "definition_source": definitions.get("source"),
        "definition_ok": definitions.get("ok"),
        "instance": instance_info,
        "profile": profile,
        "read_only": True,
        "module_count": len(modules),
        "summary": {
            "required": sum(1 for item in modules if item.get("required")),
            "optional": sum(1 for item in modules if not item.get("required")),
            "active": sum(1 for item in modules if item.get("current", {}).get("status") == "enabled"),
            "fallback": sum(1 for item in modules if item.get("current", {}).get("status") == "fallback"),
        },
        "principles": [
            "A module is a bounded capability with inputs, generated outputs, checks, and rollback.",
            "Pi, mini PC, NAS, and OpenWrt-only deployments share the same module model; hardware changes placement and performance.",
            "Advanced modules must have a fallback or be explicitly optional.",
            "Instance files declare intent; generated surfaces explain and review it before any apply workflow.",
        ],
        "deployment_decisions": build_module_decisions(profile or "openwrt-pi", site_for_decisions),
        "modules": modules,
        "privacy": {
            "secrets_included": False,
            "note": "Module catalog describes capabilities and placements only; it does not include passwords, tokens, private keys, cookies, sessions, or proxy subscription URLs.",
        },
    }


def print_modules_markdown(catalog: dict[str, Any]) -> None:
    title = catalog.get("instance", {}).get("display_name") or "HomeNet"
    print(f"# HomeNet Modules - {title}")
    print()
    print(f"- schema: `{catalog.get('schema')}`")
    if catalog.get("profile"):
        print(f"- profile: `{catalog.get('profile')}`")
    print(f"- read only: {catalog.get('read_only')}")
    print()
    print("## Summary")
    print()
    for key, value in catalog.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Principles")
    print()
    for item in catalog.get("principles", []):
        print(f"- {item}")
    print()
    print("## Module Decisions")
    print()
    print("| Module | Recommended | Current | Runtime | Disable Effect | Edit |")
    print("| --- | --- | --- | --- | --- | --- |")
    for row in catalog.get("deployment_decisions", []):
        if not isinstance(row, dict):
            continue
        current = "enabled" if row.get("current_enabled") is not False else "disabled"
        print(
            f"| {row.get('title', '')} (`{row.get('id', '')}`) | "
            f"{row.get('recommended', '')} | {current} | {row.get('runtime', '')} | "
            f"{row.get('disable_effect', '')} | `{row.get('edit', '')}` |"
        )
    print()
    print("## Module Catalog")
    print()
    print("| Module | Required | Current | OpenWrt-only | With server | Fallback |")
    print("| --- | --- | --- | --- | --- | --- |")
    for module in catalog.get("modules", []):
        support = module.get("profile_support", {}) if isinstance(module.get("profile_support"), dict) else {}
        current = module.get("current", {}) if isinstance(module.get("current"), dict) else {}
        current_text = current.get("status") or "-"
        if current.get("placement"):
            current_text = f"{current_text} @ {current.get('placement')}"
        print(
            f"| {module.get('title', '')} (`{module.get('id', '')}`) | "
            f"{'yes' if module.get('required') else 'optional'} | "
            f"{current_text} | "
            f"{support.get('openwrt-only', '')} | {support.get('openwrt-pi', '')} | "
            f"{module.get('fallback', '')} |"
        )
    print()
    print("## Module Details")
    for module in catalog.get("modules", []):
        print()
        print(f"### {module.get('title')} (`{module.get('id')}`)")
        print()
        if module.get("description"):
            print(module.get("description"))
            print()
        runtime_options = ", ".join(str(item) for item in module.get("runtime_options", []))
        print(f"- runtime options: {runtime_options or '-'}")
        print(f"- fallback: {module.get('fallback') or '-'}")
        definition = module.get("definition", {}) if isinstance(module.get("definition"), dict) else {}
        if definition:
            print(f"- definition: {definition.get('status') or '-'} from `{definition.get('source') or '-'}`")
            if definition.get("module_boundary"):
                print(f"- boundary: {definition.get('module_boundary')}")
        current = module.get("current", {}) if isinstance(module.get("current"), dict) else {}
        print(f"- current: {current.get('status') or '-'} @ {current.get('placement') or '-'}")
        intent = current.get("intent", {}) if isinstance(current.get("intent"), dict) else {}
        if intent:
            print(
                f"- intent: enabled={intent.get('enabled')} runtime={intent.get('runtime') or '-'} "
                f"implementation={intent.get('implementation') or '-'} source={intent.get('source') or '-'}"
            )
        surfaces = module.get("surfaces", {}) if isinstance(module.get("surfaces"), dict) else {}
        for label in ("inputs", "outputs", "checks", "rollback"):
            values = [str(item) for item in as_list(surfaces.get(label)) if str(item)]
            if not values:
                continue
            print(f"- {label}:")
            for value in values:
                print(f"  - {value}")


def profile_by_id(profile_id: str) -> dict[str, Any]:
    for profile in PROFILE_CATALOG:
        if profile.get("id") == profile_id:
            return profile
    return {}


def build_inputs_checklist(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    plan = build_plan(state, instance)
    metadata = build_metadata(state, instance)
    secrets = build_secrets_contract(state, instance)
    modules = build_modules_catalog(state, instance)
    profile = str(plan.get("profile") or "")
    profile_def = profile_by_id(profile)
    site = state["site"]
    networks = state["networks"]
    wifi = state["wifi"]
    services = state["services"]
    devices = state["devices"]
    runtime_targets = plan.get("runtime_targets", {}) if isinstance(plan.get("runtime_targets"), dict) else {}
    features = site.get("features", {}) if isinstance(site.get("features"), dict) else {}
    declared_modules = site.get("modules", {}) if isinstance(site.get("modules"), dict) else {}

    def status_for(value: Any, *, required: bool = True) -> str:
        if value not in (None, "", [], {}):
            return "declared"
        return "missing" if required else "optional"

    instance_files = [
        {
            "id": "site",
            "path": str(instance / "site.yaml"),
            "required": True,
            "status": "declared" if (instance / "site.yaml").exists() else "missing",
            "purpose": "Site identity, profile intent, runtime targets, networks, Wi-Fi, modules, existing features, and remote ingress.",
        },
        {
            "id": "devices",
            "path": str(instance / "devices.yaml"),
            "required": True,
            "status": "declared" if (instance / "devices.yaml").exists() else "missing",
            "purpose": "Fixed devices, expected IPs, hostnames, roles, and MAC inventory.",
        },
        {
            "id": "services",
            "path": str(instance / "services.yaml"),
            "required": True,
            "status": "declared" if (instance / "services.yaml").exists() else "missing",
            "purpose": "Service directory, local/remote entries, ports, owners, checks, and categories.",
        },
    ]

    runtime_inputs: list[dict[str, Any]] = []
    router = runtime_targets.get("openwrt_gateway")
    runtime_inputs.append({
        "id": "openwrt-gateway",
        "required": True,
        "status": status_for(router),
        "value_hint": router or "OpenWrt LAN IP",
        "purpose": "Main Gateway, DHCP, firewall, Wi-Fi, and future router-side apply target.",
    })
    server = runtime_targets.get("server", {}) if isinstance(runtime_targets.get("server"), dict) else {}
    server_required = profile != "openwrt-only"
    runtime_inputs.append({
        "id": "server-runtime",
        "required": server_required,
        "status": status_for(server.get("host"), required=server_required),
        "value_hint": server.get("host") or ("Pi / mini PC / NAS IP" if server_required else "not required"),
        "purpose": "Always-on Linux runtime for Docker/systemd services when this profile uses a server.",
    })
    room_ap = runtime_targets.get("room_ap", {}) if isinstance(runtime_targets.get("room_ap"), dict) else {}
    runtime_inputs.append({
        "id": "room-ap",
        "required": False,
        "status": status_for(room_ap.get("host"), required=False),
        "value_hint": room_ap.get("host") or "optional",
        "purpose": "Optional coverage AP/relay for rooms with weak main Wi-Fi.",
    })

    network_inputs = [
        {
            "id": net_id,
            "required": bool(net.get("enabled", True)) if isinstance(net, dict) else True,
            "status": "declared",
            "cidr": net.get("cidr") if isinstance(net, dict) else "",
            "gateway": net.get("gateway") if isinstance(net, dict) else "",
            "dns_mode": net.get("dns_mode") if isinstance(net, dict) else "",
            "proxy_mode": net.get("proxy_mode") if isinstance(net, dict) else "",
            "purpose": net.get("purpose") if isinstance(net, dict) else "",
        }
        for net_id, net in sorted(networks.items())
        if isinstance(net, dict)
    ]
    wifi_inputs = [
        {
            "id": wifi_id,
            "required": bool(item.get("enabled", True)),
            "status": "declared",
            "ssid": item.get("ssid") or wifi_id,
            "network": item.get("network") or "",
            "band": item.get("band") or "",
            "password_secret": f"WIFI_{wifi_id.upper()}_PASSWORD",
            "purpose": item.get("purpose") or "",
        }
        for wifi_id, item in sorted(wifi.items())
        if isinstance(item, dict)
    ]

    secret_inputs = [
        {
            "key": row.get("key") or "",
            "scope": row.get("scope") or "",
            "required": bool(row.get("required")),
            "status": "required" if row.get("required") else "optional",
            "used_by": as_list(row.get("used_by")),
            "storage_hint": row.get("storage_hint") or "",
            "purpose": row.get("purpose") or "",
        }
        for row in secrets.get("secrets", [])
        if isinstance(row, dict)
    ]

    feature_inputs = []
    for module in modules.get("modules", []):
        if not isinstance(module, dict):
            continue
        module_id = str(module.get("id") or "")
        current = module.get("current", {}) if isinstance(module.get("current"), dict) else {}
        feature_inputs.append({
            "module_id": module_id,
            "title": module.get("title") or module_id,
            "required": bool(module.get("required")),
            "status": current.get("status") or "",
            "placement": current.get("placement") or "",
            "runtime_options": as_list(module.get("runtime_options")),
            "fallback": module.get("fallback") or "",
        })

    auto_defaults = [
        {
            "id": "profile-detection",
            "value": profile,
            "source": "runtime.server settings",
            "purpose": "Select OpenWrt-only versus OpenWrt + server behavior.",
        },
        {
            "id": "module-placement",
            "value": f"{modules.get('module_count', 0)} module(s)",
            "source": "modules + existing features + runtime targets",
            "purpose": "Derive where each capability runs.",
        },
        {
            "id": "service-directory",
            "value": f"{len(metadata.get('service_directory', []))} service(s)",
            "source": "services.yaml",
            "purpose": "Generate HomeNet Ops entries, docs, ports, and Kuma candidates.",
        },
        {
            "id": "kuma-candidates",
            "value": f"{len(metadata.get('kuma_inventory', []))} candidate row(s)",
            "source": "service URLs and ports",
            "purpose": "Generate monitoring candidates without writing Kuma by default.",
        },
    ]

    required_missing = [
        item for item in [*runtime_inputs, *instance_files] if item.get("required") and item.get("status") == "missing"
    ]
    summary = {
        "profile_inputs": len(as_list(profile_def.get("required_inputs"))),
        "instance_files": len(instance_files),
        "runtime_inputs": len(runtime_inputs),
        "networks": len(network_inputs),
        "wifi": len(wifi_inputs),
        "devices": len(devices),
        "services": len(services),
        "features": len(features),
        "declared_modules": len(declared_modules),
        "module_inputs": len(feature_inputs),
        "secrets": len(secret_inputs),
        "required_secrets": sum(1 for row in secret_inputs if row.get("required")),
        "required_missing": len(required_missing),
        "auto_defaults": len(auto_defaults),
    }
    return {
        "schema": "homenet.inputs.v1",
        "instance": plan.get("instance") or {},
        "instance_path": str(instance),
        "profile": profile,
        "read_only": True,
        "reads_secret_values": False,
        "reads_live_state": False,
        "summary": summary,
        "profile_required_inputs": as_list(profile_def.get("required_inputs")),
        "instance_files": instance_files,
        "runtime_inputs": runtime_inputs,
        "network_inputs": network_inputs,
        "wifi_inputs": wifi_inputs,
        "feature_inputs": feature_inputs,
        "secret_inputs": secret_inputs,
        "auto_defaults": auto_defaults,
        "next_actions": [
            "Run ./homenet init <name> --profile <profile> to create an editable instance draft.",
            "Edit site.yaml, devices.yaml, and services.yaml until ./homenet check --instance <instance> passes.",
            "Put real secret values in local secret storage or service-native stores, never in instance files or git.",
            "Run ./homenet preflight --instance <instance> on the machine that will operate the deployment.",
            "Run ./homenet deploy --instance <instance> --force --check-idempotent to generate and validate the private runtime draft.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Inputs checklist lists required names, files, decisions, and generated defaults only; it does not read or print secret values.",
        },
    }


def print_inputs_markdown(inputs: dict[str, Any]) -> None:
    instance = inputs.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or Path(str(inputs.get("instance_path", "instance"))).name
    print(f"# Deployment Inputs - {name}")
    print()
    print(f"- schema: `{inputs.get('schema')}`")
    print(f"- profile: `{inputs.get('profile')}`")
    print(f"- read only: {inputs.get('read_only')}")
    print(f"- reads secret values: {inputs.get('reads_secret_values')}")
    print(f"- reads live state: {inputs.get('reads_live_state')}")
    print()
    print("## Summary")
    print()
    for key, value in inputs.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Profile Required Inputs")
    print()
    for item in inputs.get("profile_required_inputs", []):
        print(f"- {item}")
    print()
    print("## Instance Files")
    print()
    print("| File | Required | Status | Purpose |")
    print("| --- | --- | --- | --- |")
    for row in inputs.get("instance_files", []):
        if isinstance(row, dict):
            print(f"| `{row.get('path', '')}` | {'yes' if row.get('required') else 'optional'} | {row.get('status', '')} | {row.get('purpose', '')} |")
    print()
    print("## Runtime Inputs")
    print()
    print("| ID | Required | Status | Value Hint | Purpose |")
    print("| --- | --- | --- | --- | --- |")
    for row in inputs.get("runtime_inputs", []):
        if isinstance(row, dict):
            print(f"| {row.get('id', '')} | {'yes' if row.get('required') else 'optional'} | {row.get('status', '')} | {row.get('value_hint', '')} | {row.get('purpose', '')} |")
    print()
    print("## Networks")
    print()
    print("| ID | CIDR | Gateway | DNS | Proxy | Purpose |")
    print("| --- | --- | --- | --- | --- | --- |")
    for row in inputs.get("network_inputs", []):
        if isinstance(row, dict):
            print(f"| {row.get('id', '')} | {row.get('cidr', '')} | {row.get('gateway', '')} | {row.get('dns_mode', '')} | {row.get('proxy_mode', '')} | {row.get('purpose', '')} |")
    print()
    print("## Wi-Fi")
    print()
    print("| ID | SSID | Network | Band | Password Secret | Purpose |")
    print("| --- | --- | --- | --- | --- | --- |")
    for row in inputs.get("wifi_inputs", []):
        if isinstance(row, dict):
            print(f"| {row.get('id', '')} | {row.get('ssid', '')} | {row.get('network', '')} | {row.get('band', '')} | `{row.get('password_secret', '')}` | {row.get('purpose', '')} |")
    print()
    print("## Modules")
    print()
    print("| Module | Required | Status | Placement | Fallback |")
    print("| --- | --- | --- | --- | --- |")
    for row in inputs.get("feature_inputs", []):
        if isinstance(row, dict):
            print(f"| {row.get('title', '')} (`{row.get('module_id', '')}`) | {'yes' if row.get('required') else 'optional'} | {row.get('status', '')} | {row.get('placement', '')} | {row.get('fallback', '')} |")
    print()
    print("## Secrets")
    print()
    print("| Key | Scope | Required | Used By | Storage Hint |")
    print("| --- | --- | --- | --- | --- |")
    for row in inputs.get("secret_inputs", []):
        if isinstance(row, dict):
            used_by = ", ".join(str(item) for item in as_list(row.get("used_by")))
            print(f"| `{row.get('key', '')}` | {row.get('scope', '')} | {'yes' if row.get('required') else 'optional'} | {used_by} | {row.get('storage_hint', '')} |")
    print()
    print("## Auto Defaults")
    print()
    print("| ID | Value | Source | Purpose |")
    print("| --- | --- | --- | --- |")
    for row in inputs.get("auto_defaults", []):
        if isinstance(row, dict):
            print(f"| {row.get('id', '')} | {row.get('value', '')} | {row.get('source', '')} | {row.get('purpose', '')} |")
    print()
    print("## Next Actions")
    print()
    for action in inputs.get("next_actions", []):
        print(f"- {action}")
    print()


def build_deployment_worksheet(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    inputs = build_inputs_checklist(state, instance)
    secrets = build_secrets_contract(state, instance)
    preflight = build_preflight(state, instance)
    readiness = build_readiness(state, instance)
    deploy_plan = build_deploy_plan(state, instance)
    quickstart = build_quickstart_guide(str(inputs.get("profile") or "openwrt-pi"), instance=instance, instance_state=state)

    secret_rows = [row for row in inputs.get("secret_inputs", []) if isinstance(row, dict)]
    required_secrets = [row for row in secret_rows if row.get("required")]
    optional_secrets = [row for row in secret_rows if not row.get("required")]

    sections = [
        {
            "id": "instance-files",
            "title": "Instance files",
            "status": "done" if inputs.get("summary", {}).get("instance_files", 0) else "pending",
            "owner": "operator",
            "next_command": f"homenet check --instance {instance}",
            "items": [
                {
                    "id": row.get("id") or Path(str(row.get("path") or "")).stem,
                    "label": row.get("path") or row.get("id") or "",
                    "required": bool(row.get("required")),
                    "status": row.get("status") or "",
                    "detail": row.get("purpose") or "",
                }
                for row in inputs.get("instance_files", [])
                if isinstance(row, dict)
            ],
        },
        {
            "id": "runtime-targets",
            "title": "Runtime targets",
            "status": "done" if not inputs.get("summary", {}).get("required_missing") else "pending",
            "owner": "operator",
            "next_command": f"homenet inputs --instance {instance}",
            "items": [
                {
                    "id": row.get("id") or "",
                    "label": row.get("id") or "",
                    "required": bool(row.get("required")),
                    "status": row.get("status") or "",
                    "detail": row.get("value_hint") or row.get("purpose") or "",
                }
                for row in inputs.get("runtime_inputs", [])
                if isinstance(row, dict)
            ],
        },
        {
            "id": "networks-wifi",
            "title": "Networks and Wi-Fi",
            "status": "done" if inputs.get("summary", {}).get("networks", 0) and inputs.get("summary", {}).get("wifi", 0) else "pending",
            "owner": "operator",
            "next_command": f"homenet inputs --instance {instance}",
            "items": [
                *[
                    {
                        "id": f"network-{row.get('id')}",
                        "label": f"{row.get('id')} {row.get('cidr')}",
                        "required": bool(row.get("required")),
                        "status": row.get("status") or "",
                        "detail": f"gateway={row.get('gateway', '')} dns={row.get('dns_mode', '')} proxy={row.get('proxy_mode', '')}",
                    }
                    for row in inputs.get("network_inputs", [])
                    if isinstance(row, dict)
                ],
                *[
                    {
                        "id": f"wifi-{row.get('id')}",
                        "label": row.get("ssid") or row.get("id") or "",
                        "required": bool(row.get("required")),
                        "status": row.get("status") or "",
                        "detail": f"network={row.get('network', '')} band={row.get('band', '')} secret={row.get('password_secret', '')}",
                    }
                    for row in inputs.get("wifi_inputs", [])
                    if isinstance(row, dict)
                ],
            ],
        },
        {
            "id": "secrets",
            "title": "Secrets",
            "status": "review" if required_secrets else "done",
            "owner": "operator",
            "next_command": f"homenet secrets --instance {instance}",
            "items": [
                {
                    "id": row.get("key") or "",
                    "label": row.get("key") or "",
                    "required": bool(row.get("required")),
                    "status": "required" if row.get("required") else "optional",
                    "detail": f"{row.get('scope', '')}: {row.get('storage_hint', '')}",
                }
                for row in secret_rows
            ],
        },
        {
            "id": "operator-preflight",
            "title": "Operator preflight",
            "status": "done" if not preflight.get("blockers") else "pending",
            "owner": "operator-machine",
            "next_command": f"homenet preflight --instance {instance}",
            "items": [
                {
                    "id": row.get("id") or row.get("key") or "",
                    "label": row.get("name") or row.get("key") or row.get("id") or "",
                    "required": row.get("required", True) is not False,
                    "status": row.get("status") or "",
                    "detail": row.get("detail") or row.get("purpose") or "",
                }
                for row in [*preflight.get("commands", []), *preflight.get("secrets", [])]
                if isinstance(row, dict)
            ],
        },
        {
            "id": "review-gates",
            "title": "Review gates",
            "status": "review" if readiness.get("ready_for_review") else "pending",
            "owner": "operator",
            "next_command": f"homenet check --instance {instance}",
            "items": [
                {
                    "id": "readiness-review",
                    "label": "ready_for_review",
                    "required": True,
                    "status": "done" if readiness.get("ready_for_review") else "pending",
                    "detail": f"warnings={readiness.get('summary', {}).get('warnings', 0)}",
                },
                {
                    "id": "deploy-dry-run",
                    "label": "deploy dry-run",
                    "required": True,
                    "status": "done" if deploy_plan.get("summary", {}).get("steps", 0) else "pending",
                    "detail": f"blockers={deploy_plan.get('summary', {}).get('blockers', 0)}",
                },
                {
                    "id": "check",
                    "label": "deployment check",
                    "required": True,
                    "status": "done",
                    "detail": "Run check after editing inputs and preparing secrets.",
                },
            ],
        },
    ]
    pending = sum(
        1
        for section in sections
        for item in section.get("items", [])
        if isinstance(item, dict) and item.get("required") and item.get("status") in {"missing", "pending"}
    )
    review = sum(1 for section in sections if section.get("status") == "review")
    done = sum(1 for section in sections if section.get("status") == "done")
    return {
        "schema": "homenet.worksheet.v1",
        "instance": inputs.get("instance") or {},
        "instance_path": str(instance),
        "profile": inputs.get("profile"),
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "reads_secret_values": False,
        "summary": {
            "sections": len(sections),
            "done_sections": done,
            "review_sections": review,
            "pending_required_items": pending,
            "required_secrets": len(required_secrets),
            "optional_secrets": len(optional_secrets),
            "quickstart_stages": len(quickstart.get("stages", [])),
        },
        "sections": sections,
        "next_commands": [
            f"homenet quickstart --instance {instance}",
            f"homenet inputs --instance {instance}",
            f"homenet preflight --instance {instance}",
            f"homenet deploy --instance {instance} --force --check-idempotent",
            f"homenet check --instance {instance}",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Worksheet contains secret names and storage hints only. It does not read or print secret values.",
        },
    }


def print_worksheet_markdown(worksheet: dict[str, Any]) -> None:
    instance = worksheet.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or Path(str(worksheet.get("instance_path", "instance"))).name
    print(f"# Deployment Worksheet - {name}")
    print()
    print(f"- schema: `{worksheet.get('schema')}`")
    print(f"- profile: `{worksheet.get('profile')}`")
    print(f"- read only: {worksheet.get('read_only')}")
    print(f"- writes files: {worksheet.get('writes_files')}")
    print(f"- writes live config: {worksheet.get('writes_live_config')}")
    print(f"- reads secret values: {worksheet.get('reads_secret_values')}")
    print()
    print("## Summary")
    print()
    for key, value in worksheet.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    for section in worksheet.get("sections", []):
        if not isinstance(section, dict):
            continue
        print(f"## {section.get('title')}")
        print()
        print(f"- status: `{section.get('status')}`")
        print(f"- owner: `{section.get('owner')}`")
        print(f"- next command: `{section.get('next_command')}`")
        print()
        print("| Item | Required | Status | Detail |")
        print("| --- | --- | --- | --- |")
        for item in section.get("items", []):
            if isinstance(item, dict):
                print(f"| {item.get('label', '')} | {'yes' if item.get('required') else 'optional'} | {item.get('status', '')} | {item.get('detail', '')} |")
        print()
    print("## Next Commands")
    print()
    for command in worksheet.get("next_commands", []):
        print(f"- `{command}`")
    print()


def build_module_plans(state: dict[str, Any], profile: str) -> list[dict[str, Any]]:
    site = state["site"]
    networks = state["networks"]
    wifi = state["wifi"]
    services = state["services"]
    intents = module_intents(site, profile)
    router = site.get("runtime", {}).get("router", {})
    server = site.get("runtime", {}).get("server", {})
    room_ap = site.get("runtime", {}).get("room_ap", {})
    router_host = router.get("host", "OpenWrt")
    server_host = server.get("host", "server")
    room_ap_host = room_ap.get("host", "")

    docker_containers = expected_docker_containers(services)
    server_service_ids = [
        str(service.get("id"))
        for service in services
        if service.get("runtime") == "server" and service.get("id")
    ]
    openwrt_service_ids = [
        str(service.get("id"))
        for service in services
        if service.get("runtime") == "openwrt" and service.get("id")
    ]

    modules: list[dict[str, Any]] = []

    modules.append({
        "id": "gateway-openwrt",
        "title": "OpenWrt Gateway",
        "placement": str(router_host),
        "inputs": [
            f"networks={', '.join(networks.keys())}",
            f"wifi={', '.join(item.get('ssid', key) for key, item in wifi.items() if isinstance(item, dict))}",
            f"services={', '.join(openwrt_service_ids) or 'none'}",
        ],
        "outputs": [
            "network / dhcp / firewall / wireless intent",
            "static DHCP leases for expected devices",
            "LAN, IoT, Guest, Maintenance Wi-Fi boundaries",
            "TProxy policy review when transparent_proxy is enabled",
        ],
        "checks": [
            f"SSH to {router_host}",
            "DHCP leases match fixed devices",
            "LuCI/SSH maintenance entries reachable",
            "Maintenance Wi-Fi can reach server runtime maintenance ports",
        ],
        "rollback": [
            "/etc/config/network",
            "/etc/config/dhcp",
            "/etc/config/firewall",
            "/etc/config/wireless",
        ],
    })

    dns_intent = intents.get("dns-layer", {})
    dns_feature = enabled_feature(site, "dns") or dns_intent
    if dns_intent.get("enabled") is not False:
        dns_services = service_ids_by_owner(services, {"adguardhome"}) or ["adguard"]
        modules.append({
            "id": "dns-layer",
            "title": "DNS Layer",
            "placement": module_runtime_placement(site, "dns-layer", dns_intent),
            "inputs": [
                f"implementation={dns_intent.get('implementation') or dns_feature.get('implementation', 'auto')}",
                "network dns_mode values",
                f"services={', '.join(dns_services)}",
            ],
            "outputs": [
                "AdGuard upstream split config",
                "OpenWrt dnsmasq forwarding to home DNS",
                "domestic real DNS and foreign fake-ip review",
            ],
            "checks": [
                "domestic domain returns real IP",
                "foreign domain returns fake-ip where expected",
                "AdGuard DNS port is listening",
                "OpenWrt DNS forwarding points to server runtime",
            ],
            "rollback": [
                "adguard/conf/AdGuardHome.yaml",
                "adguard/conf/upstream-domestic.conf",
                "OpenWrt dhcp dnsmasq server options",
            ],
        })

    proxy_intent = intents.get("proxy-mihomo", {})
    proxy_feature = enabled_feature(site, "proxy") or proxy_intent
    transparent_feature = enabled_feature(site, "transparent_proxy")
    if proxy_intent.get("enabled") is not False and (proxy_feature or transparent_feature):
        proxy_services = service_ids_by_owner(services, {"mihomo"}) or ["mihomo"]
        modules.append({
            "id": "proxy-mihomo",
            "title": "Mihomo Proxy",
            "placement": module_runtime_placement(site, "proxy-mihomo", proxy_intent),
            "inputs": [
                f"implementation={proxy_intent.get('implementation') or (proxy_feature or {}).get('implementation', 'mihomo')}",
                f"transparent_proxy={(transparent_feature or {}).get('implementation', 'disabled')}",
                f"ports={', '.join(service_ports_for(services, set(proxy_services))) or 'none'}",
            ],
            "outputs": [
                "Mihomo runtime config and rule providers",
                "explicit mixed proxy entry",
                "fake-ip DNS entry",
                "OpenWrt mangle/table 100 TProxy handoff",
            ],
            "checks": [
                "Mihomo controller API reachable",
                "proxy groups and route summary visible",
                "domestic IP bypass hits OpenWrt ipset",
                "foreign HTTPS reachable through proxy",
            ],
            "rollback": [
                "mihomo/config.yaml",
                "OpenWrt mangle rules and policy routing",
                "mihomo-gateway.service / mihomo-tproxy-route.service",
            ],
        })

    remote_intent = intents.get("remote-access", {})
    remote_feature = enabled_feature(site, "remote_access") or remote_intent
    if remote_intent.get("enabled") is not False and remote_feature:
        remote_services = service_ids_by_category(services, {"remote-entry"})
        modules.append({
            "id": "remote-access",
            "title": "Remote Access",
            "placement": module_runtime_placement(site, "remote-access", remote_intent),
            "inputs": [
                f"methods={', '.join(as_list(remote_intent.get('methods')) or as_list(remote_feature.get('methods')))}",
                f"domain={site.get('site', {}).get('domain', '-')}",
                f"services={', '.join(remote_services)}",
            ],
            "outputs": [
                "WireGuard LAN return path",
                "Cloudflare Tunnel / Access public hostnames",
                "Caddy IPv6/direct reverse proxy entries",
                "DDNS IPv6 update service",
            ],
            "checks": [
                "WireGuard clients and latest handshakes",
                "Cloudflare Tunnel container running",
                "remote HTTPS entries monitored by Kuma",
                "local and remote URLs stay paired in service inventory",
            ],
            "rollback": [
                "wg-easy data",
                "cloudflared tunnel config",
                "caddy/Caddyfile",
                "ddns-go config",
            ],
        })

    observability_intent = intents.get("observability-homenet", {})
    observability_feature = enabled_feature(site, "observability") or observability_intent
    if observability_intent.get("enabled") is not False and observability_feature:
        ops_services = service_ids_by_category(services, {"control-core", "system-task"})
        modules.append({
            "id": "observability-homenet",
            "title": "Observability",
            "placement": module_runtime_placement(site, "observability-homenet", observability_intent),
            "inputs": [
                f"implementation={observability_intent.get('implementation') or observability_feature.get('implementation', 'homenet+kuma')}",
                f"level={observability_feature.get('level', 'auto')}",
                f"services={', '.join(ops_services)}",
            ],
            "outputs": [
                "HomeNet Ops service directory and topology metadata",
                "Uptime Kuma monitors and status pages",
                "presence receiver and WireGuard status state",
                "read-only health checks",
            ],
            "checks": [
                "HomeNet API has no errors",
                "Kuma tracks external and LAN-critical entries",
                "Docker owners from instance are running",
                "instance metadata loads inside HomeNet Ops",
            ],
            "rollback": [
                "homenet-ops image and compose file",
                "maintenance/state generated files",
                "Kuma monitor export / database backup",
            ],
        })

    smart_home_intent = intents.get("smart-home", {})
    smart_home_feature = enabled_feature(site, "smart_home") or smart_home_intent
    if smart_home_intent.get("enabled") is not False and smart_home_feature:
        smart_services = service_ids_by_category(services, {"home-core"})
        modules.append({
            "id": "smart-home",
            "title": "Smart Home",
            "placement": module_runtime_placement(site, "smart-home", smart_home_intent),
            "inputs": [
                f"implementation={smart_home_intent.get('implementation') or smart_home_feature.get('implementation', 'home-assistant')}",
                f"services={', '.join(smart_services)}",
            ],
            "outputs": [
                "Home Assistant entry",
                "MQTT and Zigbee bridge entries",
                "camera/media bridge entries",
                "background data collection tasks",
            ],
            "checks": [
                "Home Assistant reachable",
                "Mosquitto TCP port listening",
                "Zigbee2MQTT UI reachable",
                "home-core containers from instance are running",
            ],
            "rollback": [
                "Home Assistant config backup",
                "Mosquitto / Zigbee2MQTT config volumes",
                "go2rtc config",
            ],
        })

    maintenance_wifi_intent = intents.get("maintenance-wifi", {})
    maintenance_wifi_feature = enabled_feature(site, "maintenance_wifi") or maintenance_wifi_intent
    if maintenance_wifi_intent.get("enabled") is not False and maintenance_wifi_feature:
        ops = networks.get("ops", {})
        modules.append({
            "id": "maintenance-wifi",
            "title": "Maintenance Wi-Fi",
            "placement": module_runtime_placement(site, "maintenance-wifi", maintenance_wifi_intent),
            "inputs": [
                f"ssid={wifi.get('ops', {}).get('ssid', 'Maintenance Wi-Fi')}",
                f"cidr={ops.get('cidr', '-')}",
                f"gateway={ops.get('gateway', '-')}",
            ],
            "outputs": [
                "isolated maintenance SSID",
                "direct WAN path bypassing transparent proxy",
                "limited access to server runtime SSH and HomeNet",
            ],
            "checks": [
                "Maintenance SSID enabled",
                "Maintenance DHCP range active",
                "Maintenance clients can reach server runtime maintenance ports",
                "Maintenance traffic bypasses OpenWrt MIHOMO_POLICY",
            ],
            "rollback": [
                "/etc/config/wireless",
                "/etc/config/network ops interface",
                "/etc/config/firewall ops zone/rules",
                "/etc/config/dhcp ops range",
            ],
        })

    modules.append({
        "id": "server-runtime",
        "title": "Server Runtime",
        "placement": str(server_host) if intents.get("server-runtime", {}).get("enabled") is not False else "none",
        "inputs": [
            f"profile={profile}",
            f"server_services={len(server_service_ids)}",
            f"docker_containers={', '.join(docker_containers)}",
        ],
        "outputs": [
            "Docker Compose services and host-network services",
            "systemd timers/services for generated tasks",
            "local state under maintenance/state",
        ],
        "checks": [
            "docker ps containers match instance",
            "critical systemd units active",
            "service ports match instance inventory",
        ],
        "rollback": [
            "docker-compose.yml per module",
            "systemd unit files",
            "service config volumes and backups",
        ],
    })

    if room_ap_host:
        modules.append({
            "id": "room-ap",
            "title": "Room AP / Relay",
            "placement": str(room_ap_host),
            "inputs": [
                f"type={room_ap.get('type', 'openwrt-relay')}",
                f"role={room_ap.get('role', '')}",
                f"main_ssid={wifi.get('main', {}).get('ssid', '-')}",
                f"backhaul_ssid={wifi.get('relay_5g', {}).get('ssid', '-')}",
            ],
            "outputs": [
                "bedroom coverage AP/relay configuration",
                "Room LuCI and SSH maintenance entries",
                "presence reporting for roaming visibility",
            ],
            "checks": [
                "Room AP LuCI/SSH reachable",
                "presence reporter sends fresh AP data",
                "clients in bedrooms prefer stronger room coverage where possible",
            ],
            "rollback": [
                "Room AP /etc/config/network",
                "Room AP /etc/config/wireless",
                "Room AP /etc/config/firewall",
            ],
        })

    return modules


def print_module_plan(module: dict[str, Any]) -> None:
    print(f"### {module['title']} ({module['id']})")
    print(f"Placement: {module['placement']}")
    for label in ("inputs", "outputs", "checks", "rollback"):
        print(f"{label.title()}:")
        for item in module.get(label, []):
            print(f"- {item}")
    print()


def build_plan(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    site = state["site"]
    networks = state["networks"]
    wifi = state["wifi"]
    services = state["services"]
    profile = infer_profile(site)
    intents = module_intents(site, profile)
    runtime = site.get("runtime", {}) if isinstance(site.get("runtime"), dict) else {}
    router = runtime.get("router", {}) if isinstance(runtime.get("router"), dict) else {}
    server = runtime.get("server", {}) if isinstance(runtime.get("server"), dict) else {}
    room_ap = runtime.get("room_ap", {}) if isinstance(runtime.get("room_ap"), dict) else {}

    service_inventory: dict[str, int] = {}
    for service in services:
        service_runtime = str(service.get("runtime", "unknown"))
        service_inventory[service_runtime] = service_inventory.get(service_runtime, 0) + 1

    module_placement = []
    for module_id, intent in intents.items():
        if not isinstance(intent, dict) or intent.get("enabled") is False:
            continue
        module_placement.append({
            "id": module_id,
            "implementation": intent.get("implementation", "auto"),
            "runtime": intent.get("runtime", "auto"),
            "placement": module_runtime_placement(site, module_id, intent),
            "fallback": intent.get("fallback", ""),
            "source": intent.get("source", "derived"),
            "methods": as_list(intent.get("methods")),
        })

    modules = build_module_plans(state, profile)
    capability_matrix = build_capability_matrix(state, profile, modules)

    return {
        "schema": "homenet.plan.v1",
        "instance": {
            "path": str(instance),
            "name": site.get("site", {}).get("name", ""),
            "display_name": site.get("site", {}).get("display_name") or site.get("site", {}).get("name", ""),
            "domain": site.get("site", {}).get("domain", ""),
        },
        "profile": profile,
        "runtime_targets": {
            "openwrt_gateway": router.get("host", ""),
            "server": {
                "enabled": server.get("enabled", False),
                "host": server.get("host", ""),
                "preferred": server.get("preferred", "auto"),
                "role": server.get("role", ""),
            },
            "room_ap": {
                "host": room_ap.get("host", ""),
                "type": room_ap.get("type", ""),
                "role": room_ap.get("role", ""),
            },
        },
        "networks": networks,
        "wifi": wifi,
        "module_placement": module_placement,
        "capability_matrix": capability_matrix,
        "service_inventory": dict(sorted(service_inventory.items())),
        "generated_artifacts_target": [
            "HomeNet metadata from site/devices/services instance files",
            "OpenWrt read-only comparison plan before any apply",
            "Service directory and port inventory for HomeNet Ops",
            "Module checks for Gateway, DNS, Proxy, Remote Access, Observability",
        ],
        "modules": modules,
        "apply": {
            "status": "dry_run_only",
            "read_only": True,
            "message": "`homenet apply --dry-run` is available; write-side apply is intentionally disabled.",
        },
    }


def print_plan(plan: dict[str, Any]) -> None:
    print(f"Instance: {plan['instance'].get('display_name')}")
    print(f"Profile:  {plan.get('profile')}")
    print()
    print("Runtime Targets")
    runtime_targets = plan.get("runtime_targets", {})
    print(f"- OpenWrt Gateway: {runtime_targets.get('openwrt_gateway')}")
    server = runtime_targets.get("server", {})
    if server.get("enabled") is not False and server.get("host"):
        print(f"- Server Runtime:  {server.get('host')} ({server.get('preferred', 'auto')})")
    room_ap = runtime_targets.get("room_ap", {})
    if room_ap.get("host"):
        print(f"- Room AP:         {room_ap.get('host')} ({room_ap.get('type', 'ap')})")

    print()
    print("Networks")
    for net_id, net in plan.get("networks", {}).items():
        if not isinstance(net, dict) or net.get("enabled") is False:
            continue
        purpose = net.get("purpose", "")
        print(f"- {net_id}: {net.get('cidr')} gateway={net.get('gateway', '-')} dns={net.get('dns_mode', '-')} proxy={net.get('proxy_mode', '-')} | {purpose}")

    print()
    print("Wi-Fi / SSID")
    for wifi_id, item in plan.get("wifi", {}).items():
        if not isinstance(item, dict):
            continue
        print(f"- {item.get('ssid')} ({wifi_id}): network={item.get('network')} band={item.get('band', '-')} | {item.get('purpose', '')}")

    print()
    print("Module Placement")
    for feature in plan.get("module_placement", []):
        detail = f" methods={','.join(feature.get('methods', []))}" if feature.get("methods") else ""
        fallback = f" fallback={feature.get('fallback')}" if feature.get("fallback") else ""
        print(
            f"- {feature.get('id')}: {feature.get('implementation')} "
            f"runtime={feature.get('runtime', '-')} on {feature.get('placement')} "
            f"source={feature.get('source', '-')}{fallback}{detail}"
        )

    print()
    print("Runtime Capability")
    for capability in plan.get("capability_matrix", []):
        required = "required" if capability.get("required") else "optional"
        placement = capability.get("current_placement") or capability.get("fallback") or "-"
        print(
            f"- {capability.get('id')}: {capability.get('current_status')} "
            f"({required}) placement={placement} fallback={capability.get('fallback')}"
        )

    print()
    print("Service Inventory")
    for runtime, count in plan.get("service_inventory", {}).items():
        print(f"- {runtime}: {count} service(s)")

    print()
    print("Generated Artifacts Target")
    for item in plan.get("generated_artifacts_target", []):
        print(f"- {item}")

    print()
    print("Module Plans")
    for module in plan.get("modules", []):
        print_module_plan(module)

    print()
    print("Apply Status")
    print("- No changes applied. This plan is read-only.")
    print(f"- {plan.get('apply', {}).get('message', '`homenet apply --dry-run` is available; write-side apply is intentionally disabled.')}")


def module_enabled_map(site: dict[str, Any], profile: str) -> dict[str, bool]:
    return {
        module_id: intent.get("enabled") is not False
        for module_id, intent in module_intents(site, profile).items()
    }


def build_metadata(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    plan = build_plan(state, instance)
    site = state["site"]
    devices = state["devices"]
    services = state["services"]
    enabled_by_module = module_enabled_map(site, str(plan.get("profile") or infer_profile(site)))
    service_directory = build_service_directory(services, enabled_by_module)
    port_inventory = build_port_inventory(services, enabled_by_module)
    kuma_inventory = build_kuma_inventory(services, enabled_by_module)
    disabled_services = [row for row in service_directory if row.get("module_enabled") is False]
    services_by_module: dict[str, dict[str, int]] = {}
    for row in service_directory:
        module_id = str(row.get("module_id") or "unknown")
        bucket = services_by_module.setdefault(module_id, {"total": 0, "active": 0, "disabled": 0})
        bucket["total"] += 1
        if row.get("module_enabled") is False:
            bucket["disabled"] += 1
        else:
            bucket["active"] += 1
    return {
        "schema": "homenet.metadata.v1",
        "instance": plan["instance"],
        "profile": plan["profile"],
        "runtime_targets": plan["runtime_targets"],
        "networks": state["networks"],
        "wifi": state["wifi"],
        "remote_ingress": sorted(
            [
                {
                    "id": entry.get("id") or "",
                    "name": entry.get("name") or entry.get("id") or "",
                    "kind": entry.get("kind") or "external",
                    "href": entry.get("href") or "",
                    "target": entry.get("target") or "",
                    "service_id": entry.get("service_id") or "",
                    "status_source": entry.get("status_source") or "static",
                }
                for entry in state.get("remote_ingress", [])
                if isinstance(entry, dict)
            ],
            key=lambda item: str(item.get("id", "")),
        ),
        "devices": sorted(
            [
                {
                    "id": device.get("id") or "",
                    "name": device.get("name") or device.get("id") or "",
                    "role": device.get("role") or "",
                    "network": device.get("network") or "",
                    "ip": device.get("ip") or "",
                    "hostnames": as_list(device.get("hostnames")),
                    "expected": device.get("expected", True),
                    "presence": device.get("presence") or "",
                    "notes": device.get("notes") or "",
                }
                for device in devices
                if isinstance(device, dict)
            ],
            key=lambda item: (str(item.get("network", "")), str(item.get("ip", "")), str(item.get("id", ""))),
        ),
        "service_directory": service_directory,
        "port_inventory": port_inventory,
        "kuma_inventory": kuma_inventory,
        "module_service_summary": {
            "services_by_module": dict(sorted(services_by_module.items())),
            "disabled_services": len(disabled_services),
            "disabled_service_ids": [str(row.get("id") or "") for row in disabled_services],
            "kuma_candidates_exclude_disabled_modules": True,
        },
        "module_plan": plan["modules"],
        "module_placement": plan["module_placement"],
        "capability_matrix": plan["capability_matrix"],
        "service_inventory": plan["service_inventory"],
        "apply": plan["apply"],
        "source_files": [
            str(instance / "site.yaml"),
            str(instance / "devices.yaml"),
            str(instance / "services.yaml"),
        ],
        "privacy": {
            "secrets_included": False,
            "note": "Metadata intentionally excludes passwords, tokens, private keys, cookies, sessions, and proxy subscription URLs.",
        },
        "site": site.get("site", {}) if isinstance(site.get("site"), dict) else {},
    }


def build_topology(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    metadata = build_metadata(state, instance)
    return build_topology_from_metadata(metadata, instance, as_list)


def print_topology_markdown(topology: dict[str, Any]) -> None:
    print_topology_markdown_impl(topology, as_list)



def build_status_dashboard(
    state: dict[str, Any],
    instance: Path,
    *,
    live: bool = False,
    live_reporter: Reporter | None = None,
) -> dict[str, Any]:
    metadata = build_metadata(state, instance)
    plan = build_plan(state, instance)
    rescue = build_rescue_guide(metadata, instance)
    kuma = build_kuma_export(metadata)
    readiness = build_readiness(state, instance)
    services = [
        service
        for service in metadata.get("service_directory", [])
        if isinstance(service, dict)
    ]
    services_by_id = {str(service.get("id") or ""): service for service in services}

    def service_entry(service_id: str, purpose: str) -> dict[str, Any] | None:
        service = services_by_id.get(service_id)
        if not service:
            return None
        return {
            "id": service_id,
            "name": service.get("name") or service_id,
            "category": service.get("category") or "",
            "runtime": service.get("runtime") or "",
            "host": service.get("host") or "",
            "local_url": service.get("local_url") or "",
            "remote_url": service.get("remote_url") or "",
            "purpose": purpose,
        }

    daily_entries = [
        entry
        for entry in [
            service_entry("homenet-ops", "Daily status, service directory, topology, and operations entry."),
            service_entry("uptime-kuma", "Availability alerts and notification history."),
            service_entry("openwrt-luci", "Gateway, DHCP, firewall, Wi-Fi, and routing source tool."),
            service_entry("mihomo", "Proxy providers, route groups, and transparent proxy behavior."),
            service_entry("adguard", "DNS split, filtering, and upstream behavior."),
            service_entry("home-assistant", "Smart home state and automations."),
            service_entry("wireguard", "Return-home peers and remote LAN access."),
        ]
        if entry
    ]

    enabled_networks = [
        {"id": net_id, **net}
        for net_id, net in metadata.get("networks", {}).items()
        if isinstance(net, dict) and net.get("enabled") is not False
    ]
    enabled_wifi = [
        {"id": wifi_id, **item}
        for wifi_id, item in metadata.get("wifi", {}).items()
        if isinstance(item, dict)
    ]
    module_state = [
        {
            "id": module.get("id") or "",
            "title": module.get("title") or module.get("id") or "",
            "status": module.get("status") or "",
            "placement": module.get("placement") or "",
            "runtime_options": as_list(module.get("runtime_options")),
            "checks": len(as_list(module.get("checks"))),
            "outputs": len(as_list(module.get("outputs"))),
        }
        for module in plan.get("modules", [])
        if isinstance(module, dict)
    ]

    live_summary: dict[str, Any] = {
        "checked": False,
        "ok": None,
        "failures": 0,
        "warnings": 0,
        "top_findings": [],
    }
    if live:
        reporter = live_reporter or Reporter()
        if live_reporter is None:
            check_live(state, instance, reporter)
        findings = [
            finding
            for finding in reporter.findings
            if finding.level in {"FAIL", "WARN"}
        ]
        failures = [finding for finding in findings if finding.level == "FAIL"]
        warnings = [finding for finding in findings if finding.level == "WARN"]
        diagnostic_findings = summarize_live_diagnostic_findings(findings)
        live_summary = {
            "checked": True,
            "ok": not failures,
            "failures": len(failures),
            "warnings": len(warnings),
            "classified_findings": diagnostic_findings.get("classified_findings", []),
            "domain_counts": diagnostic_findings.get("domain_counts", {}),
            "top_findings": [
                {
                    "level": finding.level,
                    "area": finding.area,
                    "message": finding.message,
                    "domains": classify_live_diagnostic_domains(finding.area, finding.message),
                }
                for finding in findings[:12]
            ],
        }

    diagnostic_surface = build_diagnostic_surface(metadata, rescue, live_summary, live=live)

    next_actions: list[str] = []
    if live_summary.get("checked") and live_summary.get("failures"):
        next_actions.append("Open Diagnostic Surface first; fix the failing domain before touching unrelated services.")
    if live_summary.get("checked") and live_summary.get("warnings") and not live_summary.get("failures"):
        next_actions.append("Review degraded diagnostic domains; they may explain slow, intermittent, or missing-device behavior.")
    if not readiness.get("ready_for_apply"):
        next_actions.append("Keep live changes in source tools; HomeNet write-side apply is still gated by review, backup, and live verification.")
    next_actions.append("Use HomeNet for status, explanation, and navigation; use Kuma for alerts; use source tools for authoritative edits.")

    return {
        "schema": "homenet.status.v1",
        "instance": metadata.get("instance") or {},
        "instance_path": str(instance),
        "profile": metadata.get("profile"),
        "live": live,
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "summary": {
            "services": len(services),
            "ports": len(metadata.get("port_inventory", [])),
            "devices": len(metadata.get("devices", [])),
            "networks": len(enabled_networks),
            "wifi": len(enabled_wifi),
            "modules": len(module_state),
            "remote_entries": len(metadata.get("remote_ingress", [])),
            "daily_entries": len(daily_entries),
            "kuma_monitors": kuma.get("monitor_count", 0),
            "kuma_auto": kuma.get("auto_importable_count", 0),
            "ready_for_review": readiness.get("ready_for_review"),
            "ready_for_apply": readiness.get("ready_for_apply"),
            "diagnostic_domains": diagnostic_surface.get("summary", {}).get("domains", 0),
            "diagnostic_first_probes": diagnostic_surface.get("summary", {}).get("first_probes", 0),
            "diagnostic_live_findings": diagnostic_surface.get("summary", {}).get("live_findings", 0),
            "diagnostic_classified_findings": diagnostic_surface.get("summary", {}).get("classified_findings", 0),
            "diagnostic_domains_with_live_findings": diagnostic_surface.get("summary", {}).get("domains_with_live_findings", 0),
        },
        "diagnostic_surface": diagnostic_surface,
        "daily_entries": daily_entries,
        "runtime_targets": metadata.get("runtime_targets") or {},
        "networks": enabled_networks,
        "wifi": enabled_wifi,
        "module_state": module_state,
        "remote_ingress": metadata.get("remote_ingress", []),
        "maintenance": {
            "ops_network": rescue.get("maintenance_network") or {},
            "local_entries": rescue.get("local_entries", [])[:8],
            "ssh_targets": rescue.get("ssh_targets", []),
            "failure_modes": rescue.get("failure_modes", []),
        },
        "live_status": live_summary,
        "next_actions": next_actions,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Status summarizes metadata and optional live finding counts only. It does not include passwords, tokens, keys, cookies, sessions, or subscription URLs.",
        },
    }


def print_status_markdown(status: dict[str, Any]) -> None:
    instance = status.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or Path(str(status.get("instance_path", "instance"))).name
    print(f"# HomeNet Status - {name}")
    print()
    print(f"- schema: `{status.get('schema')}`")
    print(f"- profile: `{status.get('profile')}`")
    print(f"- live: {status.get('live')}")
    print(f"- read only: {status.get('read_only')}")
    print(f"- writes files: {status.get('writes_files')}")
    print(f"- writes live config: {status.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in status.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    diagnostic = status.get("diagnostic_surface", {}) if isinstance(status.get("diagnostic_surface"), dict) else {}
    if diagnostic:
        print("## Diagnostic Surface")
        print()
        print(diagnostic.get("headline") or "")
        print()
        print("| Status | Domain | Live | Scope | First Probe | Owner | If Bad |")
        print("| --- | --- | --- | --- | --- | --- | --- |")
        for domain in as_list(diagnostic.get("domains")):
            if not isinstance(domain, dict):
                continue
            live_evidence = domain.get("live_evidence", {}) if isinstance(domain.get("live_evidence"), dict) else {}
            live_cell = (
                f"fail={live_evidence.get('failures', 0)} warn={live_evidence.get('warnings', 0)}"
                if live_evidence.get("checked")
                else "not checked"
            )
            print(
                f"| `{domain.get('status', '')}` | {domain.get('title', '')} | {live_cell} | {domain.get('scope', '')} | "
                f"`{domain.get('first_probe', '')}` | {domain.get('primary_owner', '')} | {domain.get('if_bad', '')} |"
            )
        print()
        print("Operator rule:", diagnostic.get("operator_rule") or "")
        print()
    print("## Daily Entries")
    print()
    print("| Service | Purpose | Local | Remote | Runtime |")
    print("| --- | --- | --- | --- | --- |")
    for entry in status.get("daily_entries", []):
        if isinstance(entry, dict):
            print(
                f"| {entry.get('name', '')} | {entry.get('purpose', '')} | "
                f"{entry.get('local_url', '')} | {entry.get('remote_url', '')} | {entry.get('runtime', '')} |"
            )
    print()
    print("## Runtime Targets")
    print()
    runtime = status.get("runtime_targets", {}) if isinstance(status.get("runtime_targets"), dict) else {}
    print(f"- OpenWrt Gateway: {runtime.get('openwrt_gateway') or ''}")
    server = runtime.get("server", {}) if isinstance(runtime.get("server"), dict) else {}
    room_ap = runtime.get("room_ap", {}) if isinstance(runtime.get("room_ap"), dict) else {}
    if server:
        print(f"- Server Runtime: {server.get('host') or ''} enabled={server.get('enabled')} preferred={server.get('preferred') or ''}")
    if room_ap:
        print(f"- Room AP: {room_ap.get('host') or ''} type={room_ap.get('type') or ''}")
    print()
    print("## Networks / Wi-Fi")
    print()
    print("| Network | CIDR | Gateway | DNS | Proxy | Purpose |")
    print("| --- | --- | --- | --- | --- | --- |")
    for network in status.get("networks", []):
        if isinstance(network, dict):
            print(
                f"| {network.get('id', '')} | {network.get('cidr', '')} | {network.get('gateway', '')} | "
                f"{network.get('dns_mode', '')} | {network.get('proxy_mode', '')} | {network.get('purpose', '')} |"
            )
    print()
    print("| SSID | Network | Band | Purpose |")
    print("| --- | --- | --- | --- |")
    for wifi in status.get("wifi", []):
        if isinstance(wifi, dict):
            print(f"| {wifi.get('ssid', '')} | {wifi.get('network', '')} | {wifi.get('band', '')} | {wifi.get('purpose', '')} |")
    print()
    print("## Module State")
    print()
    print("| Module | Status | Placement | Checks | Outputs |")
    print("| --- | --- | --- | --- | --- |")
    for module in status.get("module_state", []):
        if isinstance(module, dict):
            print(
                f"| {module.get('title', '')} | {module.get('status', '')} | {module.get('placement', '')} | "
                f"{module.get('checks', '')} | {module.get('outputs', '')} |"
            )
    print()
    print("## Remote Ingress")
    print()
    print("| Name | Kind | URL | Target | Source |")
    print("| --- | --- | --- | --- | --- |")
    for entry in status.get("remote_ingress", []):
        if isinstance(entry, dict):
            print(
                f"| {entry.get('name', '')} | {entry.get('kind', '')} | {entry.get('href', '')} | "
                f"{entry.get('target', '')} | {entry.get('status_source', '')} |"
            )
    print()
    live_status = status.get("live_status", {}) if isinstance(status.get("live_status"), dict) else {}
    print("## Live Status")
    print()
    print(f"- checked: {live_status.get('checked')}")
    print(f"- ok: {live_status.get('ok')}")
    print(f"- failures: {live_status.get('failures')}")
    print(f"- warnings: {live_status.get('warnings')}")
    if live_status.get("top_findings"):
        print()
        for finding in live_status.get("top_findings", []):
            if isinstance(finding, dict):
                print(f"- {finding.get('level')} {finding.get('area')}: {finding.get('message')}")
    print()
    print("## Maintenance")
    print()
    maintenance = status.get("maintenance", {}) if isinstance(status.get("maintenance"), dict) else {}
    ops_network = maintenance.get("ops_network", {}) if isinstance(maintenance.get("ops_network"), dict) else {}
    print(f"- Maintenance network: {ops_network.get('cidr', '')} gateway={ops_network.get('gateway', '')} dns={ops_network.get('dns_mode', '')} proxy={ops_network.get('proxy_mode', '')}")
    if maintenance.get("ssh_targets"):
        print("- SSH targets:")
        for target in maintenance.get("ssh_targets", []):
            if isinstance(target, dict):
                print(f"  - {target.get('name')}: {target.get('command')}")
    print()
    print("## Next Actions")
    print()
    for action in status.get("next_actions", []):
        print(f"- {action}")
    print()


def classify_doctor_finding(message: str) -> dict[str, Any]:
    text = message.lower()
    if "weak 5ghz" in text or "weak" in text and "client" in text:
        return {
            "domain": "wifi",
            "severity": "warn",
            "title": "Weak Wi-Fi client",
            "likely_cause": "A client is associated with a weak 5GHz signal or did not roam to the better AP.",
            "first_actions": [
                "Identify the client from OpenWrt wireless association details.",
                "Check whether it should be near the Room AP or main Gateway.",
                "Use topology to confirm the client path, then tune placement/roaming only if this is recurring.",
            ],
            "source_tools": ["OpenWrt LuCI/SSH", "client Wi-Fi diagnostics", "HomeNet topology"],
            "related_runbook": "room-ap-or-roaming-bad",
            "related_topology_path": "room-coverage",
        }
    if "remote ingress" in text and ("not reachable" in text or "timed out" in text or "could not connect" in text):
        return {
            "domain": "remote-access",
            "severity": "warn",
            "title": "Remote ingress is degraded",
            "likely_cause": "A public entry, tunnel, Access app, IPv6 direct path, or upstream internet path is not answering from this check context.",
            "first_actions": [
                "Check the paired LAN service URL first.",
                "If LAN is healthy, inspect the matching Cloudflare Tunnel/Access, Caddy/DDNS, or IPv6 direct owner.",
                "Use Kuma for history; do not change the service until the local target is proven down.",
            ],
            "source_tools": ["HomeNet status", "Uptime Kuma", "Cloudflare Dashboard", "Caddy/DDNS", "WireGuard"],
            "related_runbook": "remote-access-fails",
            "related_topology_path": "remote-web",
        }
    if "cloudflare" in text and ("api unavailable" in text or "api" in text):
        return {
            "domain": "cloudflare-provider",
            "severity": "warn",
            "title": "Cloudflare provider check is unavailable",
            "likely_cause": "The local check could not read Cloudflare provider state; the tunnel or app may still work through cached/runtime state.",
            "first_actions": [
                "Compare remote entry HTTP checks with Cloudflare provider API status.",
                "Confirm token/network reachability from the Pi before changing tunnel or Access configuration.",
                "Use Cloudflare Dashboard as the source tool if provider state is needed.",
            ],
            "source_tools": ["Cloudflare Dashboard/API", "cloudflared", "HomeNet status"],
            "related_runbook": "remote-access-fails",
            "related_topology_path": "remote-web",
        }
    if "mangle chain" in text or "mihomo" in text and "cannot query" in text:
        return {
            "domain": "proxy-policy",
            "severity": "info",
            "title": "Local mangle-chain check is context-limited",
            "likely_cause": "The command context cannot inspect the local MIHOMO/MIHOMO6 chain even though OpenWrt policy evidence may still pass.",
            "first_actions": [
                "Use OpenWrt policy checks and connectivity checks as stronger evidence.",
                "Only inspect Pi iptables directly when proxy routing symptoms exist.",
                "Do not change proxy rules just because this context-limited check warns.",
            ],
            "source_tools": ["OpenWrt SSH", "Mihomo Dashboard/API", "Pi shell"],
            "related_runbook": "dns-proxy-routing-wrong",
            "related_topology_path": "foreign-proxy",
        }
    if "not seen in current dhcp leases" in text:
        return {
            "domain": "device-presence",
            "severity": "warn",
            "title": "Expected device is not in DHCP leases",
            "likely_cause": "The device may be offline, sleeping, on another SSID/MAC, or using a lease not visible in the current snapshot.",
            "first_actions": [
                "Check whether the device is powered and expected to be online.",
                "Use OpenWrt DHCP/static lease view for the declared network.",
                "For IoT and Apple/private-MAC cases, confirm the SSID-specific MAC before changing fixed IPs.",
            ],
            "source_tools": ["OpenWrt DHCP/static leases", "device native UI", "Home Assistant"],
            "related_runbook": "iot-or-smart-home-device-missing",
            "related_topology_path": "iot-smart-home",
        }
    return {
        "domain": "general",
        "severity": "warn",
        "title": "Live finding needs review",
        "likely_cause": "The live check produced a warning or failure that does not match a specific HomeNet doctor rule yet.",
        "first_actions": [
            "Read the raw finding.",
            "Use ownership to find the source tool.",
            "Add a more specific doctor mapping if this recurs.",
        ],
        "source_tools": ["HomeNet status", "HomeNet ownership"],
        "related_runbook": "",
        "related_topology_path": "",
    }


def build_doctor_triage_domains(
    metadata: dict[str, Any],
    status: dict[str, Any],
    runbook: dict[str, Any],
    issues: list[dict[str, Any]],
    *,
    live: bool,
) -> list[dict[str, Any]]:
    runtime = metadata.get("runtime_targets", {}) if isinstance(metadata.get("runtime_targets"), dict) else {}
    networks = metadata.get("networks", {}) if isinstance(metadata.get("networks"), dict) else {}
    wifi = metadata.get("wifi", {}) if isinstance(metadata.get("wifi"), dict) else {}
    maintenance = status.get("maintenance", {}) if isinstance(status.get("maintenance"), dict) else {}
    local_entries = [
        entry
        for entry in as_list(maintenance.get("local_entries"))
        if isinstance(entry, dict)
    ]
    remote_entries = [
        entry
        for entry in as_list(status.get("remote_ingress"))
        if isinstance(entry, dict)
    ] or [
        entry
        for entry in as_list(metadata.get("remote_ingress"))
        if isinstance(entry, dict)
    ]
    runbook_scenarios = {
        str(scenario.get("id") or ""): scenario
        for scenario in as_list(runbook.get("scenarios"))
        if isinstance(scenario, dict)
    }

    def entry_ids(*ids: str) -> list[dict[str, Any]]:
        wanted = set(ids)
        return [
            {
                "id": str(entry.get("id") or ""),
                "name": entry.get("name") or entry.get("id") or "",
                "target": entry.get("target") or entry.get("local_url") or entry.get("remote_url") or "",
                "dependency": entry.get("dependency") or "",
            }
            for entry in local_entries
            if str(entry.get("id") or "") in wanted
        ]

    def scenario_checks(scenario_id: str, limit: int = 3) -> list[str]:
        scenario = runbook_scenarios.get(scenario_id) or {}
        return [str(item) for item in as_list(scenario.get("check_order"))[:limit]]

    issue_domain_map = {
        "wifi": "wifi-radio",
        "remote-access": "remote-access",
        "cloudflare-provider": "remote-access",
        "proxy-policy": "dns-proxy",
        "device-presence": "client-device",
        "general": "general",
        "evidence": "evidence",
    }
    issue_status_by_domain: dict[str, str] = {}
    for issue in issues:
        mapped = issue_domain_map.get(str(issue.get("domain") or ""), str(issue.get("domain") or "general"))
        level = str(issue.get("level") or "warn")
        status_value = "bad" if level == "fail" else ("warn" if level == "warn" else "info")
        current = issue_status_by_domain.get(mapped)
        if current == "bad" or (current == "warn" and status_value != "bad"):
            continue
        issue_status_by_domain[mapped] = status_value

    def domain_status(domain_id: str, aliases: list[str] | None = None) -> str:
        keys = [domain_id, *(aliases or [])]
        for key in keys:
            if issue_status_by_domain.get(key) in {"bad", "warn"}:
                return str(issue_status_by_domain[key])
        if live:
            return "ok"
        return "unknown"

    gateway = str(runtime.get("openwrt_gateway") or "")
    server = runtime.get("server", {}) if isinstance(runtime.get("server"), dict) else {}
    server_host = str(server.get("host") or "")
    room_ap = runtime.get("room_ap", {}) if isinstance(runtime.get("room_ap"), dict) else {}
    room_host = str(room_ap.get("host") or "")
    ops_network = maintenance.get("ops_network", {}) if isinstance(maintenance.get("ops_network"), dict) else {}
    lan = networks.get("lan", {}) if isinstance(networks.get("lan"), dict) else {}
    ops = networks.get("ops", {}) if isinstance(networks.get("ops"), dict) else {}
    main_wifi = wifi.get("main", {}) if isinstance(wifi.get("main"), dict) else {}
    relay_wifi = wifi.get("relay_5g", {}) if isinstance(wifi.get("relay_5g"), dict) else {}

    domains = [
        {
            "id": "gateway-wan",
            "title": "Gateway / WAN",
            "status": domain_status("gateway-wan", ["gateway", "general"]),
            "scope": f"OpenWrt {gateway or 'gateway'}; LAN {lan.get('cidr') or ''}",
            "symptom": "所有客户端无网、DHCP 异常、LAN IP 不通、拨号/WAN 不稳定。",
            "prove_ok": [
                "OpenWrt LuCI or SSH reachable by direct IP.",
                "WAN interface has carrier/session and byte counters move.",
                "LAN clients receive expected gateway and DNS for their network.",
            ],
            "first_entries": entry_ids("openwrt-luci", "openwrt-ssh"),
            "source_tools": ["OpenWrt LuCI", "OpenWrt SSH", "ISP modem/admin page"],
            "related_runbook": "wifi-connected-no-internet",
            "related_topology_path": "lan-client",
            "next_action": "If this domain is not proven healthy, stop debugging Pi, DNS, Proxy, or remote ingress first.",
        },
        {
            "id": "wifi-radio",
            "title": "Wi-Fi Radios / SSIDs",
            "status": domain_status("wifi-radio", ["wifi"]),
            "scope": f"main={main_wifi.get('ssid') or '-'} backhaul={relay_wifi.get('ssid') or '-'}",
            "symptom": "Wi-Fi 连不上、断电来电后 5G 不起、客户端显示无互联网、信号/漫游不稳定。",
            "prove_ok": [
                "Expected SSIDs are broadcasting on the intended radios.",
                "Client association/RSSI matches the room where the client is located.",
                "DHCP lease appears in the expected network after association.",
            ],
            "first_entries": entry_ids("openwrt-luci", "openwrt-ssh"),
            "source_tools": ["OpenWrt wireless status", "client Wi-Fi diagnostics", "HomeNet topology"],
            "related_runbook": "wifi-connected-no-internet",
            "related_topology_path": "main-wifi",
            "next_action": "After power loss, prove the main radio/backhaul radio is up before touching DNS or Proxy.",
        },
        {
            "id": "room-ap",
            "title": "Room AP / Coverage",
            "status": domain_status("room-ap", ["wifi"]),
            "scope": f"room_ap={room_host or '-'}",
            "symptom": "卧室网络慢、设备进入卧室后不自动切、房间 AP 在线但覆盖体验差。",
            "prove_ok": [
                "Room AP is reachable by its management IP.",
                "Room AP upstream/backhaul is associated and stable.",
                "Room clients obtain LAN DHCP from the gateway, not a second DHCP server.",
            ],
            "first_entries": entry_ids("wrt-room-luci", "wrt-room-ssh", "openwrt-luci"),
            "source_tools": ["Room AP LuCI/SSH", "OpenWrt wireless status", "client Wi-Fi diagnostics"],
            "related_runbook": "room-ap-or-roaming-bad",
            "related_topology_path": "room-coverage",
            "next_action": "If main Wi-Fi is healthy but bedroom is not, isolate Room AP/backhaul before changing global Wi-Fi.",
        },
        {
            "id": "dns-proxy",
            "title": "DNS / Proxy",
            "status": domain_status("dns-proxy", ["proxy-policy"]),
            "scope": "AdGuard or router DNS + Mihomo or declared proxy runtime",
            "symptom": "国内软件开代理很慢、国外服务打不开、能 ping IP 但域名失败、AI 节点走错组。",
            "prove_ok": [
                "Domestic test domain returns real IP through the intended DNS path.",
                "Foreign/proxy test domain follows the intended fake-ip or rule path.",
                "Mihomo provider/group health matches the route actually selected by rules.",
            ],
            "first_entries": entry_ids("adguard", "mihomo", "openwrt-ssh"),
            "source_tools": ["AdGuard/router DNS", "Mihomo Dashboard/API", "OpenWrt policy routing"],
            "related_runbook": "dns-proxy-routing-wrong",
            "related_topology_path": "foreign-proxy",
            "next_action": "Separate DNS answer problems from proxy route/group problems; change only the owning source config.",
        },
        {
            "id": "server-runtime",
            "title": "Server Runtime",
            "status": domain_status("server-runtime", ["general"]),
            "scope": f"server={server_host or 'none'}",
            "symptom": "HomeNet、Kuma、Mihomo、AdGuard、WireGuard、HA 等多个服务一起掉。",
            "prove_ok": [
                "Server host is reachable by SSH or direct LAN IP.",
                "Core containers/systemd units are running.",
                "Expected service ports are listening locally before checking remote domains.",
            ],
            "first_entries": entry_ids("pi-ssh", "homenet-ops", "uptime-kuma"),
            "source_tools": ["server SSH", "Docker", "systemd", "service-native dashboards"],
            "related_runbook": "server-runtime-down",
            "related_topology_path": "server-runtime",
            "next_action": "If several server-hosted services fail together, treat it as one runtime incident first.",
        },
        {
            "id": "remote-access",
            "title": "Remote Access",
            "status": domain_status("remote-access", ["cloudflare-provider"]),
            "scope": f"{len(remote_entries)} declared remote entr{'y' if len(remote_entries) == 1 else 'ies'}",
            "symptom": "外网域名打不开、Cloudflare Access 到不了后端、WireGuard 能上网但不能回家。",
            "prove_ok": [
                "The paired LAN/local target works first.",
                "Tunnel, Access app, Caddy/DDNS, or WireGuard peer state matches the entry type.",
                "Kuma or another external monitor agrees with the expected public entry.",
            ],
            "first_entries": entry_ids("homenet-ops", "wireguard", "pi-ssh"),
            "source_tools": ["Cloudflare Dashboard/API", "cloudflared", "Caddy/DDNS", "WireGuard", "Kuma"],
            "related_runbook": "remote-access-fails",
            "related_topology_path": "remote-web",
            "next_action": "Do not diagnose a public-domain failure until the LAN target for the same service is checked.",
        },
        {
            "id": "rescue-path",
            "title": "Rescue / Maintenance Path",
            "status": domain_status("rescue-path", ["evidence"]),
            "scope": f"ops={ops.get('cidr') or ops_network.get('cidr') or '-'} dns={ops.get('dns_mode') or ops_network.get('dns_mode') or '-'} proxy={ops.get('proxy_mode') or ops_network.get('proxy_mode') or '-'}",
            "symptom": "主 DNS/Proxy/Wi-Fi 异常时，需要仍能从其他设备进 Pi/OpenWrt 让 Codex 辅助排障。",
            "prove_ok": [
                "Maintenance path uses direct IP and does not depend on the broken DNS/proxy stack.",
                "Client can reach internet independently enough to access operator tools.",
                "Client can still reach Pi/OpenWrt by allowed LAN IP/SSH/HomeNet target.",
            ],
            "first_entries": entry_ids("pi-ssh", "homenet-ops", "openwrt-ssh"),
            "source_tools": ["Maintenance Wi-Fi/LAN", "OpenWrt firewall/DHCP", "Pi SSH", "HomeNet"],
            "related_runbook": "codex-maintenance-path-needed",
            "related_topology_path": "ops-maintenance",
            "next_action": "Keep this path simple and independent; use it to observe and repair rather than redesign normal traffic.",
        },
        {
            "id": "client-device",
            "title": "Client / Device Identity",
            "status": domain_status("client-device", ["device-presence"]),
            "scope": "DHCP leases, static mappings, hostnames, SSID-specific MACs",
            "symptom": "某个设备固定 IP 不对、Apple 私有 MAC 改变、.local/.lan 名字不通、IoT 设备消失。",
            "prove_ok": [
                "The device is present in DHCP/neighbour evidence on the expected network.",
                "Static IP binding matches the MAC used on that SSID.",
                "Service references use the declared stable IP or hostname for that device class.",
            ],
            "first_entries": entry_ids("openwrt-luci", "homenet-ops"),
            "source_tools": ["OpenWrt DHCP/static leases", "device native UI", "Home Assistant", "HomeNet instance files"],
            "related_runbook": "iot-or-smart-home-device-missing",
            "related_topology_path": "iot-smart-home",
            "next_action": "For Apple/private-MAC clients, verify the observed SSID-specific MAC before changing fixed IPs.",
        },
    ]

    for domain in domains:
        related = [
            issue
            for issue in issues
            if issue_domain_map.get(str(issue.get("domain") or ""), str(issue.get("domain") or "")) in {domain["id"], *(domain.get("aliases") or [])}
        ]
        domain["related_issues"] = [str(issue.get("id") or "") for issue in related]
        if not domain.get("first_entries"):
            domain["first_entries"] = []
        if not domain.get("prove_ok"):
            domain["prove_ok"] = scenario_checks(str(domain.get("related_runbook") or ""))
    return domains


def build_doctor(
    state: dict[str, Any],
    instance: Path,
    *,
    live: bool = False,
    live_reporter: Reporter | None = None,
) -> dict[str, Any]:
    metadata = build_metadata(state, instance)
    topology = build_topology(state, instance)
    runbook = build_runbook(state, instance)
    ownership = build_ownership_map(metadata, build_artifact_manifest(metadata), instance)
    reporter = live_reporter
    if live and reporter is None:
        reporter = Reporter()
        check_live(state, instance, reporter)
    status = build_status_dashboard(state, instance, live=live, live_reporter=reporter)

    findings = []
    if reporter is not None:
        findings = [
            finding
            for finding in reporter.findings
            if finding.level in {"FAIL", "WARN"}
        ]

    issues: list[dict[str, Any]] = []
    for index, finding in enumerate(findings, start=1):
        classified = classify_doctor_finding(finding.message)
        level = "fail" if finding.level == "FAIL" else str(classified.get("severity") or "warn")
        issues.append({
            "id": f"live-{index}",
            "level": level,
            "domain": classified.get("domain"),
            "title": classified.get("title"),
            "evidence": finding.message,
            "area": finding.area,
            "likely_cause": classified.get("likely_cause"),
            "first_actions": classified.get("first_actions") or [],
            "source_tools": classified.get("source_tools") or [],
            "related_runbook": classified.get("related_runbook") or "",
            "related_topology_path": classified.get("related_topology_path") or "",
        })

    if not live:
        issues.append({
            "id": "live-evidence-not-read",
            "level": "info",
            "domain": "evidence",
            "title": "Live evidence not read",
            "evidence": "Doctor was run offline.",
            "area": "doctor",
            "likely_cause": "Offline mode is useful for review, but it cannot prove current network health.",
            "first_actions": [
                "Run ./homenet doctor --instance <instance> --live from a trusted maintenance host.",
                "Use ./homenet status --instance <instance> --live for raw live finding counts.",
            ],
            "source_tools": ["HomeNet doctor", "HomeNet status"],
            "related_runbook": "codex-maintenance-path-needed",
            "related_topology_path": "ops-maintenance",
        })

    triage_domains = build_doctor_triage_domains(metadata, status, runbook, issues, live=live)

    by_domain: dict[str, int] = {}
    by_level: dict[str, int] = {}
    for issue in issues:
        domain = str(issue.get("domain") or "unknown")
        level = str(issue.get("level") or "unknown")
        by_domain[domain] = by_domain.get(domain, 0) + 1
        by_level[level] = by_level.get(level, 0) + 1

    failures = int(status.get("live_status", {}).get("failures") or 0) if isinstance(status.get("live_status"), dict) else 0
    warnings = int(status.get("live_status", {}).get("warnings") or 0) if isinstance(status.get("live_status"), dict) else 0
    if failures:
        health = "action-required"
    elif warnings:
        health = "degraded"
    elif live:
        health = "healthy"
    else:
        health = "unknown-offline"

    source_boundaries = [
        {
            "owner": item.get("name") or item.get("id") or "",
            "source_tool": item.get("source_tool") or "",
            "write_rule": item.get("write_rule") or "",
        }
        for item in ownership.get("control_planes", [])
        if isinstance(item, dict)
    ]

    return {
        "schema": "homenet.doctor.v1",
        "instance": metadata.get("instance") or {},
        "instance_path": str(instance),
        "profile": metadata.get("profile"),
        "live": live,
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "health": health,
        "summary": {
            "issues": len(issues),
            "failures": failures,
            "warnings": warnings,
            "domains": len(by_domain),
            "topology_paths": topology.get("summary", {}).get("traffic_paths", 0),
            "runbook_scenarios": runbook.get("summary", {}).get("scenarios", 0),
            "source_boundaries": len(source_boundaries),
            "triage_domains": len(triage_domains),
        },
        "by_domain": dict(sorted(by_domain.items())),
        "by_level": dict(sorted(by_level.items())),
        "triage_domains": triage_domains,
        "issues": issues,
        "next_actions": [
            "Handle fail-level issues before warn-level issues.",
            "Check the local/LAN target before remote ingress or public-domain symptoms.",
            "Use topology to understand the path, runbook to follow the scenario, and ownership to pick the source tool.",
            "Make at most one small source-tool change at a time, then re-run doctor --live.",
        ],
        "status_summary": status.get("summary", {}),
        "source_boundaries": source_boundaries,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "live_state_read": live,
            "note": "Doctor summarizes findings, paths, and source-tool guidance only. It does not include passwords, tokens, keys, cookies, sessions, or proxy subscription URLs.",
        },
    }


def print_doctor_markdown(doctor: dict[str, Any]) -> None:
    instance = doctor.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or Path(str(doctor.get("instance_path", "instance"))).name
    print(f"# HomeNet Doctor - {name}")
    print()
    print(f"- schema: `{doctor.get('schema')}`")
    print(f"- profile: `{doctor.get('profile')}`")
    print(f"- live: {doctor.get('live')}")
    print(f"- health: `{doctor.get('health')}`")
    print(f"- read only: {doctor.get('read_only')}")
    print(f"- writes files: {doctor.get('writes_files')}")
    print(f"- writes live config: {doctor.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in doctor.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Issue Groups")
    print()
    print("### By Domain")
    print()
    for domain, count in doctor.get("by_domain", {}).items():
        print(f"- `{domain}`: {count}")
    print()
    print("### By Level")
    print()
    for level, count in doctor.get("by_level", {}).items():
        print(f"- `{level}`: {count}")
    print()
    print("## Triage Domains")
    print()
    for domain in doctor.get("triage_domains", []):
        if not isinstance(domain, dict):
            continue
        print(f"### {domain.get('title')} (`{domain.get('id')}`)")
        print()
        print(f"- status: `{domain.get('status')}`")
        print(f"- scope: {domain.get('scope')}")
        print(f"- symptom: {domain.get('symptom')}")
        print(f"- next action: {domain.get('next_action')}")
        if domain.get("related_runbook"):
            print(f"- runbook: `{domain.get('related_runbook')}`")
        if domain.get("related_topology_path"):
            print(f"- topology path: `{domain.get('related_topology_path')}`")
        if domain.get("source_tools"):
            print(f"- source tools: {', '.join(as_list(domain.get('source_tools')))}")
        entries = [
            f"{entry.get('name')} (`{entry.get('target')}`)"
            for entry in as_list(domain.get("first_entries"))
            if isinstance(entry, dict)
        ]
        if entries:
            print(f"- first entries: {'; '.join(entries)}")
        if domain.get("prove_ok"):
            print("- proves healthy:")
            for item in as_list(domain.get("prove_ok")):
                print(f"  - {item}")
        if domain.get("related_issues"):
            print(f"- related issues: {', '.join(as_list(domain.get('related_issues')))}")
        print()
    print("## Issues")
    print()
    for issue in doctor.get("issues", []):
        if not isinstance(issue, dict):
            continue
        print(f"### {issue.get('title')} (`{issue.get('id')}`)")
        print()
        print(f"- level: `{issue.get('level')}`")
        print(f"- domain: `{issue.get('domain')}`")
        print(f"- evidence: {issue.get('evidence')}")
        print(f"- likely cause: {issue.get('likely_cause')}")
        if issue.get("related_runbook"):
            print(f"- runbook: `{issue.get('related_runbook')}`")
        if issue.get("related_topology_path"):
            print(f"- topology path: `{issue.get('related_topology_path')}`")
        if issue.get("source_tools"):
            print(f"- source tools: {', '.join(as_list(issue.get('source_tools')))}")
        print("- first actions:")
        for action in as_list(issue.get("first_actions")):
            print(f"  - {action}")
        print()
    print("## Next Actions")
    print()
    for action in doctor.get("next_actions", []):
        print(f"- {action}")
    print()
    print("## Source Boundaries")
    print()
    print("| Owner | Source Tool | Write Rule |")
    print("| --- | --- | --- |")
    for item in doctor.get("source_boundaries", []):
        if isinstance(item, dict):
            print(f"| {item.get('owner', '')} | {item.get('source_tool', '')} | {item.get('write_rule', '')} |")
    print()


def build_incident_decision_flow(
    triage: list[dict[str, Any]],
    maintenance: dict[str, Any],
    *,
    live: bool,
) -> list[dict[str, Any]]:
    by_id = {str(domain.get("id") or ""): domain for domain in triage if isinstance(domain, dict)}

    def domain_status(domain_id: str) -> str:
        return str((by_id.get(domain_id) or {}).get("status") or ("unknown" if not live else "ok"))

    def first_entry_targets(domain_id: str) -> list[str]:
        domain = by_id.get(domain_id) or {}
        targets: list[str] = []
        for entry in as_list(domain.get("first_entries"))[:3]:
            if isinstance(entry, dict):
                target = str(entry.get("target") or "")
                name = str(entry.get("name") or "")
                if target:
                    targets.append(f"{name} {target}".strip())
        return targets

    ops_network = str(maintenance.get("id") or maintenance.get("network") or "ops")
    ops_gateway = str(maintenance.get("gateway") or "")
    ops_cidr = str(maintenance.get("cidr") or "")
    ops_mode = " / ".join(
        value
        for value in [
            str(maintenance.get("dns_mode") or ""),
            str(maintenance.get("proxy_mode") or ""),
        ]
        if value
    )

    return [
        {
            "id": "keep-maintenance",
            "order": 1,
            "question": "还能不能通过低依赖通道进 Pi/OpenWrt？",
            "domain": "rescue-path",
            "status": domain_status("rescue-path"),
            "why_first": "没有维护通道就不要扩大改动；先保证还能观察和回滚。",
            "good_signal": [
                f"{ops_network} reachable" + (f" at {ops_gateway}" if ops_gateway else ""),
                f"maintenance network {ops_cidr}" if ops_cidr else "maintenance network declared",
                f"mode {ops_mode}" if ops_mode else "direct-IP maintenance path declared",
            ],
            "if_bad": [
                "用直连 IP 访问 OpenWrt/Pi，避免依赖 DNS、代理和外部域名。",
                "只检查 DHCP/firewall/SSID 是否让维护设备到达 Pi 和 OpenWrt。",
            ],
            "entries": first_entry_targets("rescue-path"),
        },
        {
            "id": "prove-gateway",
            "order": 2,
            "question": "主路由、LAN、WAN 是不是基础正常？",
            "domain": "gateway-wan",
            "status": domain_status("gateway-wan"),
            "why_first": "Gateway/WAN 不正常时，DNS、Proxy、Cloudflare、Kuma 的异常都可能是下游假象。",
            "good_signal": [
                "OpenWrt direct IP reachable",
                "WAN session/carrier present and counters move",
                "client DHCP gets expected gateway/DNS",
            ],
            "if_bad": [
                "先看 OpenWrt WAN、PPPoE/DHCP、接口状态和系统日志。",
                "不要先重启 Pi 服务或改 Mihomo/AdGuard。",
            ],
            "entries": first_entry_targets("gateway-wan"),
        },
        {
            "id": "prove-wifi",
            "order": 3,
            "question": "问题是不是 Wi-Fi radio/SSID/卧室回程？",
            "domain": "wifi-radio",
            "status": worst_status([domain_status("wifi-radio"), domain_status("room-ap")]),
            "why_first": "断电后来电 5G 不起、卧室覆盖不稳，通常要先证明 radio 和 client association。",
            "good_signal": [
                "main/maintenance/iot/guest/backhaul SSID matches declared radios",
                "Room AP reachable and upstream associated",
                "client RSSI and lease match expected AP/network",
            ],
            "if_bad": [
                "只检查 OpenWrt wireless status 和 Room AP upstream，不改全局 DNS/Proxy。",
                "客户端单点异常时先看该设备当前 SSID-specific MAC 和 DHCP lease。",
            ],
            "entries": list(dict.fromkeys(first_entry_targets("wifi-radio") + first_entry_targets("room-ap"))),
        },
        {
            "id": "prove-dns-proxy",
            "order": 4,
            "question": "是 DNS 解析错，还是 Proxy 路由/节点慢？",
            "domain": "dns-proxy",
            "status": domain_status("dns-proxy"),
            "why_first": "国内慢、国外慢、AI 节点走错组，需要先拆开 DNS answer、rule match、proxy group health。",
            "good_signal": [
                "domestic domain uses domestic/direct DNS path",
                "foreign/proxy domain follows intended fake-ip/rule path",
                "Mihomo selected chain matches rule expectation",
            ],
            "if_bad": [
                "先看 AdGuard/router DNS，再看 Mihomo rule/provider/group，不同时改两边。",
                "如果只有某个客户端异常，先排客户端代理模式和系统 DNS。",
            ],
            "entries": first_entry_targets("dns-proxy"),
        },
        {
            "id": "prove-server",
            "order": 5,
            "question": "是不是 Pi 上一组服务一起异常？",
            "domain": "server-runtime",
            "status": domain_status("server-runtime"),
            "why_first": "HomeNet/Kuma/Mihomo/AdGuard/HA 一起异常时，先当作 server runtime 事件处理。",
            "good_signal": [
                "Pi SSH reachable",
                "core containers/systemd units running",
                "service ports listen locally before remote checks",
            ],
            "if_bad": [
                "先查 Docker/systemd/磁盘/内存/端口监听。",
                "LAN 本地服务没好之前，不诊断 Cloudflare 外部入口。",
            ],
            "entries": first_entry_targets("server-runtime"),
        },
        {
            "id": "prove-remote",
            "order": 6,
            "question": "外部入口坏，还是它背后的 LAN 服务坏？",
            "domain": "remote-access",
            "status": domain_status("remote-access"),
            "why_first": "外部域名失败必须和对应 LAN target 配对看，否则容易误改 Cloudflare。",
            "good_signal": [
                "paired LAN target works first",
                "tunnel/access/caddy/wireguard state matches entry type",
                "Kuma/external monitor agrees with public entry",
            ],
            "if_bad": [
                "LAN target 正常才看 Cloudflare Tunnel/Access/Caddy/DDNS/WireGuard。",
                "LAN target 也坏就回到 server-runtime 或 gateway-wan。",
            ],
            "entries": first_entry_targets("remote-access"),
        },
    ]


def worst_status(statuses: list[str]) -> str:
    rank = {"bad": 0, "warn": 1, "info": 2, "unknown": 3, "ok": 4}
    chosen = "ok"
    chosen_rank = rank[chosen]
    for status in statuses:
        value = str(status or "unknown")
        value_rank = rank.get(value, rank["unknown"])
        if value_rank < chosen_rank:
            chosen = value
            chosen_rank = value_rank
    return chosen


def build_incident_recovery_matrix(
    triage: list[dict[str, Any]],
    local_entries: list[dict[str, Any]],
    remote_entries: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    entry_by_id = {str(entry.get("id") or ""): entry for entry in local_entries if isinstance(entry, dict)}
    remote_by_service = {
        str(entry.get("service_id") or ""): entry
        for entry in remote_entries
        if isinstance(entry, dict) and entry.get("service_id")
    }
    domain_by_id = {str(domain.get("id") or ""): domain for domain in triage if isinstance(domain, dict)}

    def entry_target(entry_id: str) -> str:
        entry = entry_by_id.get(entry_id) or {}
        return str(entry.get("target") or entry.get("local_url") or entry.get("host") or "")

    def remote_target(service_id: str) -> str:
        entry = remote_by_service.get(service_id) or {}
        return str(entry.get("href") or entry.get("target") or "")

    rows = [
        {
            "symptom": "所有 Wi-Fi/有线都慢或无网",
            "start_domain": "gateway-wan",
            "first_probe": entry_target("openwrt-luci") or "http://<gateway>/",
            "then_probe": "WAN interface, DHCP lease, DNS handed to client",
            "likely_owner": "OpenWrt Gateway / ISP modem",
            "do_not_start_with": "Mihomo provider, Cloudflare, HA, or Kuma",
        },
        {
            "symptom": "断电后来电 5G/SSID 不出现",
            "start_domain": "wifi-radio",
            "first_probe": entry_target("openwrt-luci") or "OpenWrt wireless status",
            "then_probe": "radio enabled, SSID broadcast, client association, system log",
            "likely_owner": "OpenWrt wireless config",
            "do_not_start_with": "DNS/proxy rules",
        },
        {
            "symptom": "卧室慢、切 AP 不顺、Room AP 客户端异常",
            "start_domain": "room-ap",
            "first_probe": entry_target("wrt-room-luci") or "Room AP management IP",
            "then_probe": "Room AP upstream/backhaul, DHCP server disabled, client lease source",
            "likely_owner": "Room AP LuCI/SSH + Gateway wireless",
            "do_not_start_with": "global Wi-Fi redesign",
        },
        {
            "symptom": "国内 App 开代理很慢，关代理正常",
            "start_domain": "dns-proxy",
            "first_probe": entry_target("mihomo") or "Mihomo Dashboard/API",
            "then_probe": "rule match, DIRECT path, selected proxy group, DNS result type",
            "likely_owner": "Mihomo rules + AdGuard/router DNS",
            "do_not_start_with": "WAN reboot unless direct path also fails",
        },
        {
            "symptom": "HomeNet/Kuma/HA/Mihomo/AdGuard 一起掉",
            "start_domain": "server-runtime",
            "first_probe": entry_target("pi-ssh") or "ssh <server>",
            "then_probe": "Docker ps, systemd units, listening ports, disk/memory",
            "likely_owner": "Pi Docker/systemd",
            "do_not_start_with": "Cloudflare Access settings",
        },
        {
            "symptom": "外部域名打不开，但 LAN 可能正常",
            "start_domain": "remote-access",
            "first_probe": entry_target("homenet-ops") or "paired LAN target",
            "then_probe": remote_target("homenet-ops") or "Cloudflare Tunnel/Access or Caddy/DDNS state",
            "likely_owner": "Cloudflare / cloudflared / Caddy / WireGuard",
            "do_not_start_with": "service restart before local target is checked",
        },
        {
            "symptom": "单个设备 IP/名字不对，尤其 Apple 或 IoT",
            "start_domain": "client-device",
            "first_probe": entry_target("openwrt-luci") or "OpenWrt DHCP leases",
            "then_probe": "SSID-specific MAC, static lease, hostname source, device power state",
            "likely_owner": "OpenWrt DHCP/static lease + device native settings",
            "do_not_start_with": "whole-network changes",
        },
    ]
    for row in rows:
        domain = domain_by_id.get(str(row.get("start_domain") or "")) or {}
        row["status"] = domain.get("status") or "unknown"
        row["related_runbook"] = domain.get("related_runbook") or ""
    return rows


def build_incident_report(
    state: dict[str, Any],
    instance: Path,
    *,
    live: bool = False,
    live_reporter: Reporter | None = None,
) -> dict[str, Any]:
    metadata = build_metadata(state, instance)
    rescue = build_rescue_guide(metadata, instance)
    runbook = build_runbook(state, instance)
    topology = build_topology(state, instance)
    doctor = build_doctor(state, instance, live=live, live_reporter=live_reporter)
    status = build_status_dashboard(state, instance, live=live, live_reporter=live_reporter)

    health = str(doctor.get("health") or "unknown")
    if health == "action-required":
        mode = "incident"
        headline = "Live evidence has failures. Fix the failing domain before broad changes."
    elif health == "degraded":
        mode = "degraded"
        headline = "Live evidence has warnings. Isolate the domain before changing config."
    elif health == "healthy":
        mode = "normal"
        headline = "Live evidence is healthy. Use this page as the daily maintenance map."
    else:
        mode = "offline"
        headline = "Offline report. It explains where to look, but does not prove current health."

    domain_order = [
        "gateway-wan",
        "wifi-radio",
        "room-ap",
        "dns-proxy",
        "server-runtime",
        "remote-access",
        "rescue-path",
        "client-device",
    ]
    status_rank = {"bad": 0, "warn": 1, "unknown": 2, "ok": 3}
    triage_domains = [
        domain
        for domain in as_list(doctor.get("triage_domains"))
        if isinstance(domain, dict)
    ]
    ordered_domains = sorted(
        triage_domains,
        key=lambda item: (
            status_rank.get(str(item.get("status") or "unknown"), 2),
            domain_order.index(str(item.get("id"))) if str(item.get("id")) in domain_order else 99,
        ),
    )

    triage = []
    for domain in ordered_domains[:8]:
        entries = [
            {
                "name": entry.get("name") or entry.get("id") or "",
                "target": entry.get("target") or "",
            }
            for entry in as_list(domain.get("first_entries"))[:3]
            if isinstance(entry, dict)
        ]
        triage.append({
            "id": domain.get("id") or "",
            "title": domain.get("title") or domain.get("id") or "",
            "status": domain.get("status") or "unknown",
            "symptom": domain.get("symptom") or "",
            "prove_ok": as_list(domain.get("prove_ok"))[:3],
            "first_entries": entries,
            "source_tools": as_list(domain.get("source_tools"))[:5],
            "next_action": domain.get("next_action") or "",
            "related_runbook": domain.get("related_runbook") or "",
        })

    maintenance = rescue.get("maintenance_network", {}) if isinstance(rescue.get("maintenance_network"), dict) else {}
    all_local_entries = [
        entry
        for entry in as_list(rescue.get("local_entries"))
        if isinstance(entry, dict)
    ]
    local_entries = [
        entry
        for entry in all_local_entries
        if entry.get("priority") == "first"
    ]
    ssh_targets = [
        item
        for item in as_list(rescue.get("ssh_targets"))
        if isinstance(item, dict)
    ]
    remote_entries = [
        item
        for item in as_list(rescue.get("remote_entries"))
        if isinstance(item, dict)
    ]
    issues = [
        issue
        for issue in as_list(doctor.get("issues"))
        if isinstance(issue, dict)
    ]
    active_issues = [
        issue
        for issue in issues
        if str(issue.get("level") or "") in {"fail", "warn"}
    ]
    safe_commands = [
        command
        for command in as_list(runbook.get("safe_commands"))
        if isinstance(command, dict) and command.get("id") in {"daily-status", "live-status", "live-check", "ownership", "rescue"}
    ]

    first_five_minutes = [
        "Use direct IP or the Maintenance path if DNS, proxy, or remote ingress is suspect.",
        "Prove Gateway/WAN and Wi-Fi radio state before changing DNS, proxy rules, or server services.",
        "Check the LAN/local target before checking Cloudflare, public domains, or return-home tunnels.",
        "Confirm the source tool owner before changing anything; change one thing, then re-run incident --live.",
    ]
    if not live:
        first_five_minutes.insert(0, "Run this command with --live from a trusted maintenance host when current health must be proven.")
    decision_flow = build_incident_decision_flow(triage, maintenance, live=live)
    recovery_matrix = build_incident_recovery_matrix(triage, all_local_entries, remote_entries)

    return {
        "schema": "homenet.incident.v1",
        "instance": metadata.get("instance") or {},
        "instance_path": str(instance),
        "profile": metadata.get("profile"),
        "live": live,
        "mode": mode,
        "health": health,
        "headline": headline,
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "summary": {
            "active_issues": len(active_issues),
            "triage_domains": len(triage),
            "local_first_entries": len(local_entries),
            "ssh_targets": len(ssh_targets),
            "remote_entries": len(remote_entries),
            "topology_paths": topology.get("summary", {}).get("traffic_paths", 0),
            "runbook_scenarios": runbook.get("summary", {}).get("scenarios", 0),
            "status_daily_entries": status.get("summary", {}).get("daily_entries", 0),
            "decision_steps": len(decision_flow),
            "recovery_rows": len(recovery_matrix),
        },
        "first_five_minutes": first_five_minutes,
        "decision_flow": decision_flow,
        "recovery_matrix": recovery_matrix,
        "triage": triage,
        "maintenance_path": {
            "network": maintenance.get("id") or "",
            "cidr": maintenance.get("cidr") or "",
            "gateway": maintenance.get("gateway") or "",
            "dns_mode": maintenance.get("dns_mode") or "",
            "proxy_mode": maintenance.get("proxy_mode") or "",
            "purpose": maintenance.get("purpose") or "",
            "wifi": maintenance.get("wifi") or [],
        },
        "first_entries": local_entries,
        "ssh_targets": ssh_targets,
        "remote_entries": remote_entries,
        "active_issues": active_issues,
        "safe_commands": safe_commands,
        "next_commands": [
            f"./homenet incident --instance {instance} --live",
            f"./homenet doctor --instance {instance} --live",
            f"./homenet check --instance {instance} --live",
            f"./homenet ownership --instance {instance}",
        ],
        "source_role": {
            "homenet": "status, information, links, correlation, and troubleshooting direction",
            "kuma": "alerts and availability history",
            "source_tools": "authoritative configuration and deep runtime state",
        },
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "live_state_read": live,
            "note": "Incident report aggregates existing HomeNet status, doctor, rescue, runbook, and topology surfaces. It never prints Wi-Fi passwords, tokens, keys, cookies, sessions, or proxy subscriptions.",
        },
    }


def print_incident_markdown(report: dict[str, Any]) -> None:
    instance = report.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or Path(str(report.get("instance_path", "instance"))).name
    print(f"# HomeNet Incident - {name}")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- profile: `{report.get('profile')}`")
    print(f"- live: {report.get('live')}")
    print(f"- mode: `{report.get('mode')}`")
    print(f"- health: `{report.get('health')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print()
    print(report.get("headline") or "")
    print()
    print("## Summary")
    print()
    for key, value in report.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    print("## First Five Minutes")
    print()
    for item in as_list(report.get("first_five_minutes")):
        print(f"- {item}")
    print()
    print("## Decision Flow")
    print()
    print("| Step | Question | Status | Why First | If Bad | Entries |")
    print("| --- | --- | --- | --- | --- | --- |")
    for step in as_list(report.get("decision_flow")):
        if not isinstance(step, dict):
            continue
        bad_actions = "<br>".join(as_list(step.get("if_bad"))[:3])
        entries = "<br>".join(f"`{entry}`" for entry in as_list(step.get("entries"))[:3])
        print(
            f"| {step.get('order', '')} | {step.get('question', '')} | `{step.get('status', '')}` | "
            f"{step.get('why_first', '')} | {bad_actions} | {entries} |"
        )
    print()
    print("## Recovery Matrix")
    print()
    print("| Symptom | Start Domain | Status | First Probe | Then Probe | Owner | Do Not Start With |")
    print("| --- | --- | --- | --- | --- | --- | --- |")
    for row in as_list(report.get("recovery_matrix")):
        if not isinstance(row, dict):
            continue
        print(
            f"| {row.get('symptom', '')} | `{row.get('start_domain', '')}` | `{row.get('status', '')}` | "
            f"`{row.get('first_probe', '')}` | {row.get('then_probe', '')} | "
            f"{row.get('likely_owner', '')} | {row.get('do_not_start_with', '')} |"
        )
    print()
    print("## Triage")
    print()
    print("| Status | Domain | Prove OK | First Entries | Source Tools | Next Action |")
    print("| --- | --- | --- | --- | --- | --- |")
    for domain in as_list(report.get("triage")):
        if not isinstance(domain, dict):
            continue
        prove = "<br>".join(as_list(domain.get("prove_ok"))[:3])
        entries = "<br>".join(
            f"{entry.get('name')} `{entry.get('target')}`"
            for entry in as_list(domain.get("first_entries"))
            if isinstance(entry, dict)
        )
        tools = ", ".join(as_list(domain.get("source_tools"))[:5])
        print(
            f"| `{domain.get('status', '')}` | {domain.get('title', '')} | {prove} | "
            f"{entries} | {tools} | {domain.get('next_action', '')} |"
        )
    print()
    maintenance = report.get("maintenance_path", {}) if isinstance(report.get("maintenance_path"), dict) else {}
    print("## Maintenance Path")
    print()
    print(markdown_table(
        ["Field", "Value"],
        [
            ["network", maintenance.get("network")],
            ["cidr", maintenance.get("cidr")],
            ["gateway", maintenance.get("gateway")],
            ["dns_mode", maintenance.get("dns_mode")],
            ["proxy_mode", maintenance.get("proxy_mode")],
            ["purpose", maintenance.get("purpose")],
        ],
    ))
    print()
    print("## First Entries")
    print()
    print("| Name | Target | Dependency | Note |")
    print("| --- | --- | --- | --- |")
    for entry in as_list(report.get("first_entries")):
        if isinstance(entry, dict):
            print(f"| {entry.get('name', '')} | `{entry.get('target', '')}` | {entry.get('dependency', '')} | {entry.get('note', '')} |")
    print()
    print("## Active Issues")
    print()
    if report.get("active_issues"):
        print("| Level | Domain | Title | Evidence | First Actions |")
        print("| --- | --- | --- | --- | --- |")
        for issue in as_list(report.get("active_issues")):
            if isinstance(issue, dict):
                actions = "<br>".join(as_list(issue.get("first_actions"))[:3])
                print(f"| `{issue.get('level', '')}` | {issue.get('domain', '')} | {issue.get('title', '')} | {issue.get('evidence', '')} | {actions} |")
    else:
        print("- No fail/warn issue is present in this report.")
    print()
    print("## Safe Commands")
    print()
    for command in as_list(report.get("safe_commands")):
        if isinstance(command, dict):
            print(f"- `{command.get('command')}` - {command.get('purpose')}")
    print()
    print("## Next Commands")
    print()
    for command in as_list(report.get("next_commands")):
        print(f"- `{command}`")
    print()


def build_ownership_map(metadata: dict[str, Any], artifacts: dict[str, Any], instance: Path) -> dict[str, Any]:
    instance_info = metadata.get("instance", {}) if isinstance(metadata.get("instance"), dict) else {}
    networks = metadata.get("networks", {}) if isinstance(metadata.get("networks"), dict) else {}
    wifi = metadata.get("wifi", {}) if isinstance(metadata.get("wifi"), dict) else {}
    services = [
        service
        for service in metadata.get("service_directory", [])
        if isinstance(service, dict)
    ]
    module_plan = [
        module
        for module in metadata.get("module_plan", [])
        if isinstance(module, dict)
    ]

    control_planes = [
        {
            "id": "instance-files",
            "name": "HomeNet instance files",
            "owns": "Declared intent: networks, Wi-Fi metadata, devices, services, ports, remote ingress, and module placement.",
            "source_tool": "site.yaml / devices.yaml / services.yaml",
            "homenet_role": "Source for generated metadata, docs, status, plans, and review contracts.",
            "write_rule": "Edit instance files for declared intent; never place secrets or runtime databases here.",
        },
        {
            "id": "openwrt",
            "name": "OpenWrt Gateway",
            "owns": "WAN/LAN, DHCP/static leases, VLANs, Wi-Fi interfaces, firewall, routing, TProxy handoff, and room AP relay config.",
            "source_tool": "LuCI / OpenWrt SSH / UCI",
            "homenet_role": "Reads and explains OpenWrt state; future apply must backup and require explicit confirmation.",
            "write_rule": "Use LuCI/SSH today; future HomeNet writes must be network-change gated.",
        },
        {
            "id": "adguard",
            "name": "AdGuard DNS",
            "owns": "Home DNS behavior, filtering, domestic upstream split, and DNS logs when server runtime is enabled.",
            "source_tool": "AdGuard Home UI/config",
            "homenet_role": "Generates review fragments and checks DNS behavior.",
            "write_rule": "AdGuard config remains service-owned until renderer/apply gates are implemented.",
        },
        {
            "id": "mihomo",
            "name": "Mihomo Proxy",
            "owns": "Proxy providers, rule groups, fake-ip behavior, and transparent proxy runtime decisions.",
            "source_tool": "Mihomo Dashboard/config",
            "homenet_role": "Summarizes routing intent and verifies direct/proxy paths.",
            "write_rule": "Mihomo config remains service-owned; generated fragments are review-only.",
        },
        {
            "id": "cloudflare",
            "name": "Cloudflare Tunnel / Access / DNS",
            "owns": "External protected hostnames, tunnel routing, Zero Trust app protection, and provider-side tunnel state.",
            "source_tool": "Cloudflare Dashboard/API",
            "homenet_role": "Reads provider state and documents ingress targets.",
            "write_rule": "Cloudflare writes require scoped tokens and explicit remote-entry review.",
        },
        {
            "id": "wireguard",
            "name": "WireGuard",
            "owns": "Return-home peers, keys, allowed IPs, and UDP reachability.",
            "source_tool": "wg-easy / wg",
            "homenet_role": "Lists entry points and checks handshake/state evidence.",
            "write_rule": "Keys and peer secrets stay in WireGuard tooling, not instance metadata.",
        },
        {
            "id": "kuma",
            "name": "Uptime Kuma",
            "owns": "Availability notifications, monitor history, and alert delivery.",
            "source_tool": "Uptime Kuma UI/DB",
            "homenet_role": "Exports monitor candidates and guarded import plans.",
            "write_rule": "Kuma writes require DB backup and explicit APPLY-KUMA confirmation; never delete operator-owned monitors automatically.",
        },
        {
            "id": "homenet-ops",
            "name": "HomeNet Ops",
            "owns": "Daily navigation, explanation, topology view, service directory, and status aggregation.",
            "source_tool": "HomeNet metadata/API",
            "homenet_role": "Primary human entry surface; not the authority for raw router/DNS/proxy state.",
            "write_rule": "Ops should link and explain before controlling; controls need module-owned apply/rollback contracts.",
        },
    ]

    network_rows = []
    for net_id, network in sorted(networks.items()):
        if not isinstance(network, dict) or network.get("enabled") is False:
            continue
        network_rows.append({
            "id": net_id,
            "cidr": network.get("cidr") or "",
            "owner": "OpenWrt Gateway",
            "source_tool": "LuCI / UCI network, dhcp, firewall",
            "homenet_role": "Declared network intent and read-only validation.",
            "notes": f"dns={network.get('dns_mode', '')} proxy={network.get('proxy_mode', '')}",
        })

    wifi_rows = []
    for wifi_id, item in sorted(wifi.items()):
        if not isinstance(item, dict):
            continue
        wifi_rows.append({
            "id": wifi_id,
            "ssid": item.get("ssid") or "",
            "network": item.get("network") or "",
            "owner": "OpenWrt Gateway / Room AP when broadcast there",
            "source_tool": "LuCI wireless / UCI wireless",
            "homenet_role": "Declares SSID purpose and expected network mapping, not the password.",
            "notes": f"band={item.get('band', '')} broadcast_by={', '.join(as_list(item.get('broadcast_by')))}",
        })

    service_rows = []
    for service in sorted(services, key=lambda row: (str(row.get("category", "")), str(row.get("name", "")))):
        owner = str(service.get("owner") or service.get("runtime") or "")
        runtime = str(service.get("runtime") or "")
        if runtime == "openwrt":
            source_tool = "OpenWrt LuCI/SSH"
        elif runtime == "server":
            source_tool = "Docker Compose / systemd / service UI"
        elif runtime == "external":
            source_tool = "External provider dashboard"
        else:
            source_tool = "Declared service owner"
        service_rows.append({
            "id": service.get("id") or "",
            "name": service.get("name") or service.get("id") or "",
            "category": service.get("category") or "",
            "owner": owner,
            "runtime": runtime,
            "source_tool": source_tool,
            "homenet_role": "Service directory, port inventory, status links, and monitor candidates.",
            "local_url": service.get("local_url") or "",
            "remote_url": service.get("remote_url") or "",
        })

    module_rows = []
    for module in module_plan:
        module_rows.append({
            "id": module.get("id") or "",
            "title": module.get("title") or module.get("id") or "",
            "placement": module.get("placement") or "",
            "owner": module.get("owner") or module.get("title") or module.get("id") or "",
            "source_tool": module.get("source_tool") or "Module-specific source tool",
            "checks": len(as_list(module.get("checks"))),
            "outputs": len(as_list(module.get("outputs"))),
            "rollback": len(as_list(module.get("rollback"))),
            "homenet_role": "Plan, explain, verify, and prepare apply/rollback contracts.",
        })

    artifact_rows = []
    for artifact in artifacts.get("artifacts", []):
        if not isinstance(artifact, dict):
            continue
        artifact_rows.append({
            "id": artifact.get("id") or "",
            "module_id": artifact.get("module_id") or "",
            "target": artifact.get("target") or "",
            "owner": artifact.get("owner") or "",
            "path": artifact.get("path") or "",
            "risk": artifact.get("risk") or "",
            "write_default": bool(artifact.get("write_default")),
            "requires_backup": bool(artifact.get("requires_backup")),
            "homenet_role": "Artifact contract for review, backup, render, and future guarded apply.",
        })

    writer_by_target = {
        "operator": {
            "id": "review-bundle",
            "owner": "operator",
            "source_tool": "HomeNet review bundle and git review",
            "write_surface": "review artifacts only",
        },
        "server-runtime": {
            "id": "server-runtime-writer",
            "owner": "server-runtime",
            "source_tool": "Docker Compose, systemd, and service-native configuration",
            "write_surface": "Pi/server runtime",
        },
        "room-ap": {
            "id": "room-ap-source-tool",
            "owner": "room-ap",
            "source_tool": "OpenWrt LuCI/uci on the room AP",
            "write_surface": "room AP wireless/network configuration",
        },
        "openwrt": {
            "id": "openwrt-source-tool",
            "owner": "openwrt",
            "source_tool": "OpenWrt LuCI/uci and router-side source tools on the gateway",
            "write_surface": "gateway network, DNS, proxy, firewall, and remote-access configuration",
        },
    }
    future_writer_counts: dict[str, dict[str, Any]] = {}
    for row in artifact_rows:
        target = str(row.get("target") or "")
        writer = writer_by_target.get(target, {
            "id": "source-tool",
            "owner": "unknown-target",
            "source_tool": "module-specific source tool",
            "write_surface": "module-owned live surface",
        })
        writer_id = str(writer.get("id") or "source-tool")
        entry = future_writer_counts.setdefault(writer_id, {
            **writer,
            "artifact_count": 0,
            "targets": set(),
            "risks": set(),
            "backup_required_artifacts": 0,
        })
        entry["artifact_count"] += 1
        if target:
            entry["targets"].add(target)
        if row.get("risk"):
            entry["risks"].add(str(row.get("risk")))
        if row.get("requires_backup"):
            entry["backup_required_artifacts"] += 1
    future_writers = []
    for writer_id, entry in sorted(future_writer_counts.items()):
        risks = sorted(entry.pop("risks"))
        targets = sorted(entry.pop("targets"))
        future_writers.append({
            **entry,
            "id": writer_id,
            "targets": targets,
            "risks": risks,
            "source_tool_gate": "source-tool-ownership",
            "evidence_key": "source_tools.reviewed",
            "review_status": "required" if writer_id != "review-bundle" else "review-only",
            "proof_required": [
                "source tool owner is explicit",
                "write surface is explicit",
                "backup and rollback path are explicit",
                "operator knows where manual source-tool change must be made today",
            ] if writer_id != "review-bundle" else [
                "review output remains privacy-safe",
                "review output does not mutate live state",
            ],
        })

    return {
        "schema": "homenet.ownership.v1",
        "instance": instance_info,
        "instance_path": str(instance),
        "profile": metadata.get("profile"),
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "summary": {
            "control_planes": len(control_planes),
            "networks": len(network_rows),
            "wifi": len(wifi_rows),
            "services": len(service_rows),
            "modules": len(module_rows),
            "artifacts": len(artifact_rows),
            "future_writers": len(future_writers),
            "write_default_artifacts": sum(1 for row in artifact_rows if row.get("write_default")),
            "backup_required_artifacts": sum(1 for row in artifact_rows if row.get("requires_backup")),
        },
        "control_planes": control_planes,
        "networks": network_rows,
        "wifi": wifi_rows,
        "services": service_rows,
        "modules": module_rows,
        "artifacts": artifact_rows,
        "future_writers": future_writers,
        "rules": [
            "HomeNet instance files declare intent; source tools remain authoritative for live router, DNS, proxy, tunnel, monitor, and service state.",
            "HomeNet Ops summarizes and navigates; it should not duplicate full source-tool configuration UIs.",
            "Uptime Kuma owns notifications and history; HomeNet owns monitor candidates, diffs, and guarded import plans.",
            "Write-side automation must be module-owned, backed up, explicitly confirmed, and verified after apply.",
            "Secrets stay in service-native stores or scoped secret files; ownership reports show names and boundaries only.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Ownership shows responsibilities, paths, and tools only. It does not include passwords, tokens, keys, cookies, sessions, or subscription URLs.",
        },
    }


