def print_blueprint_markdown(blueprint: dict[str, Any]) -> None:
    instance = blueprint.get("instance", {})
    print(f"# Blueprint - {instance.get('display_name') or instance.get('name') or 'instance'}")
    print()
    print(f"- schema: `{blueprint.get('schema')}`")
    print(f"- profile: `{blueprint.get('profile')}`")
    print(f"- position: {blueprint.get('position')}")
    print()

    def bullet_section(title: str, rows: list[Any]) -> None:
        print(f"## {title}")
        print()
        for row in rows:
            print(f"- {row}")
        print()

    bullet_section("Problem", blueprint.get("problem", []))
    bullet_section("Provides", blueprint.get("provides", []))
    bullet_section("Non-goals", blueprint.get("non_goals", []))

    print("## Operational Questions")
    print()
    print("| Question | Surface |")
    print("| --- | --- |")
    for row in blueprint.get("operational_questions", []):
        if isinstance(row, dict):
            print(f"| {row.get('question', '')} | {row.get('surface', '')} |")
    print()

    print("## Active / Fallback Capabilities")
    print()
    print("| Capability | Status | Required | Placement | Fallback |")
    print("| --- | --- | --- | --- | --- |")
    for item in blueprint.get("active_capabilities", []):
        if isinstance(item, dict):
            required = "yes" if item.get("required") else "no"
            print(f"| {item.get('title', '')} | {item.get('status', '')} | {required} | {item.get('placement', '')} | {item.get('fallback', '')} |")
    print()

    service_summary = blueprint.get("service_summary", {})
    artifact_summary = blueprint.get("artifact_summary", {})
    print("## Instance Summary")
    print()
    print(f"- services: {service_summary.get('total', 0)}")
    for category, count in service_summary.get("by_category", {}).items():
        print(f"  - `{category}`: {count}")
    print(f"- artifacts: {artifact_summary.get('total', 0)}")
    for target, count in artifact_summary.get("by_target", {}).items():
        print(f"  - `{target}`: {count}")
    print()

    print("## Source Of Truth")
    print()
    print("| Area | Owner |")
    print("| --- | --- |")
    for row in blueprint.get("source_of_truth", []):
        if isinstance(row, dict):
            print(f"| {row.get('area', '')} | {row.get('owner', '')} |")
    print()

    bullet_section("Operator Commands", [f"`{command}`" for command in blueprint.get("operator_commands", [])])


