def build_profiles_export() -> dict[str, Any]:
    profiles: list[dict[str, Any]] = []
    for profile in PROFILE_CATALOG:
        profile_id = str(profile.get("id") or "")
        mode_key = "openwrt_only" if profile_id == "openwrt-only" else "with_server"
        capabilities = [
            {
                "id": capability.get("id") or "",
                "title": capability.get("title") or capability.get("id") or "",
                "required": bool(capability.get("required")),
                "mode": capability.get(mode_key) or "",
                "fallback": capability.get("fallback") or "",
                "runtime_options": capability.get("runtime_options") or [],
                "notes": capability.get("notes") or "",
            }
            for capability in module_capabilities()
        ]
        profiles.append({
            **profile,
            "capabilities": capabilities,
            "capability_count": len(capabilities),
            "required_capabilities": sum(1 for item in capabilities if item.get("required")),
        })
    return {
        "schema": "homenet.profiles.v1",
        "profiles": profiles,
        "default_profile": "openwrt-pi",
        "selection_rule": "Choose openwrt-pi for a Raspberry Pi-style always-on server, openwrt-mini-pc for a higher-capacity Linux host, and openwrt-only when the router must carry the deployment alone.",
        "public_onboarding": {
            "primary_commands": [
                "homenet profiles",
                "homenet init --name my-home --profile openwrt-pi",
                "homenet inputs --instance instances/my-home",
                "homenet secrets --instance instances/my-home",
                "homenet preflight --instance instances/my-home",
                "homenet adopt --instance instances/my-home",
                "homenet deploy --instance instances/my-home --force --check-idempotent",
                "homenet check --instance instances/my-home",
            ],
            "principle": "Start with init, instance inputs, secrets/preflight, adopt, deploy, and check. Keep CI, proof, and apply internals out of the first deployment path unless the operator is preparing publication or automation.",
        },
        "advanced_surfaces": [
            "apply --dry-run",
            "gates",
            "evidence",
            "pre-change-proof",
            "write-enablement",
            "render --dry-run",
            "generate --dry-run",
        ],
        "privacy": {
            "secrets_included": False,
            "note": "Profiles describe deployment shapes only and never include passwords, tokens, subscriptions, or private keys.",
        },
    }


def print_profiles_markdown(export: dict[str, Any]) -> None:
    print("# HomeNet Profiles")
    print()
    print(f"- schema: `{export.get('schema')}`")
    print(f"- default: `{export.get('default_profile')}`")
    print(f"- selection: {export.get('selection_rule')}")
    print()
    onboarding = export.get("public_onboarding", {})
    if isinstance(onboarding, dict):
        print("## Public Onboarding")
        print()
        print(onboarding.get("principle") or "")
        print()
        for command in onboarding.get("primary_commands", []):
            print(f"- `{command}`")
        print()
    print("## Profile Decision")
    print()
    print("| Profile | Best for | Avoid when | Default server |")
    print("| --- | --- | --- | --- |")
    for profile in export.get("profiles", []):
        if isinstance(profile, dict):
            print(f"| `{profile.get('id')}` | {profile.get('best_for', '')} | {profile.get('not_for', '')} | {profile.get('default_server', '')} |")
    print()
    for profile in export.get("profiles", []):
        if not isinstance(profile, dict):
            continue
        print(f"## {profile.get('title')} (`{profile.get('id')}`)")
        print()
        print(f"- fit: {profile.get('fit')}")
        print(f"- best for: {profile.get('best_for')}")
        print(f"- avoid when: {profile.get('not_for')}")
        print(f"- default server: `{profile.get('default_server')}`")
        print(f"- example: `{profile.get('example_instance')}`")
        print(f"- scaffold: `{profile.get('scaffold')}`")
        print()
        print("### Deployment Path")
        for item in profile.get("deployment_path", []):
            print(f"- {item}")
        print()
        print("### Optional Add-ons")
        for item in profile.get("optional_addons", []):
            print(f"- {item}")
        print()
        print("### Hardware")
        for item in profile.get("hardware", []):
            print(f"- {item}")
        print()
        print("### Required Inputs")
        for item in profile.get("required_inputs", []):
            print(f"- {item}")
        print()
        print("### Tradeoffs")
        for item in profile.get("tradeoffs", []):
            print(f"- {item}")
        print()
        print("### Capability Matrix")
        print()
        print("| Capability | Required | Mode | Fallback |")
        print("| --- | --- | --- | --- |")
        for capability in profile.get("capabilities", []):
            if not isinstance(capability, dict):
                continue
            required = "yes" if capability.get("required") else "no"
            print(f"| {capability.get('title', '')} | {required} | {capability.get('mode', '')} | {capability.get('fallback', '')} |")
        print()


def profile_by_id(profile_id: str) -> dict[str, Any]:
    for profile in PROFILE_CATALOG:
        if profile.get("id") == profile_id:
            return profile
    raise ValueError(f"unsupported profile: {profile_id}")


def build_quickstart_guide(
    profile_id: str,
    *,
    instance: Path | None = None,
    instance_state: dict[str, Any] | None = None,
    name: str = "my-home",
) -> dict[str, Any]:
    profile = profile_by_id(profile_id)
    scaffold_name = name if validate_instance_name(name) else "my-home"
    scaffold_command = f"homenet init --name {scaffold_name} --profile {profile_id}"
    instance_path = str(instance) if instance else f"instances/{scaffold_name}"
    server_runtime_enabled = profile_id != "openwrt-only"
    if isinstance(instance_state, dict):
        runtime = instance_state.get("site", {}).get("runtime", {}) if isinstance(instance_state.get("site"), dict) else {}
        server = runtime.get("server", {}) if isinstance(runtime, dict) and isinstance(runtime.get("server"), dict) else {}
        server_runtime_enabled = bool(server.get("enabled", server_runtime_enabled))
    runtime_template = None
    if server_runtime_enabled:
        runtime_template = {
            "id": "compose-template",
            "template": "templates/compose/docker-compose.yml",
            "env_template": "templates/compose/env.example",
            "readme": "templates/compose/README.md",
            "private_output": "docker-compose.yml + .env in the operator's private deployment directory",
            "commands": [
                "cp templates/compose/docker-compose.yml ./docker-compose.yml",
                "cp templates/compose/env.example ./.env",
            ],
            "rules": [
                "Do not commit the filled .env.",
                "Do not commit service databases, certificates, WireGuard data, Cloudflare credentials, or proxy subscriptions.",
                "Review deploy output before source-tool setup.",
            ],
        }
    profile_commands = ["homenet profiles", f"homenet quickstart --profile {profile_id}"]
    live_commands = [
        f"homenet check --instance {instance_path} --live",
        f"homenet status --instance {instance_path} --live",
        f"homenet doctor --instance {instance_path} --live",
    ]
    stages = [
        {
            "id": "choose-profile",
            "title": "Choose profile",
            "purpose": "Pick whether this deployment is OpenWrt-only, OpenWrt + Pi/server runtime, or OpenWrt + mini PC/NAS.",
            "commands": profile_commands,
            "done_when": "The operator knows where Gateway, DNS, Proxy, Remote Access, Observability, and optional services will run.",
        },
        {
            "id": "scaffold-instance",
            "title": "Initialize instance",
            "purpose": "Create or update editable site/devices/services files through the idempotent interactive initializer.",
            "commands": [scaffold_command],
            "done_when": "The init instance directory exists and contains no secrets.",
        },
        {
            "id": "fill-inputs",
            "title": "Fill inputs",
            "purpose": "Edit declared networks, Wi-Fi metadata, runtime targets, devices, services, and remote entries.",
            "commands": [
                f"homenet inputs --instance {instance_path}",
                f"homenet worksheet --instance {instance_path}",
                f"homenet check --instance {instance_path}",
            ],
            "done_when": "Schema and semantic checks pass; required inputs are declared or intentionally disabled.",
        },
        {
            "id": "prepare-secrets",
            "title": "Prepare secrets",
            "purpose": "Put passwords, tokens, private keys, and provider URLs into local secret stores or source-tool stores.",
            "commands": [
                f"homenet secrets --instance {instance_path}",
                f"homenet preflight --instance {instance_path}",
            ],
            "done_when": "Required secret names are present where HomeNet expects them; values are never copied into instance files.",
        },
    ]
    if runtime_template:
        stages.append({
            "id": "prepare-server-runtime",
            "title": "Prepare server runtime template",
            "purpose": "Derive private Docker Compose and env files from the public template for the selected server runtime.",
            "commands": as_list(runtime_template.get("commands")),
            "done_when": "The operator has a private compose/env draft outside public source control and has not committed filled secrets or runtime data.",
        })
    stages.extend([
        {
            "id": "verify-package",
            "title": "Check and package",
            "purpose": "Run the deployment check and produce a repeatable deployment package for setup and maintenance.",
            "commands": [
                f"homenet deploy --instance {instance_path} --force --check-idempotent",
                f"homenet check --instance {instance_path}",
            ],
            "done_when": "check has no failures and deploy idempotency passes.",
        },
        {
            "id": "plan-source-tool-setup",
            "title": "Plan source-tool setup",
            "purpose": "Use deploy as the practical setup checklist before touching OpenWrt, Docker/systemd, Cloudflare, Kuma, or other source tools.",
            "commands": [
                f"homenet deploy --instance {instance_path} --force --check-idempotent",
                f"homenet bootstrap --instance {instance_path}",
            ],
            "done_when": "The operator knows the source-tool order, rollback reference, and verification command for each live change.",
        },
        {
            "id": "live-verify",
            "title": "Live verify",
            "purpose": "Compare the declaration with live evidence after manual/source-tool setup or future apply work.",
            "commands": live_commands,
            "done_when": "Live checks have no failures; warnings are understood as explicit follow-up work.",
        },
    ])
    advanced_review = [
        f"homenet deploy --instance {instance_path} --dry-run",
        f"homenet rollback --instance {instance_path}",
        f"homenet apply --instance {instance_path} --dry-run",
        f"homenet gates --instance {instance_path}",
        f"homenet evidence --instance {instance_path}",
        f"homenet render --instance {instance_path} --dry-run",
        f"homenet generate --instance {instance_path} --dry-run",
    ]
    instance_summary: dict[str, Any] | None = None
    if instance and instance_state:
        plan = build_plan(instance_state, instance)
        metadata = build_metadata(instance_state, instance)
        readiness = build_readiness(instance_state, instance)
        instance_summary = {
            "path": str(instance),
            "profile": plan.get("profile"),
            "services": len(metadata.get("service_directory", [])),
            "ports": len(metadata.get("port_inventory", [])),
            "modules": len(plan.get("modules", [])),
            "ready_for_review": readiness.get("ready_for_review"),
            "ready_for_apply": readiness.get("ready_for_apply"),
            "readiness_warnings": readiness.get("summary", {}).get("warnings", 0),
        }
    module_decisions = build_module_decisions(
        profile_id,
        instance_state.get("site") if isinstance(instance_state, dict) and isinstance(instance_state.get("site"), dict) else None,
    )
    first_deployment_commands = [
        scaffold_command,
        f"homenet inputs --instance {instance_path}",
        f"homenet secrets --instance {instance_path}",
        f"homenet preflight --instance {instance_path}",
        f"homenet deploy --instance {instance_path} --force --check-idempotent",
        f"homenet check --instance {instance_path}",
    ]
    if runtime_template:
        first_deployment_commands.insert(-1, "cp templates/compose/docker-compose.yml ./docker-compose.yml")
        first_deployment_commands.insert(-1, "cp templates/compose/env.example ./.env")
    operator_summary = {
        "purpose": "Start here when creating or taking over a HomeNet deployment. It keeps deployment and daily use first; status and Ops views are supporting observation surfaces.",
        "first_deployment": {
            "goal": "Create a private instance, fill non-secret inputs, prepare local secret stores, review the source-tool setup order, and prove the public safety gate.",
            "commands": first_deployment_commands,
        },
        "daily_use": {
            "goal": "Use HomeNet Ops and CLI as the status and troubleshooting entry; leave alert history to Kuma and live source settings to their owning tools.",
            "commands": [
                f"homenet status --instance {instance_path}",
                f"homenet incident --instance {instance_path}",
                f"homenet topology --instance {instance_path}",
            ],
        },
        "incident_response": {
            "goal": "When the network is slow, intermittent, or unreachable, classify the failing layer before changing anything.",
            "commands": [
                f"homenet incident --instance {instance_path} --live",
                f"homenet doctor --instance {instance_path} --live",
                f"homenet check --instance {instance_path} --live",
            ],
        },
        "boundaries": [
            "HomeNet quickstart is read-only and does not write live network config.",
            "Filled secrets, runtime data, databases, certificates, and subscriptions stay outside public source control.",
            "Live changes still go through OpenWrt, Docker/systemd, Cloudflare, Kuma, Home Assistant, or another source tool until a guarded executor is enabled.",
        ],
    }

    return {
        "schema": "homenet.quickstart.v1",
        "profile": profile_id,
        "profile_title": profile.get("title"),
        "fit": profile.get("fit"),
        "example_instance": profile.get("example_instance"),
        "scaffold": scaffold_command,
        "target_instance": instance_path,
        "instance": instance_summary,
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "hardware": profile.get("hardware", []),
        "required_inputs": profile.get("required_inputs", []),
        "deployment_path": profile.get("deployment_path", []),
        "optional_addons": profile.get("optional_addons", []),
        "runtime_template": runtime_template,
        "operator_summary": operator_summary,
        "module_decisions": module_decisions,
        "stages": stages,
        "primary_path": [command for stage in stages for command in stage.get("commands", [])],
        "advanced_review": {
            "purpose": "Use these surfaces when preparing automation, reviewing generated config artifacts, or proving a live change. They are not required for the first public deployment path.",
            "commands": advanced_review,
        },
        "operator_rules": [
            "Keep real passwords, tokens, private keys, subscriptions, cookies, and sessions outside instance files.",
            "Use source tools for live changes until a guarded write-side apply path exists.",
            "Run the aggregate CI gate before publishing, handing the instance to an AI maintainer, or making live changes.",
            "Use --live only when the operator is on a trusted maintenance machine with access to the target network.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Quickstart contains commands, profile assumptions, and input names only; it never includes secret values.",
        },
    }


