def capture_markdown(printer: Any, payload: dict[str, Any]) -> str:
    buffer = io.StringIO()
    with contextlib.redirect_stdout(buffer):
        printer(payload)
    return buffer.getvalue()


def build_schema_blocker_readiness(instance: Path, reporter: Reporter) -> dict[str, Any]:
    blockers = [
        {"area": finding.area, "message": finding.message}
        for finding in reporter.findings
        if finding.level == "FAIL"
    ]
    warnings = [
        {"area": finding.area, "message": finding.message}
        for finding in reporter.findings
        if finding.level == "WARN"
    ]
    return {
        "schema": "homenet.readiness.v1",
        "instance_path": str(instance),
        "read_only": True,
        "live": False,
        "ready_for_review": False,
        "ready_for_apply": False,
        "summary": {
            "checks": 1,
            "review_blockers": len(blockers),
            "apply_blockers": 1,
            "warnings": len(warnings),
            "actions": 1,
        },
        "checks": [
            {
                "id": "instance-schema",
                "status": "fail",
                "detail": "Instance validation failed before generated surfaces could be built.",
            }
        ],
        "review_blockers": blockers,
        "apply_blockers": [
            {
                "id": "instance-schema",
                "detail": "Fix instance validation failures before review or apply.",
            }
        ],
        "warnings": warnings,
        "actions": [
            "Run ./homenet check --instance <instance> and fix every FAIL finding.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
        },
    }


def build_readiness(state: dict[str, Any], instance: Path, reporter: Reporter | None = None) -> dict[str, Any]:
    if reporter is not None and reporter.failed:
        return build_schema_blocker_readiness(instance, reporter)

    plan = build_plan(state, instance)
    metadata = build_metadata(state, instance)
    artifacts = build_artifact_manifest(metadata)
    ownership = build_ownership_map(metadata, artifacts, instance)
    secrets = build_secrets_contract(state, instance)
    kuma = build_kuma_export(metadata)
    risk_summary = artifacts.get("risk_summary", {})
    required_secrets = int(secrets.get("required_count") or 0)
    secret_count = int(secrets.get("secret_count") or 0)
    network_disruptive = int(risk_summary.get("network-disruptive") or 0)
    database_writes = int(risk_summary.get("database-write-if-applied") or 0)
    service_restarts = int(risk_summary.get("service-restart") or 0)
    remote_changes = int(risk_summary.get("remote-entry-change") or 0)
    kuma_manual = max(
        0,
        int(kuma.get("monitor_count") or 0) - int(kuma.get("auto_importable_count") or 0),
    )

    checks = [
        {
            "id": "instance-schema",
            "status": "pass",
            "detail": "Instance files pass local schema and semantic checks.",
        },
        {
            "id": "generated-surfaces",
            "status": "pass",
            "detail": (
                f"Generated plan, metadata, blueprint, secrets, artifacts, Kuma inventory, "
                f"and maintenance docs for profile {plan.get('profile')}."
            ),
        },
        {
            "id": "secrets-contract",
            "status": "warn" if required_secrets else "pass",
            "detail": (
                f"{required_secrets}/{secret_count} secrets are required by the instance. "
                "Readiness lists names only and does not verify values."
            ),
        },
        {
            "id": "artifact-risk",
            "status": "warn" if network_disruptive or database_writes or service_restarts or remote_changes else "pass",
            "detail": (
                f"risk_summary={dict(sorted(risk_summary.items()))}; "
                "future apply must show these artifacts before writing."
            ),
        },
        {
            "id": "kuma-import",
            "status": "warn" if kuma_manual else "pass",
            "detail": (
                f"{kuma.get('auto_importable_count', 0)}/{kuma.get('monitor_count', 0)} monitors "
                f"are auto-importable; {kuma_manual} require manual handling."
            ),
        },
        {
            "id": "live-evidence",
            "status": "warn",
            "detail": "No live OpenWrt, Docker, Cloudflare, or Kuma state was read. Use --live checks separately before real changes.",
        },
        {
            "id": "apply-command",
            "status": "block",
            "detail": "homenet apply --dry-run is available; write-side apply is not implemented.",
        },
    ]

    review_blockers: list[dict[str, str]] = []
    apply_blockers = [
        {
            "id": "apply-command",
            "detail": "write-side homenet apply is not implemented.",
        },
        {
            "id": "secret-values-unverified",
            "detail": f"Confirm {required_secrets} required secret values in local secret storage before applying.",
        },
        {
            "id": "live-evidence-not-run",
            "detail": "Run live verification against the actual network before applying network changes.",
        },
    ]
    warnings: list[dict[str, Any]] = []
    if network_disruptive:
        warnings.append({
            "id": "network-disruptive-artifacts",
            "detail": f"{network_disruptive} planned artifacts can disrupt network connectivity if applied incorrectly.",
        })
    if service_restarts:
        warnings.append({
            "id": "service-restart-artifacts",
            "detail": f"{service_restarts} planned artifacts would restart services if applied.",
        })
    if remote_changes:
        warnings.append({
            "id": "remote-entry-artifacts",
            "detail": f"{remote_changes} planned artifacts affect remote ingress or access surfaces.",
        })
    if database_writes:
        warnings.append({
            "id": "database-write-artifacts",
            "detail": f"{database_writes} planned artifacts would write a database if applied.",
        })
    if kuma_manual:
        warnings.append({
            "id": "manual-kuma-monitors",
            "detail": f"{kuma_manual} Kuma candidates need manual review or a custom monitor strategy.",
        })
    warnings.append({
        "id": "secret-values-not-read",
        "detail": "Secret values are intentionally not read by readiness.",
    })
    warnings.append({
        "id": "live-state-not-read",
        "detail": "This readiness report is offline; it does not prove the current network matches the instance.",
    })

    actions = [
        "Review readiness.md and artifacts.md before any network change.",
        f"Confirm all {required_secrets} required secret values exist in local secret storage.",
        "Run ./homenet verify --live before touching live OpenWrt, Docker, Kuma, or Cloudflare state.",
        "Use ./homenet bundle --instance <instance> --output <dir> to hand the full review package to a human or AI.",
    ]
    if network_disruptive:
        actions.append("Schedule network-disruptive artifacts for a maintenance window and keep the Maintenance Wi-Fi/rescue path available.")
    if kuma_manual:
        actions.append("Handle manual Kuma candidates separately after reviewing kuma.md.")

    return {
        "schema": "homenet.readiness.v1",
        "instance": metadata.get("instance") or {},
        "instance_path": str(instance),
        "profile": plan.get("profile"),
        "read_only": True,
        "live": False,
        "ready_for_review": len(review_blockers) == 0,
        "ready_for_apply": False,
        "summary": {
            "checks": len(checks),
            "review_blockers": len(review_blockers),
            "apply_blockers": len(apply_blockers),
            "warnings": len(warnings),
            "actions": len(actions),
            "services": len(metadata.get("service_directory", [])),
            "artifacts": artifacts.get("artifact_count", 0),
            "required_secrets": required_secrets,
            "kuma_monitors": kuma.get("monitor_count", 0),
            "kuma_auto_importable": kuma.get("auto_importable_count", 0),
        },
        "checks": checks,
        "review_blockers": review_blockers,
        "apply_blockers": apply_blockers,
        "warnings": warnings,
        "actions": actions,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "live_state_read": False,
            "note": "Readiness uses generated contracts and intentionally avoids printing secret values or reading live infrastructure.",
        },
    }


def print_readiness_markdown(readiness: dict[str, Any]) -> None:
    instance = readiness.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or Path(str(readiness.get("instance_path", "instance"))).name
    print(f"# Readiness - {name}")
    print()
    print(f"- schema: `{readiness.get('schema')}`")
    print(f"- profile: `{readiness.get('profile', '')}`")
    print(f"- read only: {readiness.get('read_only')}")
    print(f"- live: {readiness.get('live')}")
    print(f"- ready for review: {readiness.get('ready_for_review')}")
    print(f"- ready for apply: {readiness.get('ready_for_apply')}")
    print()
    summary = readiness.get("summary", {})
    print("## Summary")
    print()
    for key in ["checks", "review_blockers", "apply_blockers", "warnings", "services", "artifacts", "required_secrets", "kuma_monitors"]:
        if key in summary:
            print(f"- {key}: {summary.get(key)}")
    print()
    print("## Checks")
