    print("| Check | Status | Detail |")
    print("| --- | --- | --- |")
    for check in preflight.get("checks", []):
        if isinstance(check, dict):
            print(f"| {check.get('id', '')} | {check.get('status', '')} | {check.get('detail', '')} |")
    print()
    print("## Commands")
