def attach_gate_evidence_to_apply_plan(
    apply_plan: dict[str, Any],
    evidence_path: Path | None,
    evidence_warnings: list[dict[str, str]],
) -> None:
    if evidence_path is None and not evidence_warnings:
        return
    apply_plan.setdefault("gate_evidence", {})
    if evidence_path is not None:
        apply_plan["gate_evidence"]["path"] = str(evidence_path)
    if evidence_warnings:
        apply_plan.setdefault("warnings", [])
        for warning in evidence_warnings:
            apply_plan["warnings"].append({
                "source": "gate-evidence",
                "id": warning.get("id", "gate-evidence"),
                "detail": warning.get("detail", ""),
            })
        summary = apply_plan.setdefault("summary", {})
        summary["warnings"] = len(as_list(apply_plan.get("warnings")))


def load_gate_evidence_input(
    *,
    evidence_file: str | None = None,
    change_record_dir: str | None = None,
) -> tuple[dict[str, Any], Path | None, list[dict[str, str]], dict[str, Any] | None]:
    if evidence_file and change_record_dir:
        return {}, None, [
            {
                "severity": "error",
                "id": "gate-evidence-ambiguous-input",
                "path": "$",
                "detail": "Use either --evidence-file or --change-record-dir, not both.",
            }
        ], None
    if change_record_dir:
        directory = Path(change_record_dir).resolve()
        record_check = build_change_record_check(directory)
        if not record_check.get("ok"):
            warnings: list[dict[str, str]] = []
            for item in as_list(record_check.get("errors")):
                if isinstance(item, dict):
                    warnings.append({
                        "severity": "error",
                        "id": str(item.get("id") or "change-record-error"),
                        "path": str(item.get("path") or str(directory)),
                        "detail": str(item.get("detail") or ""),
                    })
            for item in as_list(record_check.get("warnings")):
                if isinstance(item, dict):
                    warnings.append({
                        "severity": "warning",
                        "id": str(item.get("id") or "change-record-warning"),
                        "path": str(item.get("path") or str(directory)),
                        "detail": str(item.get("detail") or ""),
                    })
            if not warnings:
                warnings.append({
                    "severity": "error",
                    "id": "change-record-invalid",
                    "path": str(directory),
                    "detail": f"{directory}: change record check failed",
                })
            return {}, directory / "gate-evidence.json", warnings, record_check
        evidence_path = directory / "gate-evidence.json"
        gate_evidence, warnings = load_gate_evidence(evidence_path)
        for item in as_list(record_check.get("warnings")):
            if isinstance(item, dict):
                warnings.append({
                    "severity": "warning",
                    "id": str(item.get("id") or "change-record-warning"),
                    "path": str(item.get("path") or str(directory)),
                    "detail": str(item.get("detail") or ""),
                })
        return gate_evidence, evidence_path, warnings, record_check
    evidence_path = Path(evidence_file).resolve() if evidence_file else None
    gate_evidence, warnings = load_gate_evidence(evidence_path)
    return gate_evidence, evidence_path, warnings, None


def attach_change_record_to_report(report: dict[str, Any], change_record: dict[str, Any] | None) -> None:
    if not isinstance(change_record, dict):
        return
    report["change_record"] = {
        "schema": change_record.get("schema"),
        "path": change_record.get("path"),
        "ok": bool(change_record.get("ok")),
        "summary": change_record.get("summary") if isinstance(change_record.get("summary"), dict) else {},
        "records": [
            {
                "id": row.get("id"),
                "file": row.get("file"),
                "status": row.get("status"),
                "ok": row.get("ok"),
            }
            for row in as_list(change_record.get("records"))
            if isinstance(row, dict)
        ],
    }
    summary = report.setdefault("summary", {})
    if isinstance(summary, dict):
        summary["change_record_provided"] = True
        summary["change_record_ok"] = bool(change_record.get("ok"))


def build_apply_result(
    apply_plan: dict[str, Any],
    *,
    dry_run: bool,
    confirm_apply: str = "",
    selected_batches: list[str] | None = None,
) -> dict[str, Any]:
    readiness = apply_plan.get("apply_readiness", {}) if isinstance(apply_plan.get("apply_readiness"), dict) else {}
    summary = apply_plan.get("summary", {}) if isinstance(apply_plan.get("summary"), dict) else {}
    expected_confirmation = "APPLY-HOMENET"
    confirmation_provided = bool(confirm_apply)
    confirmation_accepted = confirm_apply == expected_confirmation
    available_batches = [
        str(row.get("batch_id") or "")
        for row in as_list(readiness.get("batch_readiness"))
        if isinstance(row, dict) and row.get("batch_id")
    ]
    requested_batches = [str(batch) for batch in as_list(selected_batches) if str(batch)]
    effective_batches = requested_batches or available_batches
    unknown_batches = sorted({batch for batch in effective_batches if batch not in set(available_batches)})
    selected_batch_rows = [
        row
        for row in as_list(readiness.get("batch_readiness"))
        if isinstance(row, dict) and str(row.get("batch_id") or "") in set(effective_batches)
    ]
    blocked_batches = [
        row
        for row in selected_batch_rows
        if isinstance(row, dict) and row.get("status") == "blocked"
    ]
    disabled_batches = [
        row
        for row in selected_batch_rows
        if isinstance(row, dict) and row.get("status") == "gates-clear-but-disabled"
    ]
    execution_items_by_id = {
        str(item.get("artifact_id") or ""): item
        for item in as_list(apply_plan.get("execution_plan"))
        if isinstance(item, dict) and item.get("artifact_id")
    }
    backup_items_by_id = {
        str(item.get("artifact_id") or ""): item
        for item in as_list(apply_plan.get("backup_plan"))
        if isinstance(item, dict) and item.get("artifact_id")
    }
    writer_contracts_by_id = {
        str(item.get("id") or ""): item
        for item in as_list(apply_plan.get("writer_contracts"))
        if isinstance(item, dict) and item.get("id")
    }
    executor_capabilities_by_writer = {
        str(item.get("writer") or ""): item
        for item in as_list(apply_plan.get("executor_capabilities"))
        if isinstance(item, dict) and item.get("writer")
    }
    execution_batches_by_id = {
        str(item.get("id") or ""): item
        for item in as_list(apply_plan.get("execution_batches"))
        if isinstance(item, dict) and item.get("id")
    }
    batch_packages = []
    for row in selected_batch_rows:
        batch_id = str(row.get("batch_id") or "")
        batch = execution_batches_by_id.get(batch_id, {})
        artifact_ids = [str(item) for item in as_list(batch.get("artifacts")) if str(item)]
        execution_items = [
            execution_items_by_id[artifact_id]
            for artifact_id in artifact_ids
            if artifact_id in execution_items_by_id
        ]
        writers = sorted({str(item.get("writer") or "") for item in execution_items if item.get("writer")})
        backup_items = [
            backup_items_by_id[artifact_id]
            for artifact_id in artifact_ids
            if artifact_id in backup_items_by_id
        ]
        batch_packages.append({
            "batch_id": batch_id,
            "status": row.get("status"),
            "eligible_for_write": False,
            "artifact_count": len(artifact_ids),
            "artifacts": artifact_ids,
            "execution_items": execution_items,
            "backup_items": backup_items,
            "writers": writers,
            "writer_contracts": [
                writer_contracts_by_id[writer]
                for writer in writers
                if writer in writer_contracts_by_id
            ],
            "executor_capabilities": [
                executor_capabilities_by_writer[writer]
                for writer in writers
                if writer in executor_capabilities_by_writer
            ],
            "pre_checks": as_list(batch.get("pre_checks")),
            "post_checks": as_list(batch.get("post_checks")),
            "failure_action": batch.get("failure_action") or row.get("detail") or "",
            "blocked_gates": as_list(row.get("blocked_gates")),
            "prerequisite_blockers": as_list(row.get("prerequisite_blockers")),
        })
    result_status = "dry-run" if dry_run else "refused"
    return {
        "schema": "homenet.apply_result.v1",
        "dry_run": bool(dry_run),
        "confirmed": confirmation_accepted,
        "confirmation": {
            "required": True,
            "provided": confirmation_provided,
            "accepted": confirmation_accepted,
            "expected_value": expected_confirmation,
            "effect": "Recorded only; write-side apply remains disabled in this build.",
        },
        "status": result_status,
        "applied": False,
        "writes_files": False,
        "writes_live_config": False,
        "write_side_apply_implemented": False,
        "reason": "write-side HomeNet apply is disabled in this build",
        "instance": apply_plan.get("instance") or {},
        "profile": apply_plan.get("profile"),
        "apply_plan_schema": apply_plan.get("schema"),
        "apply_readiness": readiness,
        "batch_selection": {
            "requested": requested_batches,
            "available": available_batches,
            "selected": [str(row.get("batch_id") or "") for row in selected_batch_rows],
            "unknown": unknown_batches,
            "scope": "selected" if requested_batches else "all",
            "effect": "Limits this refusal result to selected batches only; write-side apply remains disabled.",
        },
        "summary": {
            "artifacts": summary.get("artifacts", 0),
            "execution_items": summary.get("execution_items", 0),
            "execution_batches": summary.get("execution_batches", 0),
            "selected_batches": len(selected_batch_rows),
            "unknown_batches": len(unknown_batches),
            "execution_enabled": summary.get("execution_enabled", 0),
            "reviewable_batches": summary.get("reviewable_batches", 0),
            "blocked_batches": summary.get("blocked_batches", 0),
            "disabled_batches": summary.get("disabled_batches", 0),
            "apply_gates_blocked": summary.get("apply_gates_blocked", 0),
            "apply_gates_passed": summary.get("apply_gates_passed", 0),
            "gate_evidence_applied": summary.get("gate_evidence_applied", False),
        },
        "blocked_batches": blocked_batches,
        "disabled_batches": disabled_batches,
        "batch_packages": batch_packages,
        "next_actions": [
            "Review apply_readiness and blocked_batches.",
            "Keep live changes in source tools until write-side apply is implemented.",
            "Use --batch <id> to scope a refusal result to one future execution batch.",
            "Use --confirm-apply APPLY-HOMENET only as an explicit refusal/audit marker in this build.",
            "Use ./homenet apply --dry-run --evidence-file <file> to inspect gate movement without writes.",
            "Run ./homenet verify --live before and after any manual source-tool change.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Apply result contains gate status, artifact ids, and batch status only; it does not print secret values.",
        },
    }


REVIEWABLE_APPLY_FILES = {
    "config-review": {},
    "review-only": {
        "docs.maintenance": "maintenance.md",
        "verify.report": "verify.json",
    },
    "server-runtime-review": {
        "observability-homenet.metadata": "metadata.json",
        "observability-homenet.kuma-inventory": "kuma.json",
    },
}


def reviewable_apply_file_specs(
    state: dict[str, Any],
    instance: Path,
    apply_result: dict[str, Any],
    batch_id: str,
) -> list[dict[str, str]]:
    metadata = build_metadata(state, instance)
    artifacts = []
    for package in as_list(apply_result.get("batch_packages")):
        if isinstance(package, dict) and str(package.get("batch_id") or "") == batch_id:
            artifacts = [str(item) for item in as_list(package.get("artifacts"))]
            break
    artifact_set = set(artifacts)
    specs: list[dict[str, str]] = []
    if batch_id == "config-review":
        config_plan = build_config_plan(metadata, instance)
        for fragment in as_list(config_plan.get("fragments")):
            if not isinstance(fragment, dict):
                continue
            artifact_id = str(fragment.get("artifact_id") or "")
            if artifact_set and artifact_id not in artifact_set:
                continue
            filename = config_fragment_filename(fragment)
            specs.append({
                "name": filename,
                "artifact": artifact_id,
                "fragment": str(fragment.get("id") or ""),
                "content": str(fragment.get("content") or "").rstrip() + "\n",
            })
        return specs
    expected_files = expected_reviewable_apply_files(batch_id, artifacts)
    if "docs.maintenance" in expected_files:
        specs.append({
            "name": "maintenance.md",
            "artifact": "docs.maintenance",
            "fragment": "",
            "content": render_instance_docs(metadata).rstrip() + "\n",
        })
    if "verify.report" in expected_files:
        verify = {
            "schema": "homenet.verify.v1",
            "ok": True,
            "live": False,
            "instance": str(instance),
            "checked": [verify_instance(instance, live=False)],
            "failures": 0,
        }
        specs.append({
            "name": "verify.json",
            "artifact": "verify.report",
            "fragment": "",
            "content": json.dumps(verify, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        })
    if "observability-homenet.metadata" in expected_files:
        specs.append({
            "name": "metadata.json",
            "artifact": "observability-homenet.metadata",
            "fragment": "",
            "content": json.dumps(metadata, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        })
    if "observability-homenet.kuma-inventory" in expected_files:
        kuma = build_kuma_export(metadata)
        specs.append({
            "name": "kuma.json",
            "artifact": "observability-homenet.kuma-inventory",
            "fragment": "",
            "content": json.dumps(kuma, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        })
    return specs


def expected_reviewable_apply_files(batch_id: str, artifacts: list[str] | None = None) -> dict[str, str]:
    mapping = REVIEWABLE_APPLY_FILES.get(batch_id, {})
    if artifacts is None:
        return dict(mapping)
    selected = {str(item) for item in artifacts}
    return {
        artifact: filename
        for artifact, filename in mapping.items()
        if artifact in selected
    }


def reviewable_apply_file_payloads(
    state: dict[str, Any],
    instance: Path,
    apply_result: dict[str, Any],
    batch_id: str,
) -> dict[str, str]:
    return {
        str(spec.get("name") or ""): str(spec.get("content") or "")
        for spec in reviewable_apply_file_specs(state, instance, apply_result, batch_id)
        if spec.get("name")
    }


def write_reviewable_apply_files(
    state: dict[str, Any],
    instance: Path,
    apply_result: dict[str, Any],
    batch_id: str,
    output_dir: Path,
    *,
    force: bool = False,
) -> dict[str, Any]:
    existing = output_dir.exists() and any(output_dir.iterdir())
    if existing and not force:
        return {
            "ok": False,
            "error": f"{output_dir} is not empty. Use --force to overwrite generated review files.",
            "output_dir": str(output_dir),
            "files": [],
        }
    output_dir.mkdir(parents=True, exist_ok=True)
    file_specs = reviewable_apply_file_specs(state, instance, apply_result, batch_id)
    written = []
    for spec in file_specs:
        name = str(spec.get("name") or "")
        content = str(spec.get("content") or "")
        target = output_dir / name
        target.write_text(content, encoding="utf-8")
        written.append({
            "path": str(target),
            "name": name,
            "artifact": spec.get("artifact") or "",
            "fragment": spec.get("fragment") or "",
            "bytes": len(content.encode("utf-8")),
        })
    manifest = {
        "schema": "homenet.reviewable_apply_manifest.v1",
        "instance": apply_result.get("instance") or {},
        "profile": apply_result.get("profile"),
        "batch": batch_id,
        "artifacts": [
            str(item)
            for package in as_list(apply_result.get("batch_packages"))
            if isinstance(package, dict) and str(package.get("batch_id") or "") == batch_id
            for item in as_list(package.get("artifacts"))
        ],
        "writes_files": True,
        "writes_live_config": False,
        "source_schema": apply_result.get("schema"),
        "files": written,
        "privacy": {
            "secrets_included": False,
            "note": "Reviewable apply writes local review outputs only; it does not include secret values or live command output.",
        },
    }
    manifest_content = json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    manifest_target = output_dir / "manifest.json"
    manifest_target.write_text(manifest_content, encoding="utf-8")
    written.append({
        "path": str(manifest_target),
        "name": "manifest.json",
        "bytes": len(manifest_content.encode("utf-8")),
    })
    return {
        "ok": True,
        "output_dir": str(output_dir),
        "files": written,
        "file_count": len(written),
        "writes_live_config": False,
    }


def build_review_only_apply_result(
    state: dict[str, Any],
    instance: Path,
    apply_plan: dict[str, Any],
    *,
    confirm_apply: str,
    selected_batches: list[str] | None,
    output_dir: Path,
    force: bool = False,
) -> dict[str, Any]:
    result = build_apply_result(
        apply_plan,
        dry_run=False,
        confirm_apply=confirm_apply,
        selected_batches=selected_batches,
    )
    selected = as_list(result.get("batch_selection", {}).get("selected") if isinstance(result.get("batch_selection"), dict) else [])
    unknown = as_list(result.get("batch_selection", {}).get("unknown") if isinstance(result.get("batch_selection"), dict) else [])
    confirmation = result.get("confirmation") if isinstance(result.get("confirmation"), dict) else {}
    reviewable_batches = {
        str(row.get("batch_id") or "")
        for row in as_list(result.get("apply_readiness", {}).get("batch_readiness") if isinstance(result.get("apply_readiness"), dict) else [])
        if isinstance(row, dict) and row.get("review_only") is True and row.get("status") == "reviewable"
    }
    errors = []
    if unknown:
        errors.append(f"Unknown batch selection: {', '.join(str(item) for item in unknown)}")
    selected_batch = str(selected[0]) if len(selected) == 1 else ""
    if len(selected) != 1 or selected_batch not in reviewable_batches:
        errors.append(f"Reviewable apply requires exactly one reviewable --batch value: {', '.join(sorted(reviewable_batches))}.")
    if not confirmation.get("accepted"):
        errors.append("Review-only apply requires --confirm-apply APPLY-HOMENET.")
    review_package = {
        "ok": False,
        "output_dir": str(output_dir),
        "files": [],
        "file_count": 0,
        "writes_live_config": False,
    }
    if not errors:
        review_package = write_reviewable_apply_files(state, instance, result, selected_batch, output_dir, force=force)
        if not review_package.get("ok"):
            errors.append(str(review_package.get("error") or "failed to write review-only outputs"))
    if errors:
        result.update({
            "status": "refused",
            "applied": False,
            "writes_files": False,
            "writes_live_config": False,
            "write_side_apply_implemented": False,
            "reason": "; ".join(errors),
            "review_only_apply": review_package,
        })
        result["confirmation"]["effect"] = "Review-only output was not written."
        result.setdefault("next_actions", []).insert(0, "Use a single reviewable --batch value with --confirm-apply APPLY-HOMENET --review-output-dir <dir> for local review output only.")
        return result
    result.update({
        "status": "review-applied",
        "applied": True,
        "writes_files": True,
        "writes_live_config": False,
        "write_side_apply_implemented": False,
        "reason": f"{selected_batch} batch wrote local review outputs; live apply remains disabled",
        "review_only_apply": review_package,
    })
    result["confirmation"]["effect"] = "Enabled review-only local file output only; live configuration writes remain disabled."
    result["summary"]["review_only_files_written"] = review_package.get("file_count", 0)
    result["next_actions"] = [
        "Review the generated local files before any source-tool changes.",
        "Keep live OpenWrt, Docker/systemd, Cloudflare, Kuma, and service-native changes in source tools.",
        "Run ./homenet change-pack before any future guarded live write.",
    ]
    return result


def build_review_output_check(output_dir: Path | None) -> dict[str, Any]:
    errors: list[dict[str, str]] = []
    warnings: list[dict[str, str]] = []
    files: list[dict[str, Any]] = []
    manifest: dict[str, Any] = {}
    expected_files: dict[str, str] = {}

    def add_error(check_id: str, path: str, detail: str) -> None:
        errors.append({"id": check_id, "path": path, "detail": detail})

    def add_warning(check_id: str, path: str, detail: str) -> None:
        warnings.append({"id": check_id, "path": path, "detail": detail})

    if output_dir is None:
        add_error("review-output-dir-required", "", "--dir is required")
    elif not output_dir.exists():
        add_error("review-output-dir-missing", str(output_dir), "directory does not exist")
    elif not output_dir.is_dir():
        add_error("review-output-dir-not-directory", str(output_dir), "path is not a directory")
    else:
        manifest_path = output_dir / "manifest.json"
        if not manifest_path.exists():
            add_error("review-output-manifest-missing", str(manifest_path), "manifest.json is missing")
        else:
            try:
                loaded = json.loads(manifest_path.read_text(encoding="utf-8"))
            except Exception as exc:  # noqa: BLE001 - operator-facing validation
                loaded = {}
                add_error("review-output-manifest-unreadable", str(manifest_path), f"manifest.json cannot be parsed: {exc}")
            if not isinstance(loaded, dict):
                add_error("review-output-manifest-invalid", str(manifest_path), "manifest top-level value must be an object")
                loaded = {}
            manifest = loaded
            if manifest.get("schema") != "homenet.reviewable_apply_manifest.v1":
                add_error("review-output-schema", str(manifest_path), "manifest schema must be homenet.reviewable_apply_manifest.v1")
            if manifest.get("writes_live_config") is not False:
                add_error("review-output-live-write", str(manifest_path), "manifest must declare writes_live_config=false")
            if manifest.get("writes_files") is not True:
                add_error("review-output-files-write", str(manifest_path), "manifest must declare writes_files=true")
            batch_id = str(manifest.get("batch") or "")
            artifacts = [str(item) for item in as_list(manifest.get("artifacts")) if str(item)]
            if batch_id not in REVIEWABLE_APPLY_FILES:
                add_error("review-output-batch", str(manifest_path), "manifest batch is not a known reviewable batch")
            if batch_id == "config-review":
                manifest_file_rows = [
                    row for row in as_list(manifest.get("files"))
                    if isinstance(row, dict) and str(row.get("name") or "") != "manifest.json"
                ]
                expected_files = {
                    str(row.get("artifact") or ""): str(row.get("name") or "")
                    for row in manifest_file_rows
                    if row.get("artifact") and row.get("name")
                }
                manifest_artifacts = sorted(expected_files.keys())
                if sorted(artifacts) != manifest_artifacts:
                    add_error("review-output-artifacts", str(manifest_path), "manifest artifacts do not match config-review file artifact references")
                for row in manifest_file_rows:
                    filename = str(row.get("name") or "")
                    artifact = str(row.get("artifact") or "")
                    if not filename:
                        add_error("review-output-file-name", str(manifest_path), "manifest file entry is missing name")
                        continue
                    file_path = output_dir / filename
                    if not file_path.exists():
                        add_error("review-output-file-missing", str(file_path), f"expected file for artifact {artifact} is missing")
                    else:
                        files.append({
                            "name": filename,
                            "path": str(file_path),
                            "artifact": artifact,
                            "fragment": row.get("fragment") or "",
                            "bytes": file_path.stat().st_size,
                        })
                allowed_names = {"manifest.json", *expected_files.values()}
            else:
                expected_files = expected_reviewable_apply_files(batch_id, artifacts)
                if sorted(artifacts) != sorted(expected_files.keys()):
                    add_error("review-output-artifacts", str(manifest_path), "manifest artifacts do not match the expected reviewable batch artifacts")
                for artifact, filename in expected_files.items():
                    file_path = output_dir / filename
                    if not file_path.exists():
                        add_error("review-output-file-missing", str(file_path), f"expected file for artifact {artifact} is missing")
                    else:
                        files.append({
                            "name": filename,
                            "path": str(file_path),
                            "artifact": artifact,
                            "bytes": file_path.stat().st_size,
                        })
                allowed_names = {"manifest.json", *expected_files.values()}
            for child in sorted(output_dir.iterdir(), key=lambda path: path.name):
                if child.name not in allowed_names:
                    add_warning("review-output-extra-file", str(child), "extra file is not part of the reviewable apply manifest")
            manifest_files = {
                str(item.get("name") or "")
                for item in as_list(manifest.get("files"))
                if isinstance(item, dict)
            }
            missing_from_manifest = sorted(set(expected_files.values()) - manifest_files)
            if missing_from_manifest:
                add_warning("review-output-manifest-files", str(manifest_path), "manifest files list does not include every expected output file")

    return {
        "schema": "homenet.review_output_check.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "prints_values": False,
        "path": str(output_dir) if output_dir is not None else "",
        "ok": not errors,
        "summary": {
            "errors": len(errors),
            "warnings": len(warnings),
            "files": len(files),
            "expected_files": len(expected_files),
            "batch": manifest.get("batch") or "",
        },
        "manifest": {
            "schema": manifest.get("schema") or "",
            "batch": manifest.get("batch") or "",
            "writes_files": manifest.get("writes_files"),
            "writes_live_config": manifest.get("writes_live_config"),
            "artifacts": as_list(manifest.get("artifacts")),
        },
        "files": files,
        "errors": errors,
        "warnings": warnings,
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Review output check validates manifest and file names only; it does not print file contents.",
        },
    }


def build_executor_plan(
    apply_plan: dict[str, Any],
    *,
    selected_batches: list[str] | None = None,
) -> dict[str, Any]:
    refusal = build_apply_result(
        apply_plan,
        dry_run=False,
        confirm_apply="",
        selected_batches=selected_batches,
    )
    batch_selection = refusal.get("batch_selection", {}) if isinstance(refusal.get("batch_selection"), dict) else {}
    batch_packages = [
        package
        for package in as_list(refusal.get("batch_packages"))
        if isinstance(package, dict)
    ]
    stages = []
    total_execution_items = 0
    total_backup_items = 0
    writer_counts: dict[str, int] = {}
    blocked_gates: set[str] = set()
    prerequisite_blockers: set[str] = set()
    for index, package in enumerate(batch_packages, start=1):
        batch_id = str(package.get("batch_id") or "")
        execution_items = [
            item
            for item in as_list(package.get("execution_items"))
            if isinstance(item, dict)
        ]
        backup_items = [
            item
            for item in as_list(package.get("backup_items"))
            if isinstance(item, dict)
        ]
        writers = [str(writer) for writer in as_list(package.get("writers")) if str(writer)]
        total_execution_items += len(execution_items)
        total_backup_items += len(backup_items)
        for writer in writers:
            writer_counts[writer] = writer_counts.get(writer, 0) + 1
        for gate in as_list(package.get("blocked_gates")):
            if str(gate):
                blocked_gates.add(str(gate))
        for gate in as_list(package.get("prerequisite_blockers")):
            if str(gate):
                prerequisite_blockers.add(str(gate))

        operations = []
        for item in execution_items:
            risk = str(item.get("risk") or "")
            review_only = risk in {"read-only", "generated-data"}
            operations.append({
                "artifact_id": item.get("artifact_id") or "",
                "writer": item.get("writer") or "",
                "target": item.get("target") or "",
                "kind": item.get("kind") or "",
                "risk": risk,
                "requires_backup": bool(item.get("requires_backup")),
                "operation": "review-output" if review_only else "future-write-disabled",
                "eligible_for_execution": False,
                "status": "review-only" if review_only else "disabled",
                "blocked_gates": as_list(item.get("blocked_gates")),
                "reason": item.get("reason") or "write-side HomeNet apply is disabled",
            })
        stages.append({
            "order": index,
            "batch_id": batch_id,
            "status": package.get("status"),
            "eligible_for_execution": False,
            "artifact_count": package.get("artifact_count", len(execution_items)),
            "pre_checks": [
                {"command": command, "executes_now": False}
                for command in as_list(package.get("pre_checks"))
            ],
            "backup_items": backup_items,
            "operations": operations,
            "post_checks": [
                {"command": command, "executes_now": False}
                for command in as_list(package.get("post_checks"))
            ],
            "writers": writers,
            "writer_contracts": as_list(package.get("writer_contracts")),
            "executor_capabilities": as_list(package.get("executor_capabilities")),
            "failure_action": package.get("failure_action") or "",
            "blocked_gates": as_list(package.get("blocked_gates")),
            "prerequisite_blockers": as_list(package.get("prerequisite_blockers")),
        })

    unknown_batches = as_list(batch_selection.get("unknown")) if isinstance(batch_selection, dict) else []
    hard_blockers = [
        "write-side apply implementation is disabled",
        "executor plan is read-only and will not run commands",
    ]
    if unknown_batches:
        hard_blockers.append("requested batch id is unknown")
    if prerequisite_blockers:
        hard_blockers.append("one or more prerequisite gates are still blocked")
    return {
        "schema": "homenet.executor_plan.v1",
        "instance": apply_plan.get("instance") or {},
        "profile": apply_plan.get("profile"),
        "read_only": True,
        "dry_run": True,
        "executes_commands": False,
        "writes_live_config": False,
        "write_enabled": False,
        "source_apply_plan_schema": apply_plan.get("schema"),
        "batch_selection": batch_selection,
        "summary": {
            "selected_batches": len(batch_packages),
            "unknown_batches": len(unknown_batches),
            "stages": len(stages),
            "execution_items": total_execution_items,
            "backup_items": total_backup_items,
            "writers": len(writer_counts),
            "blocked_gates": len(blocked_gates),
            "prerequisite_blockers": len(prerequisite_blockers),
        },
        "writer_counts": dict(sorted(writer_counts.items())),
        "hard_blockers": hard_blockers,
        "stages": stages,
        "runner_contract": {
            "current_status": "contract-only",
            "allowed_now": [
                "read apply plan",
                "select batches",
                "inspect backup requirements",
                "inspect writer contracts",
                "inspect pre/post checks",
            ],
            "forbidden_now": [
                "execute backup commands",
                "write OpenWrt config",
                "write Docker Compose/systemd config",
                "write Kuma database",
                "write Cloudflare resources",
                "restart services",
            ],
            "promotion_required": [
                "module-specific renderer produces deployable artifacts",
                "backup capture is implemented and verified",
                "pre-apply live evidence is captured",
                "operator confirmation and maintenance window are recorded",
                "source-tool ownership is proven for every writer",
                "post-apply verification and rollback path are executable",
            ],
        },
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Executor plan contains artifact ids, writer ids, commands to run later, and backup contracts only.",
        },
    }


def build_executor_result(
    executor_plan: dict[str, Any],
    *,
    execute: bool,
    confirm_execute: str = "",
) -> dict[str, Any]:
    expected_confirmation = "EXECUTE-HOMENET"
    confirmation_provided = bool(confirm_execute)
    confirmation_accepted = confirm_execute == expected_confirmation
    summary = executor_plan.get("summary", {}) if isinstance(executor_plan.get("summary"), dict) else {}
    batch_selection = executor_plan.get("batch_selection", {}) if isinstance(executor_plan.get("batch_selection"), dict) else {}
    unknown_batches = as_list(batch_selection.get("unknown")) if isinstance(batch_selection, dict) else []
    blocked_operations = []
    for stage in as_list(executor_plan.get("stages")):
        if not isinstance(stage, dict):
            continue
        batch_id = str(stage.get("batch_id") or "")
        for operation in as_list(stage.get("operations")):
            if not isinstance(operation, dict):
                continue
            blocked_operations.append({
                "batch_id": batch_id,
                "artifact_id": operation.get("artifact_id") or "",
                "writer": operation.get("writer") or "",
                "target": operation.get("target") or "",
                "operation": operation.get("operation") or "",
                "status": operation.get("status") or "disabled",
                "blocked_gates": as_list(operation.get("blocked_gates")),
                "reason": operation.get("reason") or "executor runner is disabled",
            })
    refusal_reasons = [
        "executor run is disabled in this build",
        "exec-plan is contract-only and does not run commands",
    ]
    if not execute:
        refusal_reasons.append("execute was not requested")
    if unknown_batches:
        refusal_reasons.append("requested batch id is unknown")
    return {
        "schema": "homenet.executor_result.v1",
        "status": "refused" if execute else "dry-run",
        "execute_requested": bool(execute),
        "executed": False,
        "executes_commands": False,
        "writes_files": False,
        "writes_live_config": False,
        "write_enabled": False,
        "reason": "; ".join(refusal_reasons),
        "confirmation": {
            "required": True,
            "provided": confirmation_provided,
            "accepted": confirmation_accepted,
            "expected_value": expected_confirmation,
            "effect": "Recorded only; executor run remains disabled in this build.",
        },
        "instance": executor_plan.get("instance") or {},
        "profile": executor_plan.get("profile"),
        "executor_plan_schema": executor_plan.get("schema"),
        "batch_selection": batch_selection,
        "summary": {
            "selected_batches": summary.get("selected_batches", 0),
            "unknown_batches": summary.get("unknown_batches", 0),
            "stages": summary.get("stages", 0),
            "execution_items": summary.get("execution_items", 0),
            "backup_items": summary.get("backup_items", 0),
            "writers": summary.get("writers", 0),
            "blocked_operations": len(blocked_operations),
        },
        "blocked_operations": blocked_operations,
        "hard_blockers": as_list(executor_plan.get("hard_blockers")),
        "runner_contract": executor_plan.get("runner_contract") or {},
        "next_actions": [
            "Review exec-plan output and backup-plan output before any future execution.",
            "Keep live changes in source tools until guarded writer implementations are enabled.",
            "Run ./homenet verify --live before and after any manual source-tool change.",
            "Do not execute generated operations directly from chat or review output.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "captured_data_included": False,
            "note": "Executor result contains planned artifact ids and refusal status only; it does not include command output or secret values.",
        },
    }


def print_executor_result_markdown(result: dict[str, Any]) -> None:
    instance = result.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or "instance"
    print(f"# Executor Result - {name}")
    print()
    print(f"- schema: `{result.get('schema')}`")
    print(f"- status: {result.get('status')}")
    print(f"- execute requested: {result.get('execute_requested')}")
    print(f"- executed: {result.get('executed')}")
    print(f"- executes commands: {result.get('executes_commands')}")
    print(f"- writes files: {result.get('writes_files')}")
    print(f"- writes live config: {result.get('writes_live_config')}")
    print(f"- reason: {result.get('reason')}")
    print()
    confirmation = result.get("confirmation", {})
    if isinstance(confirmation, dict):
        print("## Confirmation")
        print()
        print(f"- required: {confirmation.get('required')}")
        print(f"- provided: {confirmation.get('provided')}")
        print(f"- accepted: {confirmation.get('accepted')}")
        print(f"- expected value: `{confirmation.get('expected_value')}`")
        print(f"- effect: {confirmation.get('effect')}")
        print()
    batch_selection = result.get("batch_selection", {})
    if isinstance(batch_selection, dict):
        print("## Batch Selection")
        print()
        print(f"- scope: {batch_selection.get('scope')}")
        print(f"- requested: {', '.join(str(item) for item in as_list(batch_selection.get('requested'))) or 'all'}")
        print(f"- selected: {', '.join(str(item) for item in as_list(batch_selection.get('selected'))) or 'none'}")
        print(f"- unknown: {', '.join(str(item) for item in as_list(batch_selection.get('unknown'))) or 'none'}")
        print()
    print("## Summary")
    print()
    for key, value in (result.get("summary") or {}).items():
        print(f"- {key}: {value}")
    print()
    if result.get("blocked_operations"):
        print("## Blocked Operations")
        print()
        print("| Artifact | Batch | Writer | Target | Status | Reason |")
        print("| --- | --- | --- | --- | --- | --- |")
        for item in as_list(result.get("blocked_operations")):
            if not isinstance(item, dict):
                continue
            print(
                f"| {item.get('artifact_id', '')} | {item.get('batch_id', '')} | {item.get('writer', '')} | "
                f"{item.get('target', '')} | {item.get('status', '')} | {item.get('reason', '')} |"
            )
        print()
    print("## Next Actions")
    print()
    for item in as_list(result.get("next_actions")):
        print(f"- {item}")
    print()


def build_backup_execution_plan(
    apply_plan: dict[str, Any],
    *,
    selected_batches: list[str] | None = None,
) -> dict[str, Any]:
    executor_plan = build_executor_plan(apply_plan, selected_batches=selected_batches)
    batch_selection = executor_plan.get("batch_selection", {}) if isinstance(executor_plan.get("batch_selection"), dict) else {}
    rows = []
    method_counts: dict[str, int] = {}
    target_counts: dict[str, int] = {}
    module_counts: dict[str, int] = {}
    backup_contracts = load_module_backup_contracts()
    method_capability_catalog = backup_contracts.get("method_capabilities") if isinstance(backup_contracts.get("method_capabilities"), dict) else {}
    method_capability_catalog.setdefault("source-tool-export", {
        "owner": "manual-source-tool",
        "implementation_status": "manual-only",
        "supports_plan": True,
        "supports_capture": False,
        "supports_restore": False,
        "supports_verify": False,
        "disabled_reason": "Generic source-tool export has no safe automated command until the module declares an exact source tool.",
        "implementation_required": ["module-specific source tool", "export command or API contract", "restore command or API contract", "verification check"],
    })
    for stage in as_list(executor_plan.get("stages")):
        if not isinstance(stage, dict):
            continue
        batch_id = str(stage.get("batch_id") or "")
        for order, item in enumerate(as_list(stage.get("backup_items")), start=1):
            if not isinstance(item, dict):
                continue
            method = str(item.get("method") or "unknown")
            target = str(item.get("target") or "unknown")
            module_id = str(item.get("module_id") or "unknown")
            method_counts[method] = method_counts.get(method, 0) + 1
            target_counts[target] = target_counts.get(target, 0) + 1
            module_counts[module_id] = module_counts.get(module_id, 0) + 1
            rows.append({
                "batch_id": batch_id,
                "order": len(rows) + 1,
                "batch_order": order,
                "artifact_id": item.get("artifact_id") or "",
                "module_id": module_id,
                "target": target,
                "kind": item.get("kind") or "",
                "risk": item.get("risk") or "",
                "path": item.get("path") or "",
                "owner": item.get("owner") or "",
                "method": method,
                "backup_root": item.get("backup_root") or "${BACKUP_DIR}",
                "capture_command": item.get("capture_plan") or "",
                "restore_plan": item.get("restore_plan") or "",
                "verify_command": item.get("verify_plan") or "",
                "requires_live_access": bool(item.get("requires_live_access")),
                "executes_now": False,
                "capture_enabled": False,
                "restore_enabled": False,
                "verify_enabled": False,
            })
    unknown_batches = as_list(batch_selection.get("unknown")) if isinstance(batch_selection, dict) else []
    blockers = [
        "backup capture runner is contract-only in this build",
        "commands are listed for review only and are not executed",
        "operator must choose and create BACKUP_DIR outside git before any future capture",
    ]
    if unknown_batches:
        blockers.append("requested batch id is unknown")
    method_capabilities = []
    for method, count in sorted(method_counts.items()):
        capability = method_capability_catalog.get(method, method_capability_catalog["source-tool-export"])
        method_capabilities.append({
            "method": method,
            **capability,
            "item_count": count,
            "capture_enabled": False,
            "restore_enabled": False,
            "verify_enabled": False,
        })
    return {
        "schema": "homenet.backup_plan.v1",
        "instance": apply_plan.get("instance") or {},
        "profile": apply_plan.get("profile"),
        "read_only": True,
        "dry_run": True,
        "executes_commands": False,
        "writes_live_config": False,
        "capture_enabled": False,
        "restore_enabled": False,
        "verify_enabled": False,
        "source_apply_plan_schema": apply_plan.get("schema"),
        "source_executor_plan_schema": executor_plan.get("schema"),
        "batch_selection": batch_selection,
        "summary": {
            "selected_batches": len(as_list(batch_selection.get("selected"))) if isinstance(batch_selection, dict) else 0,
            "unknown_batches": len(unknown_batches),
            "backup_items": len(rows),
            "methods": len(method_counts),
            "targets": len(target_counts),
            "modules": len(module_counts),
            "requires_live_access": sum(1 for row in rows if row.get("requires_live_access")),
            "backup_contracts_ok": bool(backup_contracts.get("ok")),
            "backup_contract_errors": len(as_list(backup_contracts.get("errors"))),
        },
        "backup_contracts": {
            "schema": backup_contracts.get("schema"),
            "source": backup_contracts.get("source"),
            "ok": bool(backup_contracts.get("ok")),
            "method_count": backup_contracts.get("method_count", 0),
            "errors": as_list(backup_contracts.get("errors")),
        },
        "backup_set_contract": {
            "root": "${BACKUP_DIR}",
            "must_be_outside_git": True,
            "must_be_operator_chosen": True,
            "should_include": [
                "backup-plan.json",
                "pre-apply verify --live output",
                "captured source-tool exports or files",
                "post-apply verify --live output when a future write is enabled",
            ],
            "forbidden_locations": [
                "git-tracked instance files",
                "public docs",
                "chat transcripts",
                "service runtime directories being modified",
            ],
        },
        "method_counts": dict(sorted(method_counts.items())),
        "method_capabilities": method_capabilities,
        "target_counts": dict(sorted(target_counts.items())),
        "module_counts": dict(sorted(module_counts.items())),
        "blockers": blockers,
        "items": rows,
        "runner_contract": {
            "current_status": "contract-only",
            "allowed_now": [
                "inspect capture commands",
                "inspect restore plans",
                "inspect verify commands",
                "choose a future backup directory",
            ],
            "forbidden_now": [
                "create backup directory",
                "copy files",
                "ssh into OpenWrt or room AP",
                "read or copy service databases",
                "execute restore commands",
                "restart services",
            ],
            "promotion_required": [
                "backup directory policy and retention are explicit",
                "capture commands are source-tool owned and shell-escaped",
                "pre-capture live evidence is saved",
                "restore verification is tested per method",
                "secrets and runtime databases are excluded from chat and git",
            ],
        },
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Backup plan contains paths and future commands only; it does not execute them or include captured data.",
        },
    }


def build_backup_result(
    backup_plan: dict[str, Any],
    *,
    capture: bool,
    restore: bool = False,
    verify: bool = False,
    confirm_capture: str = "",
    confirm_restore: str = "",
    confirm_verify: str = "",
) -> dict[str, Any]:
    operation = "verify" if verify else "restore" if restore else "capture" if capture else "plan"
    expected_confirmation = (
        "VERIFY-HOMENET"
        if verify
        else "RESTORE-HOMENET"
        if restore
        else "CAPTURE-HOMENET"
    )
    provided_value = confirm_verify if verify else confirm_restore if restore else confirm_capture
    confirmation_provided = bool(provided_value)
    confirmation_accepted = provided_value == expected_confirmation
    summary = backup_plan.get("summary", {}) if isinstance(backup_plan.get("summary"), dict) else {}
    batch_selection = backup_plan.get("batch_selection", {}) if isinstance(backup_plan.get("batch_selection"), dict) else {}
    method_capabilities_by_id = {
        str(item.get("method") or ""): item
        for item in as_list(backup_plan.get("method_capabilities"))
        if isinstance(item, dict) and item.get("method")
    }
    unknown_batches = as_list(batch_selection.get("unknown")) if isinstance(batch_selection, dict) else []
    refusal_reasons = [
        f"backup {operation} execution is disabled in this build" if operation in {"capture", "restore", "verify"} else "backup execution is disabled in this build",
        "backup-plan is contract-only and does not run commands",
    ]
    if not capture and not restore and not verify:
        refusal_reasons.append("capture, restore, or verify was not requested")
    if unknown_batches:
        refusal_reasons.append("requested batch id is unknown")
    return {
        "schema": "homenet.backup_result.v1",
        "status": "refused" if capture or restore or verify else "dry-run",
        "operation": operation,
        "capture_requested": bool(capture),
        "restore_requested": bool(restore),
        "verify_requested": bool(verify),
        "captured": False,
        "restored": False,
        "verified": False,
        "executes_commands": False,
        "writes_files": False,
        "writes_live_config": False,
        "capture_enabled": False,
        "restore_enabled": False,
        "verify_enabled": False,
        "reason": "; ".join(refusal_reasons),
        "confirmation": {
            "required": True,
            "provided": confirmation_provided,
            "accepted": confirmation_accepted,
            "expected_value": expected_confirmation,
            "effect": f"Recorded only; backup {operation} execution remains disabled in this build.",
        },
        "instance": backup_plan.get("instance") or {},
        "profile": backup_plan.get("profile"),
        "backup_plan_schema": backup_plan.get("schema"),
        "batch_selection": batch_selection,
        "summary": {
            "selected_batches": summary.get("selected_batches", 0),
            "unknown_batches": summary.get("unknown_batches", 0),
            "backup_items": summary.get("backup_items", 0),
            "requires_live_access": summary.get("requires_live_access", 0),
            "methods": summary.get("methods", 0),
            "targets": summary.get("targets", 0),
            "modules": summary.get("modules", 0),
        },
        "blocked_items": [
            {
                "artifact_id": item.get("artifact_id") or "",
                "batch_id": item.get("batch_id") or "",
                "method": item.get("method") or "",
                "target": item.get("target") or "",
                "capture_enabled": False,
                "restore_enabled": False,
                "reason": (
                    method_capabilities_by_id.get(str(item.get("method") or ""), {}).get("disabled_reason")
                    or f"backup {operation} runner is disabled"
                ),
            }
            for item in as_list(backup_plan.get("items"))
            if isinstance(item, dict)
        ],
        "backup_set_contract": backup_plan.get("backup_set_contract") or {},
        "blockers": as_list(backup_plan.get("blockers")),
        "next_actions": [
            "Review backup-plan output and choose BACKUP_DIR outside git.",
            "Keep backup capture, restore, and verification manual through source tools until the backup runner is implemented.",
            "Run ./homenet verify --live before and after any manual source-tool change.",
            "Do not paste captured database, token, private key, cookie, or proxy subscription contents into chat or git.",
        ],
        "privacy": {
            "secrets_included": False,
            "captured_data_included": False,
            "secret_values_checked": False,
            "note": "Backup result contains planned artifact ids and refusal status only; it does not include captured files or command output.",
        },
    }


