def backup_capture_filename(item: dict[str, Any]) -> str:
    artifact_id = str(item.get("artifact_id") or "artifact")
    method = str(item.get("method") or "")
    kind = str(item.get("kind") or "")
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "-", artifact_id).strip("-") or "artifact"
    if kind == "route-policy":
        return f"captures/{safe}.route-policy.txt"
    if method == "openwrt-ssh":
        return f"captures/{safe}.uci"
    if method == "database-copy":
        return f"captures/{safe}.database-export"
    path = str(item.get("path") or "")
    if path.endswith("/") or "*" in path:
        return f"captures/{safe}.tgz"
    suffix = Path(path).suffix or ".backup"
    return f"captures/{safe}{suffix}"


def build_backup_set_report(plan: dict[str, Any]) -> dict[str, Any]:
    contract = plan.get("backup_set_contract") if isinstance(plan.get("backup_set_contract"), dict) else {}
    items = []
    for item in as_list(plan.get("items")):
        if not isinstance(item, dict):
            continue
        items.append({
            "artifact_id": item.get("artifact_id") or "",
            "batch_id": item.get("batch_id") or "",
            "order": item.get("order", 0),
            "method": item.get("method") or "",
            "target": item.get("target") or "",
            "risk": item.get("risk") or "",
            "source_path": item.get("path") or "",
            "expected_capture_path": backup_capture_filename(item),
            "capture_command": item.get("capture_command") or "",
            "restore_plan": item.get("restore_plan") or "",
            "verify_command": item.get("verify_command") or "",
            "capture_proof_required": [
                "capture file exists under the backup set",
                "capture file is not stored in git, docs, chat, or the modified runtime path",
                "capture is linked to this artifact id and batch id in manifest.json",
            ],
            "restore_proof_required": [
                "restore plan reviewed before apply",
                "service/source-tool owner identified",
                "post-restore verification command is known before any write",
            ],
            "verify_proof_required": [
                "verify command or source-tool check result captured as summary",
                "no secret values or raw private config printed into public artifacts",
            ],
        })
    manifest_template = {
        "schema": "homenet.backup_set_manifest.v1",
        "created_at": "<iso8601>",
        "operator": "<name-or-local-operator-label>",
        "source_backup_plan_schema": plan.get("schema"),
        "backup_root": contract.get("root") or "${BACKUP_DIR}",
        "pre_apply_live_proof": "live-proof.json or saved verify --live summary",
        "post_apply_live_proof": "saved after guarded write; omit only when no write occurred",
        "items": [
            {
                "artifact_id": item.get("artifact_id"),
                "batch_id": item.get("batch_id"),
                "method": item.get("method"),
                "capture_path": item.get("expected_capture_path"),
                "captured": False,
                "verified": False,
                "restored": False,
            }
            for item in items
        ],
    }
    return {
        "schema": "homenet.backup_set.v1",
        "source_schema": plan.get("schema"),
        "instance": plan.get("instance") or {},
        "profile": plan.get("profile"),
        "read_only": True,
        "executes_commands": False,
        "writes_files": False,
        "writes_live_config": False,
        "backup_root": contract.get("root") or "${BACKUP_DIR}",
        "summary": {
            "items": len(items),
            "methods": len(set(str(item.get("method") or "") for item in items)),
            "targets": len(set(str(item.get("target") or "") for item in items)),
            "requires_operator_directory": bool(contract.get("must_be_operator_chosen", True)),
            "must_be_outside_git": bool(contract.get("must_be_outside_git", True)),
        },
        "manifest_template": manifest_template,
        "items": items,
        "required_files": [
            "manifest.json",
            "backup-plan.json",
            "live-proof.json or saved pre-apply verify --live summary",
            "captures/*",
            "saved post-apply verify --live summary when a future write is enabled",
        ],
        "forbidden_locations": as_list(contract.get("forbidden_locations")),
        "privacy": {
            "secrets_included": False,
            "captured_data_included": False,
            "secret_values_checked": False,
            "note": "Backup set report is a manifest contract only; it contains no captured files, databases, command output, or secret values.",
        },
    }


def initialize_backup_set_directory(report: dict[str, Any], plan: dict[str, Any], output_dir: Path, *, force: bool = False) -> dict[str, Any]:
    existing = output_dir.exists() and any(output_dir.iterdir())
    if existing and not force:
        return {
            "schema": "homenet.backup_set_init.v1",
            "ok": False,
            "status": "refused",
            "reason": f"{output_dir} is not empty. Use --force to overwrite generated backup-set init files.",
            "output_dir": str(output_dir),
            "writes_files": False,
            "writes_live_config": False,
            "executes_commands": False,
            "files": [],
        }
    try:
        resolved_output = output_dir.resolve(strict=False)
        resolved_repo = ROOT.resolve(strict=False)
        if resolved_output == resolved_repo or resolved_repo in resolved_output.parents:
            return {
                "schema": "homenet.backup_set_init.v1",
                "ok": False,
                "status": "refused",
                "reason": "backup set directory must stay outside the HomeNet git worktree",
                "output_dir": str(output_dir),
                "writes_files": False,
                "writes_live_config": False,
                "executes_commands": False,
                "files": [],
            }
    except Exception as exc:  # noqa: BLE001 - path validation should stay operator-facing
        return {
            "schema": "homenet.backup_set_init.v1",
            "ok": False,
            "status": "refused",
            "reason": f"cannot validate backup set directory: {exc}",
            "output_dir": str(output_dir),
            "writes_files": False,
            "writes_live_config": False,
            "executes_commands": False,
            "files": [],
        }

    output_dir.mkdir(parents=True, exist_ok=True)
    manifest = dict(report.get("manifest_template") if isinstance(report.get("manifest_template"), dict) else {})
    manifest["created_at"] = datetime.datetime.now(datetime.UTC).replace(microsecond=0).isoformat()
    manifest["operator"] = "local-operator"
    manifest["backup_root"] = str(output_dir.resolve(strict=False))
    manifest["pre_apply_live_proof"] = "pending-pre-apply-live.json"
    manifest["post_apply_live_proof"] = "pending-post-apply-live.json"
    manifest_path = output_dir / "manifest.json"
    backup_plan_path = output_dir / "backup-plan.json"
    manifest_content = json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    backup_plan_content = json.dumps(plan, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    manifest_path.write_text(manifest_content, encoding="utf-8")
    backup_plan_path.write_text(backup_plan_content, encoding="utf-8")
    check = build_backup_set_check(manifest_path)
    files = [
        {
            "name": "manifest.json",
            "path": str(manifest_path),
            "bytes": len(manifest_content.encode("utf-8")),
        },
        {
            "name": "backup-plan.json",
            "path": str(backup_plan_path),
            "bytes": len(backup_plan_content.encode("utf-8")),
        },
    ]
    return {
        "schema": "homenet.backup_set_init.v1",
        "ok": bool(check.get("ok")),
        "status": "initialized" if check.get("ok") else "invalid",
        "reason": "initialized backup set manifest and backup plan only; no captures were created",
        "output_dir": str(output_dir),
        "writes_files": True,
        "writes_live_config": False,
        "executes_commands": False,
        "captured": False,
        "restored": False,
        "verified": False,
        "files": files,
        "check": {
            "schema": check.get("schema"),
            "ok": bool(check.get("ok")),
            "summary": check.get("summary") if isinstance(check.get("summary"), dict) else {},
            "errors": as_list(check.get("errors")),
            "warnings": as_list(check.get("warnings")),
        },
        "privacy": {
            "secrets_included": False,
            "captured_data_included": False,
            "secret_values_checked": False,
            "note": "Backup set init writes only manifest and backup-plan review files; it does not copy live config, databases, command output, or secrets.",
        },
    }


def print_backup_set_markdown(report: dict[str, Any]) -> None:
    instance = report.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or "instance"
    print(f"# Backup Set - {name}")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- source schema: `{report.get('source_schema')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- executes commands: {report.get('executes_commands')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print(f"- backup root: `{report.get('backup_root')}`")
    print()
    print("## Summary")
    print()
    for key, value in (report.get("summary") if isinstance(report.get("summary"), dict) else {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Required Files")
    print()
    for item in as_list(report.get("required_files")):
        print(f"- {item}")
    print()
    print("## Items")
    print()
    print("| Order | Artifact | Batch | Method | Target | Expected Capture |")
    print("| --- | --- | --- | --- | --- | --- |")
    for item in as_list(report.get("items")):
        if not isinstance(item, dict):
            continue
        print(
            f"| {item.get('order', '')} | {item.get('artifact_id', '')} | {item.get('batch_id', '')} | "
            f"{item.get('method', '')} | {item.get('target', '')} | `{item.get('expected_capture_path', '')}` |"
        )
    print()
    if report.get("forbidden_locations"):
        print("## Forbidden Locations")
        print()
        for item in as_list(report.get("forbidden_locations")):
            print(f"- {item}")
        print()
    init = report.get("init") if isinstance(report.get("init"), dict) else {}
    if init:
        print("## Init")
        print()
        print(f"- schema: `{init.get('schema')}`")
        print(f"- status: {init.get('status')}")
        print(f"- ok: {init.get('ok')}")
        print(f"- output dir: `{init.get('output_dir')}`")
        print(f"- writes files: {init.get('writes_files')}")
        print(f"- writes live config: {init.get('writes_live_config')}")
        print(f"- executes commands: {init.get('executes_commands')}")
        print(f"- reason: {init.get('reason')}")
        print()
        if init.get("files"):
            print("| File | Bytes |")
            print("| --- | --- |")
            for item in as_list(init.get("files")):
                if isinstance(item, dict):
                    print(f"| `{item.get('name', '')}` | {item.get('bytes', 0)} |")
            print()
        check = init.get("check") if isinstance(init.get("check"), dict) else {}
        if check:
            print("### Init Check")
            print()
            print(f"- schema: `{check.get('schema')}`")
            print(f"- ok: {check.get('ok')}")
            summary = check.get("summary") if isinstance(check.get("summary"), dict) else {}
            for key, value in summary.items():
                print(f"- {key}: {value}")
            print()


BACKUP_SET_FORBIDDEN_KEY_PARTS = [
    "password",
    "passwd",
    "token",
    "private_key",
    "cookie",
    "authorization",
    "bearer",
    "subscription_url",
    "proxy_url",
    "api_key",
    "api_token",
    "secret_value",
]


def build_backup_set_check(path: Path | None) -> dict[str, Any]:
    errors: list[dict[str, str]] = []
    warnings: list[dict[str, str]] = []
    manifest: dict[str, Any] = {}

    def add_error(error_id: str, field_path: str, detail: str) -> None:
        errors.append({
            "id": error_id,
            "path": field_path,
            "detail": f"{field_path}: {detail}",
        })

    def add_warning(warning_id: str, field_path: str, detail: str) -> None:
        warnings.append({
            "id": warning_id,
            "path": field_path,
            "detail": f"{field_path}: {detail}",
        })

    def scan_for_forbidden_keys(value: Any, field_path: str) -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                key_text = str(key)
                key_lower = key_text.lower().replace("-", "_")
                for forbidden in BACKUP_SET_FORBIDDEN_KEY_PARTS:
                    if forbidden in key_lower:
                        add_error("backup-set-forbidden-key", f"{field_path}.{key_text}", "forbidden secret-like key name")
                        break
                scan_for_forbidden_keys(child, f"{field_path}.{key_text}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                scan_for_forbidden_keys(child, f"{field_path}[{index}]")

    if path is None:
        add_error("backup-set-missing-path", "$", "pass --file with a homenet.backup_set_manifest.v1 manifest")
    elif not path.exists():
        add_error("backup-set-file-missing", str(path), "file does not exist")
    elif not path.is_file():
        add_error("backup-set-not-file", str(path), "path is not a regular file")
    else:
        try:
            parsed = json.loads(path.read_text(encoding="utf-8"))
        except Exception as exc:  # noqa: BLE001 - operator-facing validation
            parsed = None
            add_error("backup-set-unreadable", str(path), str(exc))
        if isinstance(parsed, dict):
            manifest = parsed
            scan_for_forbidden_keys(manifest, "$")
        elif parsed is not None:
            add_error("backup-set-invalid", "$", "top-level JSON value must be an object")

    schema = str(manifest.get("schema") or "")
    items = manifest.get("items") if isinstance(manifest.get("items"), list) else []
    checked_items = 0
    captured_true = 0
    verified_true = 0
    restored_true = 0
    missing_captures = 0
    capture_paths: list[str] = []
    manifest_dir = path.parent if path is not None else Path(".")
    backup_root_value = str(manifest.get("backup_root") or "")
    backup_root_path: Path | None = None

    if manifest:
        if schema != "homenet.backup_set_manifest.v1":
            add_error("backup-set-schema", "$.schema", "expected homenet.backup_set_manifest.v1")
        for key in ["created_at", "operator", "source_backup_plan_schema", "backup_root"]:
            if key not in manifest:
                add_error("backup-set-required-field", f"$.{key}", "missing required field")
            elif not isinstance(manifest.get(key), str):
                add_error("backup-set-field-type", f"$.{key}", "expected a string")
        if "items" not in manifest:
            add_error("backup-set-required-field", "$.items", "missing required field")
        elif not isinstance(manifest.get("items"), list):
            add_error("backup-set-field-type", "$.items", "expected a list")

        if not backup_root_value or backup_root_value == "${BACKUP_DIR}":
            add_warning("backup-set-root-placeholder", "$.backup_root", "operator backup root has not been filled")
        else:
            backup_root_path = Path(backup_root_value).expanduser()
            if not backup_root_path.is_absolute():
                add_error("backup-set-root-relative", "$.backup_root", "backup root must be an absolute path")
            else:
                try:
                    resolved_root = backup_root_path.resolve(strict=False)
                    resolved_repo = ROOT.resolve(strict=False)
                    if resolved_root == resolved_repo or resolved_repo in resolved_root.parents:
                        add_error("backup-set-root-in-git", "$.backup_root", "backup root must stay outside the HomeNet git worktree")
                except Exception as exc:  # noqa: BLE001 - path validation should stay operator-facing
                    add_warning("backup-set-root-unresolved", "$.backup_root", str(exc))

    for index, item in enumerate(items):
        row_path = f"$.items[{index}]"
        if not isinstance(item, dict):
            add_error("backup-set-item-type", row_path, "expected an object")
            continue
        checked_items += 1
        for key in ["artifact_id", "batch_id", "method", "capture_path"]:
            if key not in item:
                add_error("backup-set-item-required-field", f"{row_path}.{key}", "missing required field")
            elif not isinstance(item.get(key), str):
                add_error("backup-set-item-field-type", f"{row_path}.{key}", "expected a string")
        for key in ["captured", "verified", "restored"]:
            if key not in item:
                add_error("backup-set-item-required-field", f"{row_path}.{key}", "missing required field")
            elif not isinstance(item.get(key), bool):
                add_error("backup-set-item-field-type", f"{row_path}.{key}", "expected a boolean")
        if item.get("captured") is True:
            captured_true += 1
        if item.get("verified") is True:
            verified_true += 1
        if item.get("restored") is True:
            restored_true += 1
        capture_path = str(item.get("capture_path") or "")
        if capture_path:
            capture_paths.append(capture_path)
            capture = Path(capture_path)
            if capture.is_absolute():
                add_error("backup-set-capture-absolute", f"{row_path}.capture_path", "capture_path must be relative to backup_root")
            if ".." in capture.parts:
                add_error("backup-set-capture-traversal", f"{row_path}.capture_path", "capture_path must not contain '..'")
            if any(part in {".git", ".ssh", ".config"} for part in capture.parts):
                add_error("backup-set-capture-private-path", f"{row_path}.capture_path", "capture_path must not target private control directories")
            if item.get("captured") is True:
                if backup_root_path is not None and backup_root_path.is_absolute():
                    candidate = backup_root_path / capture_path
                else:
                    candidate = manifest_dir / capture_path
                try:
                    if not candidate.exists():
                        missing_captures += 1
                        add_warning("backup-set-capture-missing", f"{row_path}.capture_path", "captured=true but referenced capture file is not present")
                except OSError as exc:
                    add_warning("backup-set-capture-stat", f"{row_path}.capture_path", str(exc))
        if item.get("verified") is True and item.get("captured") is not True:
            add_error("backup-set-verify-without-capture", f"{row_path}.verified", "verified=true requires captured=true")
        if item.get("restored") is True and item.get("captured") is not True:
            add_error("backup-set-restore-without-capture", f"{row_path}.restored", "restored=true requires captured=true")

    duplicates = sorted({value for value in capture_paths if capture_paths.count(value) > 1})
    for duplicate in duplicates:
        add_warning("backup-set-duplicate-capture", "$.items", f"duplicate capture_path {duplicate}")

    return {
        "schema": "homenet.backup_set_check.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "executes_commands": False,
        "prints_values": False,
        "path": str(path) if path is not None else "",
        "ok": bool(manifest) and not errors,
        "summary": {
            "loaded": bool(manifest),
            "source_schema": schema,
            "items": checked_items,
            "captured_true": captured_true,
            "verified_true": verified_true,
            "restored_true": restored_true,
            "missing_capture_warnings": missing_captures,
            "errors": len(errors),
            "warnings": len(warnings),
        },
        "manifest": {
            "schema": schema,
            "backup_root_set": bool(backup_root_value and backup_root_value != "${BACKUP_DIR}"),
            "source_backup_plan_schema": manifest.get("source_backup_plan_schema") if isinstance(manifest.get("source_backup_plan_schema"), str) else "",
            "item_count": checked_items,
        },
        "errors": errors,
        "warnings": warnings,
        "forbidden_key_parts": BACKUP_SET_FORBIDDEN_KEY_PARTS,
        "privacy": {
            "secrets_included": False,
            "captured_data_included": False,
            "secret_values_checked": False,
            "note": "Backup set check validates manifest structure and file references only; it does not read captured backup contents.",
        },
    }


def print_backup_set_check_markdown(report: dict[str, Any]) -> None:
    print("# Backup Set Check")
    print()
    print(f"- schema: `{report.get('schema')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- executes commands: {report.get('executes_commands')}")
    print(f"- writes files: {report.get('writes_files')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print(f"- prints values: {report.get('prints_values')}")
    print(f"- ok: {report.get('ok')}")
    if report.get("path"):
        print(f"- path: `{report.get('path')}`")
    print()
    print("## Summary")
    print()
    for key, value in (report.get("summary") if isinstance(report.get("summary"), dict) else {}).items():
        print(f"- {key}: {value}")
    print()
    manifest = report.get("manifest") if isinstance(report.get("manifest"), dict) else {}
    print("## Manifest")
    print()
    print(f"- schema: `{manifest.get('schema')}`")
    print(f"- backup root set: {manifest.get('backup_root_set')}")
    print(f"- source backup plan schema: `{manifest.get('source_backup_plan_schema')}`")
    print(f"- items: {manifest.get('item_count', 0)}")
    print()
    if report.get("errors"):
        print("## Errors")
        print()
        print("| ID | Path | Detail |")
        print("| --- | --- | --- |")
        for item in as_list(report.get("errors")):
            if isinstance(item, dict):
                print(f"| {item.get('id', '')} | `{item.get('path', '')}` | {item.get('detail', '')} |")
        print()
    if report.get("warnings"):
        print("## Warnings")
        print()
        print("| ID | Path | Detail |")
        print("| --- | --- | --- |")
        for item in as_list(report.get("warnings")):
            if isinstance(item, dict):
                print(f"| {item.get('id', '')} | `{item.get('path', '')}` | {item.get('detail', '')} |")
        print()


def print_executor_plan_markdown(plan: dict[str, Any]) -> None:
    instance = plan.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or "instance"
    print(f"# Executor Plan - {name}")
    print()
    print(f"- schema: `{plan.get('schema')}`")
    print(f"- read only: {plan.get('read_only')}")
    print(f"- executes commands: {plan.get('executes_commands')}")
    print(f"- writes live config: {plan.get('writes_live_config')}")
    print(f"- write enabled: {plan.get('write_enabled')}")
    print()
    batch_selection = plan.get("batch_selection", {})
    if isinstance(batch_selection, dict):
        print("## Batch Selection")
        print()
        print(f"- scope: {batch_selection.get('scope')}")
        print(f"- requested: {', '.join(str(item) for item in as_list(batch_selection.get('requested'))) or 'all'}")
        print(f"- selected: {', '.join(str(item) for item in as_list(batch_selection.get('selected'))) or 'none'}")
        print(f"- unknown: {', '.join(str(item) for item in as_list(batch_selection.get('unknown'))) or 'none'}")
        print()
    print("## Summary")
    print()
    for key, value in (plan.get("summary") or {}).items():
        print(f"- {key}: {value}")
    print()
    if plan.get("hard_blockers"):
        print("## Hard Blockers")
        print()
        for item in as_list(plan.get("hard_blockers")):
            print(f"- {item}")
        print()
    print("## Stages")
    print()
    print("| Order | Batch | Status | Artifacts | Backups | Writers | Blocked Gates |")
    print("| --- | --- | --- | --- | --- | --- | --- |")
    for stage in as_list(plan.get("stages")):
        if not isinstance(stage, dict):
            continue
        writers = ", ".join(str(item) for item in as_list(stage.get("writers")))
        blocked = ", ".join(str(item) for item in as_list(stage.get("blocked_gates")))
        print(
            f"| {stage.get('order', '')} | {stage.get('batch_id', '')} | {stage.get('status', '')} | "
            f"{stage.get('artifact_count', 0)} | {len(as_list(stage.get('backup_items')))} | {writers} | {blocked} |"
        )
    print()
    print("## Runner Contract")
    print()
    contract = plan.get("runner_contract", {}) if isinstance(plan.get("runner_contract"), dict) else {}
    print(f"- current status: {contract.get('current_status')}")
    print("- allowed now:")
    for item in as_list(contract.get("allowed_now")):
        print(f"  - {item}")
    print("- forbidden now:")
    for item in as_list(contract.get("forbidden_now")):
        print(f"  - {item}")
    print("- promotion required:")
    for item in as_list(contract.get("promotion_required")):
        print(f"  - {item}")
    print()


def print_apply_result_markdown(result: dict[str, Any]) -> None:
    instance = result.get("instance", {})
    name = instance.get("display_name") or instance.get("name") or "instance"
    print(f"# Apply Result - {name}")
