    print(f"- schema: `{report.get('schema')}`")
    print(f"- profile: `{report.get('profile')}`")
    print(f"- read only: {report.get('read_only')}")
    print(f"- executes live checks: {report.get('executes_live_checks')}")
    print(f"- writes live config: {report.get('writes_live_config')}")
    print()
    print("## Summary")
    print()
    for key, value in report.get("summary", {}).items():
        print(f"- {key}: {value}")
    print()
    print("## Status Counts")
    print()
    for key, value in report.get("status_counts", {}).items():
        print(f"- {key}: {value}")
