def build_change_pack(
    state: dict[str, Any],
    instance: Path,
    gate_evidence: dict[str, Any] | None = None,
    *,
    evidence_path: Path | None = None,
    evidence_warnings: list[dict[str, str]] | None = None,
    selected_batches: list[str] | None = None,
) -> dict[str, Any]:
    apply_plan = build_apply_plan(state, instance, gate_evidence=gate_evidence)
    attach_gate_evidence_to_apply_plan(apply_plan, evidence_path, evidence_warnings or [])
    gates = build_gates_report(state, instance, gate_evidence=gate_evidence)
    executor_plan = build_executor_plan(apply_plan, selected_batches=selected_batches)
    backup_plan = build_backup_execution_plan(apply_plan, selected_batches=selected_batches)
    backup_set = build_backup_set_report(backup_plan)
    write_enablement = build_write_enablement_report(apply_plan)
    live_proof = build_live_proof_report(build_evidence_plan(state, instance))
    selected = executor_plan.get("batch_selection") if isinstance(executor_plan.get("batch_selection"), dict) else {}
    readiness = apply_plan.get("apply_readiness") if isinstance(apply_plan.get("apply_readiness"), dict) else {}
    readiness_by_id = {
        str(row.get("batch_id") or ""): row
        for row in as_list(readiness.get("batch_readiness"))
        if isinstance(row, dict)
    }
    backup_counts_by_batch: dict[str, int] = {}
    for item in as_list(backup_plan.get("items")):
        if isinstance(item, dict):
            batch_id = str(item.get("batch_id") or "")
            backup_counts_by_batch[batch_id] = backup_counts_by_batch.get(batch_id, 0) + 1
    batch_rows = []
    for batch in as_list(executor_plan.get("stages")):
        if not isinstance(batch, dict):
            continue
        batch_id = str(batch.get("batch_id") or batch.get("id") or "")
        ready = readiness_by_id.get(batch_id, {})
        batch_rows.append({
            "id": batch_id,
            "title": batch.get("title") or "",
            "status": batch.get("status") or ready.get("status") or "unknown",
            "artifact_count": batch.get("artifact_count", 0),
            "backup_items": backup_counts_by_batch.get(batch_id, 0),
            "writers": as_list(batch.get("writers")),
            "blocked_gates": as_list(batch.get("blocked_gates")) or as_list(ready.get("blocked_gates")),
            "pre_checks": [
                str(item.get("command") or "")
                for item in as_list(batch.get("pre_checks"))
                if isinstance(item, dict) and item.get("command")
            ],
            "post_checks": [
                str(item.get("command") or "")
                for item in as_list(batch.get("post_checks"))
                if isinstance(item, dict) and item.get("command")
            ],
            "failure_action": batch.get("failure_action") or "",
            "eligible_for_write": False,
        })
    required_records = [
        {
            "id": "gate-evidence",
            "schema": "homenet.gate_evidence.v1",
            "purpose": "Boolean/timestamp proof that required safety gates were reviewed.",
            "secret_values_allowed": False,
            "source_command": "./homenet gates --template",
        },
        {
            "id": "pre-apply-live-proof",
            "schema": live_proof.get("schema"),
            "purpose": "Saved summary proving the declared home state before any source-tool write.",
            "secret_values_allowed": False,
            "source_command": "./homenet live-proof --instance <instance> --format json",
        },
        {
            "id": "backup-set-manifest",
            "schema": "homenet.backup_set_manifest.v1",
            "purpose": "Operator-owned manifest tying capture files to artifact ids and batch ids.",
            "secret_values_allowed": False,
            "source_command": "./homenet backup-set --instance <instance> --format json",
        },
        {
            "id": "executor-plan",
            "schema": executor_plan.get("schema"),
            "purpose": "Read-only future runner stages, checks, backup items, and hard blockers.",
            "secret_values_allowed": False,
            "source_command": "./homenet exec-plan --instance <instance> --format json",
        },
        {
            "id": "post-apply-live-proof",
            "schema": live_proof.get("schema"),
            "purpose": "Saved post-change regression proof; required only after a future guarded write actually runs.",
            "secret_values_allowed": False,
            "source_command": "./homenet verify --live --instance <instance>",
        },
    ]
    missing_proof = []
    for gate in as_list(gates.get("gates")):
        if not isinstance(gate, dict):
            continue
        if gate.get("required") and str(gate.get("status") or "") in {"blocked", "missing", "fail", "planned"}:
            missing_proof.append({
                "gate": gate.get("id") or "",
                "status": gate.get("status") or "",
                "type": gate.get("type") or "",
                "detail": gate.get("detail") or "",
            })
    return {
        "schema": "homenet.change_pack.v1",
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "executes_commands": False,
        "instance": apply_plan.get("instance") or {},
        "instance_path": apply_plan.get("instance_path") or str(instance),
        "profile": apply_plan.get("profile"),
        "summary": {
            "selected_batches": len(as_list(selected.get("selected"))) if selected else len(batch_rows),
            "unknown_batches": len(as_list(selected.get("unknown"))) if selected else 0,
            "batches": len(batch_rows),
            "required_records": len(required_records),
            "missing_proof_items": len(missing_proof),
            "backup_items": backup_plan.get("summary", {}).get("backup_items", len(as_list(backup_plan.get("items")))),
            "writers": write_enablement.get("summary", {}).get("writers", 0),
            "write_side_apply_implemented": bool(apply_plan.get("write_side_apply_implemented")),
            "gate_evidence_applied": bool(gate_evidence),
        },
        "batch_selection": selected,
        "batches": batch_rows,
        "required_records": required_records,
        "missing_proof": missing_proof,
        "writer_proof": as_list(write_enablement.get("writers")),
        "backup_set": {
            "schema": backup_set.get("schema"),
            "backup_root": backup_set.get("backup_root"),
            "required_files": as_list(backup_set.get("required_files")),
            "forbidden_locations": as_list(backup_set.get("forbidden_locations")),
            "manifest_template": backup_set.get("manifest_template") if isinstance(backup_set.get("manifest_template"), dict) else {},
        },
        "safety_boundary": [
            "This change pack is a review and evidence contract only.",
            "It does not create backup directories, copy files, SSH to devices, call providers, restart services, or write live config.",
            "Real changes must still happen through the declared source tools until guarded writers are implemented and proven.",
        ],
        "evidence_input": gates.get("evidence_input") if isinstance(gates.get("evidence_input"), dict) else {},
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "live_state_read": False,
            "note": "Change pack aggregates schemas, gate status, batch ids, writer proof requirements, and manifest templates only; it must not contain secret values or command output.",
        },
    }


