def build_pre_change_proof_contract(state: dict[str, Any], instance: Path) -> dict[str, Any]:
    apply_plan = build_apply_plan(state, instance)
    executor_plan = build_executor_plan(apply_plan)
    backup_plan = build_backup_execution_plan(apply_plan)
    change_pack = build_change_pack(state, instance)
    instance_info = apply_plan.get("instance") if isinstance(apply_plan.get("instance"), dict) else {}
    return {
        "schema": "homenet.pre_change_proof_contract.v1",
        "instance": instance_info,
        "instance_path": str(instance),
        "profile": apply_plan.get("profile"),
        "read_only": True,
        "writes_files": False,
        "writes_live_config": False,
        "executes_commands": False,
        "requires_operator_records": True,
        "summary": {
            "required_inputs": 2,
            "optional_inputs": 1,
            "generated_directories": 2,
            "generated_records": 5,
            "backup_items": backup_plan.get("summary", {}).get("backup_items", len(as_list(backup_plan.get("items")))),
            "executor_stages": len(as_list(executor_plan.get("stages"))),
            "change_pack_records": change_pack.get("summary", {}).get("required_records", 0),
        },
        "command": {
            "example": "./homenet pre-change-proof --instance <instance> --dir <outside-git-dir> --gate-evidence <gate-evidence.json> --pre-apply-live <verify-live.json> --batch <batch-id>",
            "requires_dir_outside_git": True,
            "refuses_non_empty_without_force": True,
            "force_overwrites_generated_files": True,
        },
        "required_inputs": [
            {
                "id": "gate-evidence",
                "file": "gate-evidence.json",
                "schema": "homenet.gate_evidence.v1",
                "source_command": "./homenet gates --template",
                "validation": "homenet evidence-check --file <gate-evidence.json>",
                "secret_values_allowed": False,
            },
            {
                "id": "pre-apply-live",
                "file": "pre-apply-live.json",
                "schema": "homenet.verify.v1 or homenet.ci.v1 with live=true",
                "source_command": "./homenet verify --instance <instance> --live --json",
                "validation": "homenet live-result-check --file <verify-live.json>",
                "secret_values_allowed": False,
            },
        ],
        "optional_inputs": [
            {
                "id": "post-apply-live",
                "file": "post-apply-live.json",
                "schema": "homenet.verify.v1 or homenet.ci.v1 with live=true",
                "when": "Only after a future guarded write actually runs.",
                "validation": "homenet live-result-check --file <post-live.json>",
                "secret_values_allowed": False,
            }
        ],
        "generated_outputs": [
            {
                "path": "config-review/",
                "schema": "homenet.reviewable_apply_manifest.v1",
                "purpose": "Local generated config review artifacts for human/source-tool review.",
                "writes_live_config": False,
            },
            {
                "path": "backup-set/",
                "schema": "homenet.backup_set_manifest.v1",
                "purpose": "Backup-set skeleton and backup plan without captures.",
                "writes_live_config": False,
            },
            {
                "path": "executor-plan.json",
                "schema": executor_plan.get("schema"),
                "purpose": "Read-only future runner stages and checks.",
                "writes_live_config": False,
            },
            {
                "path": "change-pack.json",
                "schema": change_pack.get("schema"),
                "purpose": "Pre-change gate, writer proof, and backup-set packet.",
                "writes_live_config": False,
            },
            {
                "path": "manifest.json",
                "schema": "homenet.pre_change_proof_manifest.v1",
                "purpose": "Index of generated proof files and validation summaries.",
                "writes_live_config": False,
            },
        ],
        "final_checks": [
            "homenet evidence-check",
            "homenet live-result-check",
            "homenet review-output-check",
            "homenet backup-set-check",
            "homenet change-record-check",
        ],
        "forbidden_actions": [
            "run live probes while assembling the proof directory",
            "create backup captures or copy live configuration files",
            "read backup capture contents",
            "SSH to OpenWrt, Room AP, Pi, Studio, MBP, or other devices",
            "call Cloudflare, Kuma, Docker, systemd, or service-native write APIs",
            "restart services or mutate live network configuration",
        ],
        "privacy": {
            "secrets_included": False,
            "captured_data_included": False,
            "secret_values_checked": False,
            "note": "This contract lists required proof records and generated file names only; it does not contain proof values, captures, command output, or secrets.",
        },
    }


