def config_fragment_filename(fragment: dict[str, Any]) -> str:
    fragment_id = str(fragment.get("id") or "fragment")
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "-", fragment_id).strip("-") or "fragment"
    kind = str(fragment.get("kind") or "")
    path_hint = str(fragment.get("path_hint") or "")
    if kind == "command-plan":
        suffix = ".review.txt"
    elif path_hint.endswith(".conf"):
        suffix = ".review.conf"
    else:
        suffix = ".review.yaml"
    return f"{safe}{suffix}"


def write_config_plan_review_files(plan: dict[str, Any], output_dir: Path, *, force: bool = False) -> dict[str, Any]:
    existing = output_dir.exists() and any(output_dir.iterdir())
    if existing and not force:
        return {
            "ok": False,
            "error": f"{output_dir} is not empty. Use --force to overwrite generated review files.",
            "output_dir": str(output_dir),
            "files": [],
        }

    output_dir.mkdir(parents=True, exist_ok=True)
    files: list[dict[str, Any]] = []
    for fragment in plan.get("fragments", []):
        if not isinstance(fragment, dict):
            continue
        filename = config_fragment_filename(fragment)
        target = output_dir / filename
        content = str(fragment.get("content") or "").rstrip() + "\n"
        target.write_text(content, encoding="utf-8")
        files.append({
            "path": filename,
            "fragment_id": fragment.get("id"),
            "artifact_id": fragment.get("artifact_id"),
            "module_id": fragment.get("module_id"),
            "kind": fragment.get("kind"),
            "status": fragment.get("status"),
            "deployable": False,
        })

    manifest = {
        "schema": "homenet.generated_config_review.v1",
        "source_schema": plan.get("schema"),
        "instance": plan.get("instance") or {},
        "profile": plan.get("profile"),
        "read_only": False,
        "dry_run": True,
        "writes_files": True,
        "writes_live_config": False,
        "output_dir": str(output_dir),
        "file_count": len(files) + 1,
        "files": [item.get("path") for item in files] + ["manifest.json"],
        "fragments": files,
        "safety": [
            "These files are review artifacts only.",
            "They are written to the explicit output directory, not to service runtime paths.",
            "Do not copy them into OpenWrt, Docker, systemd, AdGuard, Mihomo, Kuma, or Cloudflare without module-specific apply gates.",
        ],
        "privacy": {
            "secrets_included": False,
            "secret_values_checked": False,
            "note": "Generated review files contain placeholders and comments only; secret values are not read or written.",
        },
    }
    (output_dir / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return {
        "ok": True,
        "output_dir": str(output_dir),
        "file_count": len(files) + 1,
        "files": manifest["files"],
        "manifest": "manifest.json",
        "force": force,
        "extra_files_preserved": existing and force,
    }


def build_bundle_payloads(instance: Path, state: dict[str, Any], *, include_ci: bool = True) -> dict[str, str]:
    plan = build_plan(state, instance)
    metadata = build_metadata(state, instance)
    artifacts = build_artifact_manifest(metadata)
    ownership = build_ownership_map(metadata, artifacts, instance)
    runbook = build_runbook(state, instance)
    topology = build_topology(state, instance)
    doctor = build_doctor(state, instance, live=False)
    incident = build_incident_report(state, instance, live=False)
    blueprint = build_blueprint(metadata, artifacts)
    profiles = build_profiles_export()
    quickstart = build_quickstart_guide(str(plan.get("profile") or "openwrt-pi"), instance=instance, instance_state=state)
    module_definitions = build_module_definitions_report()
    module_artifacts = build_module_artifacts_report()
    module_renderers = build_module_renderers_report()
    module_implementations = build_module_implementations_report()
    module_executors = build_module_executors_report()
    module_backups = build_module_backups_report()
    modules_catalog = build_modules_catalog(state, instance)
    module_registry = build_module_registry(state, instance)
    secrets = build_secrets_contract(state, instance)
    inputs = build_inputs_checklist(state, instance)
    worksheet = build_deployment_worksheet(state, instance)
    preflight = build_preflight(state, instance)
    readiness = build_readiness(state, instance)
    rollback = build_rollback_contract(state, instance)
    evidence = build_evidence_plan(state, instance)
    live_proof = build_live_proof_report(evidence)
    apply_plan = build_apply_plan(state, instance)
    write_enablement = build_write_enablement_report(apply_plan)
    executor_plan = build_executor_plan(apply_plan)
    backup_execution_plan = build_backup_execution_plan(apply_plan)
    backup_set = build_backup_set_report(backup_execution_plan)
    backup_set_check = build_backup_set_check(None)
    gates = build_gates_report(state, instance)
    change_pack = build_change_pack(state, instance)
    pre_change_proof = build_pre_change_proof_contract(state, instance)
    change_record_check = build_change_record_check(None)
    evidence_check = build_gate_evidence_check(None)
    review_output_check = build_review_output_check(None)
    live_result_check = build_live_result_check(None)
    deploy_plan = build_deploy_plan(state, instance)
    bootstrap = build_bootstrap_plan(state, instance)
    render_preview = build_render_preview(state, instance)
    rescue = build_rescue_guide(metadata, instance)
    scripts = build_scripts_inventory(metadata, instance)
    config_plan = build_config_plan(metadata, instance)
    privacy = build_privacy_report(instance, scope="all")
    release = build_release_manifest(instance)
    public_package = build_public_package_manifest(instance)
    version = build_version_report(instance)
    workspace = build_workspace_report(instance)
    progress = build_progress_report(state, instance)
    status = build_status_dashboard(state, instance, live=False)
    kuma = build_kuma_export(metadata)
