def command_generate(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("Config generation requires --dry-run. Use --output-dir with --dry-run to write review files only.", file=sys.stderr)
        return 2
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2

    metadata = build_metadata(state, instance)
    plan = build_config_plan(metadata, instance)
    if args.output_dir:
        result = write_config_plan_review_files(plan, Path(args.output_dir).resolve(), force=bool(args.force))
        if not result.get("ok"):
            print(result.get("error") or "failed to write config review files", file=sys.stderr)
            return 2
        plan = {
            **plan,
            "writes_files": True,
            "render_output": result,
            "operator_rules": [
                *as_list(plan.get("operator_rules")),
                "Output files are review artifacts only and are written only to the explicit output directory.",
            ],
        }
    if args.format == "json":
        print(json.dumps(plan, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        print_config_plan_markdown(plan)
        if args.output_dir:
            output = plan.get("render_output", {})
            print("## Output Directory")
            print()
            print(f"- path: `{output.get('output_dir')}`")
            print(f"- files: {output.get('file_count')}")
            print(f"- writes live config: False")
            print()
    return 0


