def command_bundle(args: argparse.Namespace) -> int:
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2

    output = Path(args.output).resolve()
    if output.exists() and any(output.iterdir()) and not args.force:
        print(f"{output} is not empty. Use --force to overwrite known bundle files.", file=sys.stderr)
        return 2
    output.mkdir(parents=True, exist_ok=True)

    files = build_bundle_payloads(instance, state)
    for name, content in files.items():
        target = output / name
        target.write_text(content, encoding="utf-8")

    print(f"Wrote HomeNet bundle to {output}")
    print(f"- files: {len(files)}")
    print("- read only: true")
    print("- live: false")
    return 0


