def command_kuma(args: argparse.Namespace) -> int:
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2

    metadata = build_metadata(state, instance)
    export = build_kuma_export(metadata)
    if args.diff_db:
        if args.apply_db and not args.import_plan:
            print("--apply-db requires --import-plan", file=sys.stderr)
            return 2
        diff = build_kuma_diff(export, Path(args.diff_db).resolve())
        if args.import_plan:
            plan = build_kuma_import_plan(diff)
            if args.apply_db:
                result = apply_kuma_import_plan(
                    plan,
                    confirm=str(args.confirm_apply or ""),
                    include_interval_updates=bool(args.include_interval_updates),
                    include_review_updates=bool(args.include_review_updates),
                )
                if args.format == "markdown":
                    print_kuma_apply_result_markdown(result)
                else:
                    print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
                return 1 if result.get("error") else 0
            if args.format == "markdown":
                print_kuma_import_plan_markdown(plan)
            else:
                print(json.dumps(plan, ensure_ascii=False, indent=2, sort_keys=True))
            return 0
        if args.format == "markdown":
            print_kuma_diff_markdown(diff)
        else:
            print(json.dumps(diff, ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    if args.import_plan:
        print("--import-plan requires --diff-db", file=sys.stderr)
        return 2
    if args.apply_db:
        print("--apply-db requires --diff-db and --import-plan", file=sys.stderr)
        return 2
    if args.format == "markdown":
        print_kuma_markdown(export)
    else:
        print(json.dumps(export, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


