def command_apply(args: argparse.Namespace) -> int:
    if args.template:
        print(json.dumps(gate_evidence_template(), ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    if not instance.exists():
        reporter.fail("instance", f"{instance} does not exist")
        reporter.print()
        return 2
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2
    gate_evidence, evidence_path, evidence_warnings, change_record = load_gate_evidence_input(
        evidence_file=args.evidence_file,
        change_record_dir=args.change_record_dir,
    )
    apply_plan = build_apply_plan(state, instance, gate_evidence=gate_evidence)
    attach_gate_evidence_to_apply_plan(apply_plan, evidence_path, evidence_warnings)
    attach_change_record_to_report(apply_plan, change_record)
    if not args.dry_run:
        if args.review_output_dir:
            result = build_review_only_apply_result(
                state,
                instance,
                apply_plan,
                confirm_apply=str(args.confirm_apply or ""),
                selected_batches=as_list(args.batch),
                output_dir=Path(args.review_output_dir).resolve(),
                force=bool(args.force),
            )
            return_code = 0 if result.get("status") == "review-applied" else 2
        else:
            result = build_apply_result(
                apply_plan,
                dry_run=False,
                confirm_apply=str(args.confirm_apply or ""),
                selected_batches=as_list(args.batch),
            )
            return_code = 2
        if args.format == "markdown":
            print_apply_result_markdown(result)
        else:
            print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return return_code
    if args.format == "markdown":
        print_apply_plan_markdown(apply_plan)
    else:
        print(json.dumps(apply_plan, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


