def command_backup_plan(args: argparse.Namespace) -> int:
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    if not instance.exists():
        reporter.fail("instance", f"{instance} does not exist")
        reporter.print()
        return 2
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2
    gate_evidence, evidence_path, evidence_warnings, change_record = load_gate_evidence_input(
        evidence_file=args.evidence_file,
        change_record_dir=args.change_record_dir,
    )
    apply_plan = build_apply_plan(state, instance, gate_evidence=gate_evidence)
    attach_gate_evidence_to_apply_plan(apply_plan, evidence_path, evidence_warnings)
    attach_change_record_to_report(apply_plan, change_record)
    backup_plan = build_backup_execution_plan(
        apply_plan,
        selected_batches=as_list(args.batch),
    )
    attach_change_record_to_report(backup_plan, change_record)
    requested_backup_actions = [item for item in [args.capture, args.restore, args.verify_backup] if item]
    if len(requested_backup_actions) > 1:
        print("--capture, --restore, and --verify cannot be used together", file=sys.stderr)
        return 2
    if args.capture or args.restore or args.verify_backup:
        result = build_backup_result(
            backup_plan,
            capture=bool(args.capture),
            restore=bool(args.restore),
            verify=bool(args.verify_backup),
            confirm_capture=str(args.confirm_capture or ""),
            confirm_restore=str(args.confirm_restore or ""),
            confirm_verify=str(args.confirm_verify or ""),
        )
        if args.format == "markdown":
            print_backup_result_markdown(result)
        else:
            print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 2
    if args.format == "markdown":
        print_backup_execution_plan_markdown(backup_plan)
    else:
        print(json.dumps(backup_plan, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


def command_backup_set(args: argparse.Namespace) -> int:
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    if not instance.exists():
        reporter.fail("instance", f"{instance} does not exist")
        reporter.print()
        return 2
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2
    gate_evidence, evidence_path, evidence_warnings, change_record = load_gate_evidence_input(
        evidence_file=args.evidence_file,
        change_record_dir=args.change_record_dir,
    )
    apply_plan = build_apply_plan(state, instance, gate_evidence=gate_evidence)
    attach_gate_evidence_to_apply_plan(apply_plan, evidence_path, evidence_warnings)
    attach_change_record_to_report(apply_plan, change_record)
    backup_plan = build_backup_execution_plan(
        apply_plan,
        selected_batches=as_list(args.batch),
    )
    report = build_backup_set_report(backup_plan)
    attach_change_record_to_report(report, change_record)
    if evidence_path is not None:
        report["gate_evidence"] = {
            "path": str(evidence_path),
            "warnings": evidence_warnings,
        }
    if args.init_dir:
        init = initialize_backup_set_directory(report, backup_plan, Path(args.init_dir).resolve(), force=bool(args.force))
        report["init"] = init
        report["writes_files"] = bool(init.get("writes_files"))
        report["summary"]["init_ok"] = bool(init.get("ok"))
        report["summary"]["init_files"] = len(as_list(init.get("files")))
    if args.format == "markdown":
        print_backup_set_markdown(report)
    else:
        print(json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True))
    if args.init_dir:
        return 0 if report.get("init", {}).get("ok") else 2
    return 0


