def command_gates(args: argparse.Namespace) -> int:
    if args.template:
        print(json.dumps(gate_evidence_template(), ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    if not instance.exists():
        reporter.fail("instance", f"{instance} does not exist")
        reporter.print()
        return 2
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2
    gate_evidence, evidence_path, evidence_warnings, change_record = load_gate_evidence_input(
        evidence_file=args.evidence_file,
        change_record_dir=args.change_record_dir,
    )
    report = build_gates_report(state, instance, gate_evidence=gate_evidence)
    attach_change_record_to_report(report, change_record)
    if evidence_path is not None or evidence_warnings or change_record is not None:
        report.setdefault("evidence_input", {})
        if evidence_path is not None:
            report["evidence_input"]["path"] = str(evidence_path)
        if change_record is not None:
            report["evidence_input"]["source"] = "change-record"
            report["evidence_input"]["change_record_path"] = change_record.get("path")
        if evidence_warnings:
            report.setdefault("warnings", [])
            for warning in evidence_warnings:
                report["warnings"].append({
                    "source": "gate-evidence",
                    "id": warning.get("id", "gate-evidence"),
                    "detail": warning.get("detail", ""),
                })
            summary = report.setdefault("summary", {})
            summary["warnings"] = len(as_list(report.get("warnings")))
    if args.format == "markdown":
        print_gates_markdown(report)
    else:
        print(json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


