def command_package(args: argparse.Namespace) -> int:
    instance = Path(args.instance).resolve()
    manifest = build_public_package_manifest(instance)
    if not args.output_dir:
        if args.format == "json":
            print(json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True))
        else:
            print_public_package_markdown(manifest)
        return 2 if not manifest.get("package_ready") else 0

    output = Path(args.output_dir).resolve()
    report = write_public_package_output(instance, output, force=bool(args.force))
    if args.format == "json":
        print(json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if report.get("ok") else 2
    if report.get("errors"):
        for item in as_list(report.get("errors")):
            if isinstance(item, dict):
                print(f"{item.get('path')}: {item.get('detail')}", file=sys.stderr)
        return 2
    print(f"Wrote HomeNet public package to {output}")
    print(f"- copied files: {(report.get('summary') or {}).get('copied_files')}")
    print("- writes live config: false")
    return 0 if report.get("ok") else 2


