def command_status(args: argparse.Namespace) -> int:
    reporter = Reporter()
    instance = Path(args.instance).resolve()
    if not instance.exists():
        reporter.fail("instance", f"{instance} does not exist")
        reporter.print()
        return 2
    state = check_instance(instance, reporter)
    if reporter.failed:
        reporter.print()
        return 2
    live_reporter: Reporter | None = None
    if args.live:
        live_reporter = Reporter()
        check_live(state, instance, live_reporter)
    status = build_status_dashboard(state, instance, live=bool(args.live), live_reporter=live_reporter)
    if args.format == "json":
        print(json.dumps(status, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        print_status_markdown(status)
    live_status = status.get("live_status", {}) if isinstance(status.get("live_status"), dict) else {}
    return 2 if live_status.get("failures") else 0


