def discover_instances(include_private: bool = False) -> list[Path]:
    instances_root = ROOT / "instances"
    if not instances_root.exists():
        return []
    paths = [
        path
        for path in instances_root.iterdir()
        if path.is_dir()
        and (path / "site.yaml").exists()
        and (include_private or path.name.startswith("example-"))
    ]
    return sorted(paths, key=lambda path: path.name)


def command_examples(args: argparse.Namespace) -> int:
    instances = discover_instances(include_private=args.all)
    if not instances:
        print("No example instances found.")
        return 2

    rows: list[dict[str, Any]] = []
    failures = 0
    for instance in instances:
        reporter = Reporter()
        state = check_instance(instance, reporter)
        failed = reporter.failed
        if failed:
            failures += 1
            rows.append({
                "name": instance.name,
                "path": str(instance),
                "ok": False,
                "failures": sum(1 for finding in reporter.findings if finding.level == "FAIL"),
                "warnings": sum(1 for finding in reporter.findings if finding.level == "WARN"),
            })
            continue

        plan = build_plan(state, instance)
        metadata = build_metadata(state, instance)
        artifacts = build_artifact_manifest(metadata)
        ownership = build_ownership_map(metadata, artifacts, instance)
        runbook = build_runbook(state, instance)
        topology = build_topology(state, instance)
        doctor = build_doctor(state, instance, live=False)
        blueprint = build_blueprint(metadata, artifacts)
        secrets = build_secrets_contract(state, instance)
        preflight = build_preflight(state, instance)
        readiness = build_readiness(state, instance)
        rollback = build_rollback_contract(state, instance)
        evidence = build_evidence_plan(state, instance)
        apply_plan = build_apply_plan(state, instance)
        deploy_plan = build_deploy_plan(state, instance)
        bootstrap = build_bootstrap_plan(state, instance)
        render_preview = build_render_preview(state, instance)
        rescue = build_rescue_guide(metadata, instance)
        scripts = build_scripts_inventory(metadata, instance)
        config_plan = build_config_plan(metadata, instance)
        modules_catalog = build_modules_catalog(state, instance)
        inputs = build_inputs_checklist(state, instance)
        privacy = build_privacy_report(instance, scope="all")
        kuma = build_kuma_export(metadata)
        status = build_status_dashboard(state, instance, live=False)
        docs = render_instance_docs(metadata)
        if not privacy.get("ok"):
            failures += 1
        rows.append({
            "name": instance.name,
            "path": str(instance),
            "ok": bool(privacy.get("ok")),
            "privacy_findings": privacy.get("summary", {}).get("findings", 0),
            "profile": plan.get("profile"),
            "services": len(metadata.get("service_directory", [])),
            "ports": len(metadata.get("port_inventory", [])),
            "capabilities": len(plan.get("capability_matrix", [])),
            "module_catalog": modules_catalog.get("module_count", 0),
            "inputs_required_missing": inputs.get("summary", {}).get("required_missing", 0),
            "inputs_secrets": inputs.get("summary", {}).get("secrets", 0),
            "artifacts": artifacts.get("artifact_count", 0),
            "ownership_control_planes": ownership.get("summary", {}).get("control_planes", 0),
            "ownership_services": ownership.get("summary", {}).get("services", 0),
            "runbook_scenarios": runbook.get("summary", {}).get("scenarios", 0),
            "runbook_phases": runbook.get("summary", {}).get("phases", 0),
            "topology_nodes": topology.get("summary", {}).get("nodes", 0),
            "topology_edges": topology.get("summary", {}).get("edges", 0),
            "topology_paths": topology.get("summary", {}).get("traffic_paths", 0),
            "doctor_issues": doctor.get("summary", {}).get("issues", 0),
            "doctor_health": doctor.get("health"),
            "blueprint_questions": len(blueprint.get("operational_questions", [])),
            "secrets": secrets.get("secret_count", 0),
            "required_secrets": secrets.get("required_count", 0),
            "preflight_blockers": preflight.get("summary", {}).get("blockers", 0),
            "preflight_warnings": preflight.get("summary", {}).get("warnings", 0),
            "ready_for_review": readiness.get("ready_for_review"),
            "ready_for_apply": readiness.get("ready_for_apply"),
            "readiness_warnings": readiness.get("summary", {}).get("warnings", 0),
            "rollback_modules": rollback.get("summary", {}).get("modules", 0),
            "rollback_backup_required": rollback.get("summary", {}).get("backup_required_artifacts", 0),
            "evidence_checks": evidence.get("summary", {}).get("checks", 0),
            "evidence_groups": evidence.get("summary", {}).get("groups", 0),
            "apply_plan_artifacts": apply_plan.get("summary", {}).get("artifacts", 0),
            "apply_plan_blockers": apply_plan.get("summary", {}).get("blockers", 0),
            "deploy_steps": deploy_plan.get("summary", {}).get("steps", 0),
            "deploy_blockers": deploy_plan.get("summary", {}).get("blockers", 0),
            "bootstrap_phases": bootstrap.get("summary", {}).get("phases", 0),
            "bootstrap_blockers": bootstrap.get("summary", {}).get("blockers", 0),
            "renderable_artifacts": render_preview.get("summary", {}).get("renderable_artifacts", 0),
            "review_fragment_artifacts": render_preview.get("summary", {}).get("review_fragment_artifacts", 0),
            "rendered_review_artifacts": render_preview.get("summary", {}).get("rendered_review_artifacts", 0),
            "contract_only_artifacts": render_preview.get("summary", {}).get("contract_only_artifacts", 0),
            "rescue_entries": rescue.get("summary", {}).get("local_entries", 0),
            "rescue_modes": rescue.get("summary", {}).get("failure_modes", 0),
            "scripts": scripts.get("summary", {}).get("scripts", 0),
            "script_modules": scripts.get("summary", {}).get("modules", 0),
            "config_artifacts": config_plan.get("summary", {}).get("fragments", 0),
            "config_fragments": config_plan.get("summary", {}).get("fragments", 0),
            "docs_lines": len(docs.splitlines()),
            "kuma_monitors": kuma.get("monitor_count", 0),
            "kuma_auto": kuma.get("auto_importable_count", 0),
            "status_daily_entries": status.get("summary", {}).get("daily_entries", 0),
            "status_remote_entries": status.get("summary", {}).get("remote_entries", 0),
            "status_diagnostic_domains": status.get("summary", {}).get("diagnostic_domains", 0),
            "status_diagnostic_first_probes": status.get("summary", {}).get("diagnostic_first_probes", 0),
            "status_diagnostic_classified_findings": status.get("summary", {}).get("diagnostic_classified_findings", 0),
            "status_diagnostic_domains_with_live_findings": status.get("summary", {}).get("diagnostic_domains_with_live_findings", 0),
            "groups": kuma.get("groups", []),
        })

    if args.json:
        print(json.dumps({
            "schema": "homenet.examples.v1",
            "include_private": args.all,
            "count": len(rows),
            "ok": failures == 0,
            "instances": rows,
        }, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        print("HomeNet Example Instances")
        print()
        for row in rows:
            if not row.get("ok"):
                print(f"- {row.get('name')}: FAIL failures={row.get('failures', 0)} warnings={row.get('warnings', 0)} privacy={row.get('privacy_findings', 0)}")
                continue
            groups = ", ".join(row.get("groups", []))
            print(
                f"- {row.get('name')}: {row.get('profile')} | "
                f"services={row.get('services')} ports={row.get('ports')} "
                f"privacy={row.get('privacy_findings')} "
                f"deploy={row.get('deploy_steps')}/{row.get('deploy_blockers')} "
                f"rescue={row.get('rescue_entries')}/{row.get('rescue_modes')} "
                f"kuma={row.get('kuma_auto')}/{row.get('kuma_monitors')} | {groups}"
                f" status={row.get('status_daily_entries')}/{row.get('status_remote_entries')}"
                f" diagnostic={row.get('status_diagnostic_domains')}/{row.get('status_diagnostic_first_probes')}"
            )
        print()
        print(f"Summary: instances={len(rows)} failures={failures}")
    return 2 if failures else 0


def verify_instance(instance: Path, live: bool = False) -> dict[str, Any]:
    reporter = Reporter()
    state = check_instance(instance, reporter)
    if live and not reporter.failed:
        check_live(state, instance, reporter)

    failures = sum(1 for finding in reporter.findings if finding.level == "FAIL")
    warnings = sum(1 for finding in reporter.findings if finding.level == "WARN")
    row: dict[str, Any] = {
        "name": instance.name,
        "path": str(instance),
        "ok": failures == 0,
        "failures": failures,
        "warnings": warnings,
        "live": live,
    }
    if failures:
        row["failed_findings"] = [
            {"area": finding.area, "message": finding.message}
            for finding in reporter.findings
            if finding.level == "FAIL"
        ]
        return row

    plan = build_plan(state, instance)
    metadata = build_metadata(state, instance)
    artifacts = build_artifact_manifest(metadata)
    ownership = build_ownership_map(metadata, artifacts, instance)
    runbook = build_runbook(state, instance)
    topology = build_topology(state, instance)
    doctor = build_doctor(state, instance, live=False)
    incident = build_incident_report(state, instance, live=False)
    quickstart = build_quickstart_guide(str(build_plan(state, instance).get("profile") or "openwrt-pi"), instance=instance, instance_state=state)
    quickstart_summary = quickstart.get("operator_summary") if isinstance(quickstart.get("operator_summary"), dict) else {}
    quickstart_operator_sections = sum(
        1
        for key in ["first_deployment", "daily_use", "incident_response"]
        if isinstance(quickstart_summary.get(key), dict)
        and bool(quickstart_summary.get(key, {}).get("goal"))
        and as_list(quickstart_summary.get(key, {}).get("commands"))
    )
    if as_list(quickstart_summary.get("boundaries")):
        quickstart_operator_sections += 1
    workspace = build_workspace_report(instance)
    private_instance_review = workspace.get("private_instance_review") if isinstance(workspace.get("private_instance_review"), dict) else {}
    private_instance_review_ready = (
        bool(workspace.get("summary", {}).get("private_instance_review_ready"))
        and bool(private_instance_review.get("target_shape"))
        and len(as_list(private_instance_review.get("copy_only"))) >= 4
        and len(as_list(private_instance_review.get("validation_commands"))) >= 4
        and len(as_list(private_instance_review.get("no_live_change_rules"))) >= 3
    )
    blueprint = build_blueprint(metadata, artifacts)
    secrets = build_secrets_contract(state, instance)
    preflight = build_preflight(state, instance)
    readiness = build_readiness(state, instance)
    rollback = build_rollback_contract(state, instance)
    evidence = build_evidence_plan(state, instance)
    apply_plan = build_apply_plan(state, instance)
    gates = build_gates_report(state, instance)
    deploy_plan = build_deploy_plan(state, instance)
    bootstrap = build_bootstrap_plan(state, instance)
    render_preview = build_render_preview(state, instance)
    rescue = build_rescue_guide(metadata, instance)
    scripts = build_scripts_inventory(metadata, instance)
    config_plan = build_config_plan(metadata, instance)
    modules_catalog = build_modules_catalog(state, instance)
    inputs = build_inputs_checklist(state, instance)
    privacy = build_privacy_report(instance, scope="public")
    docs = render_instance_docs(metadata)
    kuma = build_kuma_export(metadata)
    status = build_status_dashboard(state, instance, live=False)
    if not privacy.get("ok"):
        row["ok"] = False
        row["failures"] = int(row.get("failures") or 0) + int(privacy.get("summary", {}).get("findings") or 0)
        row.setdefault("failed_findings", [])
        row["failed_findings"].extend([
            {
                "area": "privacy",
                "message": f"{finding.get('path')}:{finding.get('line')} {finding.get('risk')}",
            }
            for finding in privacy.get("findings", [])[:10]
            if isinstance(finding, dict)
        ])
    row.update({
        "profile": plan.get("profile"),
        "services": len(metadata.get("service_directory", [])),
        "ports": len(metadata.get("port_inventory", [])),
        "capabilities": len(plan.get("capability_matrix", [])),
        "module_catalog": modules_catalog.get("module_count", 0),
        "inputs_required_missing": inputs.get("summary", {}).get("required_missing", 0),
        "inputs_secrets": inputs.get("summary", {}).get("secrets", 0),
        "privacy_findings": privacy.get("summary", {}).get("findings", 0),
        "modules": len(plan.get("modules", [])),
        "artifacts": artifacts.get("artifact_count", 0),
        "ownership_control_planes": ownership.get("summary", {}).get("control_planes", 0),
        "ownership_services": ownership.get("summary", {}).get("services", 0),
        "runbook_scenarios": runbook.get("summary", {}).get("scenarios", 0),
        "runbook_phases": runbook.get("summary", {}).get("phases", 0),
        "topology_nodes": topology.get("summary", {}).get("nodes", 0),
        "topology_edges": topology.get("summary", {}).get("edges", 0),
        "topology_paths": topology.get("summary", {}).get("traffic_paths", 0),
        "doctor_issues": doctor.get("summary", {}).get("issues", 0),
        "doctor_health": doctor.get("health"),
        "incident_decision_steps": incident.get("summary", {}).get("decision_steps", 0),
        "incident_recovery_rows": incident.get("summary", {}).get("recovery_rows", 0),
        "incident_triage_domains": incident.get("summary", {}).get("triage_domains", 0),
        "quickstart_operator_sections": quickstart_operator_sections,
        "private_instance_review_ready": private_instance_review_ready,
        "private_instance_copy_only": len(as_list(private_instance_review.get("copy_only"))),
        "private_instance_validation_commands": len(as_list(private_instance_review.get("validation_commands"))),
        "blueprint_questions": len(blueprint.get("operational_questions", [])),
        "secrets": secrets.get("secret_count", 0),
        "required_secrets": secrets.get("required_count", 0),
        "preflight_blockers": preflight.get("summary", {}).get("blockers", 0),
        "preflight_warnings": preflight.get("summary", {}).get("warnings", 0),
        "ready_for_review": readiness.get("ready_for_review"),
        "ready_for_apply": readiness.get("ready_for_apply"),
        "readiness_warnings": readiness.get("summary", {}).get("warnings", 0),
        "readiness_apply_blockers": readiness.get("summary", {}).get("apply_blockers", 0),
        "rollback_modules": rollback.get("summary", {}).get("modules", 0),
        "rollback_backup_required": rollback.get("summary", {}).get("backup_required_artifacts", 0),
        "evidence_checks": evidence.get("summary", {}).get("checks", 0),
        "evidence_groups": evidence.get("summary", {}).get("groups", 0),
        "apply_plan_artifacts": apply_plan.get("summary", {}).get("artifacts", 0),
        "apply_plan_blockers": apply_plan.get("summary", {}).get("blockers", 0),
        "gates": gates.get("summary", {}).get("gates", 0),
        "gates_required_blocked": gates.get("summary", {}).get("required_blocked", 0),
        "deploy_steps": deploy_plan.get("summary", {}).get("steps", 0),
        "deploy_blockers": deploy_plan.get("summary", {}).get("blockers", 0),
        "bootstrap_phases": bootstrap.get("summary", {}).get("phases", 0),
        "bootstrap_blockers": bootstrap.get("summary", {}).get("blockers", 0),
        "bootstrap_source_tool_sequence": bootstrap.get("summary", {}).get("source_tool_sequence", 0),
        "renderable_artifacts": render_preview.get("summary", {}).get("renderable_artifacts", 0),
        "review_fragment_artifacts": render_preview.get("summary", {}).get("review_fragment_artifacts", 0),
        "rendered_review_artifacts": render_preview.get("summary", {}).get("rendered_review_artifacts", 0),
        "contract_only_artifacts": render_preview.get("summary", {}).get("contract_only_artifacts", 0),
        "rescue_entries": rescue.get("summary", {}).get("local_entries", 0),
        "rescue_modes": rescue.get("summary", {}).get("failure_modes", 0),
        "scripts": scripts.get("summary", {}).get("scripts", 0),
        "script_modules": scripts.get("summary", {}).get("modules", 0),
        "config_artifacts": config_plan.get("summary", {}).get("fragments", 0),
        "config_fragments": config_plan.get("summary", {}).get("fragments", 0),
        "docs_lines": len(docs.splitlines()),
        "kuma_monitors": kuma.get("monitor_count", 0),
        "kuma_auto": kuma.get("auto_importable_count", 0),
        "status_daily_entries": status.get("summary", {}).get("daily_entries", 0),
        "status_remote_entries": status.get("summary", {}).get("remote_entries", 0),
        "status_diagnostic_domains": status.get("summary", {}).get("diagnostic_domains", 0),
        "status_diagnostic_first_probes": status.get("summary", {}).get("diagnostic_first_probes", 0),
        "status_diagnostic_live_findings": status.get("summary", {}).get("diagnostic_live_findings", 0),
        "status_diagnostic_classified_findings": status.get("summary", {}).get("diagnostic_classified_findings", 0),
        "status_diagnostic_domains_with_live_findings": status.get("summary", {}).get("diagnostic_domains_with_live_findings", 0),
        "privacy_ok": bool(privacy.get("ok")),
        "schemas": [source for source in ["site.schema.yaml", "devices.schema.yaml", "services.schema.yaml"]],
    })
    return row


def command_verify(args: argparse.Namespace) -> int:
    instance = Path(args.instance).resolve()
    rows = []
    if not args.skip_examples:
        for example in discover_instances(include_private=False):
            rows.append(verify_instance(example, live=False))
    rows.append(verify_instance(instance, live=args.live))

    failures = sum(1 for row in rows if not row.get("ok"))
    result = {
        "schema": "homenet.verify.v1",
        "ok": failures == 0,
        "live": args.live,
        "instance": str(instance),
        "checked": rows,
        "failures": failures,
    }
    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        print("HomeNet Verify")
        print()
        for row in rows:
            status = "OK" if row.get("ok") else "FAIL"
            if row.get("ok"):
                print(
                    f"- {status} {row.get('name')}: profile={row.get('profile')} "
                    f"services={row.get('services')} ports={row.get('ports')} "
                    f"doctor={row.get('doctor_health')}/{row.get('doctor_issues')} "
                    f"privacy={row.get('privacy_findings')} "
                    f"deploy={row.get('deploy_steps')}/{row.get('deploy_blockers')} "
                    f"rescue={row.get('rescue_entries')}/{row.get('rescue_modes')} "
                    f"kuma={row.get('kuma_auto')}/{row.get('kuma_monitors')} "
                    f"status={row.get('status_daily_entries')}/{row.get('status_remote_entries')} "
                    f"diagnostic={row.get('status_diagnostic_domains')}/{row.get('status_diagnostic_first_probes')} "
                    f"warnings={row.get('warnings')}"
                )
            else:
                print(f"- {status} {row.get('name')}: failures={row.get('failures')} warnings={row.get('warnings')}")
                for finding in row.get("failed_findings", [])[:5]:
                    print(f"  - {finding.get('area')}: {finding.get('message')}")
        print()
        print(f"Summary: checked={len(rows)} failures={failures} live={args.live}")
    return 2 if failures else 0


def instance_template_for_profile(profile: str) -> Path:
    templates = {
        "openwrt-pi": ROOT / "instances" / "example-openwrt-pi",
        "openwrt-mini-pc": ROOT / "instances" / "example-openwrt-pi",
        "openwrt-only": ROOT / "instances" / "example-openwrt-only",
    }
    template = templates.get(profile)
    if not template or not template.exists():
        raise RuntimeError(f"No template for profile {profile}")
    return template


def validate_instance_name(name: str) -> bool:
    return bool(re.fullmatch(r"[a-z0-9][a-z0-9-]{1,62}", name))


def render_new_instance_readme(
    *,
    name: str,
    display_name: str,
    profile: str,
    profile_title: str,
    required_inputs: list[Any],
    output: Path,
) -> str:
    rel_output = output
    try:
        rel_output = output.relative_to(ROOT)
    except ValueError:
        pass
    instance_ref = str(rel_output)
    lines = [
        f"# HomeNet Instance: {display_name}",
        "",
        "This is a HomeNet deployment instance scaffold.",
        "",
        f"- instance id: `{name}`",
        f"- profile: `{profile}` ({profile_title})",
        f"- path: `{instance_ref}`",
        "- secrets are intentionally absent from this directory.",
        "- edit declared intent in `site.yaml`, `devices.yaml`, and `services.yaml` before touching live infrastructure.",
        "",
        "## Fill These First",
        "",
    ]
    if required_inputs:
        for item in required_inputs:
            lines.append(f"- {item}")
    else:
        lines.append("- Confirm this profile's runtime targets, networks, Wi-Fi, devices, services, and secret names.")
    if profile == "openwrt-only":
        site_checklist = (
            "`site.yaml`: site name/display name/domain, OpenWrt Gateway, network CIDRs, SSIDs, "
            "module toggles, OpenWrt-local service choices, and remote ingress hostnames."
        )
    else:
        site_checklist = (
            "`site.yaml`: site name/display name/domain, OpenWrt Gateway, server runtime, room AP, "
            "network CIDRs, SSIDs, module toggles, and remote ingress hostnames."
        )
    lines.extend([
        "",
        "## Edit Checklist",
        "",
        f"- {site_checklist}",
        "- `devices.yaml`: fixed devices, expected IP addresses, hostnames, roles, owners, and MAC inventory when known.",
        "- `services.yaml`: service entries, owners, local URLs, remote URLs, ports, categories, checks, and container ownership.",
        "- local secret storage or service-native stores: Wi-Fi PSKs, proxy provider URLs, API tokens, private keys, cookies, and sessions.",
        "",
    ])
    lines.extend([
        "## First Pass",
        "",
        "```sh",
        f"./homenet quickstart --instance {instance_ref}",
        f"./homenet inputs --instance {instance_ref}",
        f"./homenet worksheet --instance {instance_ref}",
        f"./homenet check --instance {instance_ref}",
        "```",
        "",
        "## Verify And Package",
        "",
        "```sh",
        f"./homenet secrets --instance {instance_ref}",
        f"./homenet secrets --instance {instance_ref} --template",
        f"./homenet preflight --instance {instance_ref}",
        f"./homenet deploy --instance {instance_ref} --force --check-idempotent",
        f"./homenet check --instance {instance_ref}",
        f"./homenet bundle --instance {instance_ref} --output /tmp/homenet-review",
        "```",
        "",
        "## Optional Planning Detail",
        "",
        "Use these when you need to understand module placement or service/topology details. They are not the first-deployment path.",
        "",
        "```sh",
        f"./homenet modules --instance {instance_ref}",
        f"./homenet topology --instance {instance_ref}",
        f"./homenet status --instance {instance_ref}",
        "```",
        "",
    ])
    if profile != "openwrt-only":
        lines.extend([
            "## Server Runtime Template",
            "",
            "Use the public compose template as a private starting point for this home:",
            "",
            "```sh",
            "cp templates/compose/docker-compose.yml ./docker-compose.yml",
            "cp templates/compose/env.example ./.env",
            "```",
            "",
            "Fill the local `.env` from your secret store. Do not commit filled `.env`, service databases, certificates, WireGuard data, Cloudflare credentials, or proxy subscriptions.",
            "",
        ])
    lines.extend([
        "## Advanced Review Before Live Changes",
        "",
        "```sh",
        f"./homenet deploy --instance {instance_ref} --dry-run",
        f"./homenet rollback --instance {instance_ref}",
        f"./homenet apply --instance {instance_ref} --dry-run",
        f"./homenet gates --instance {instance_ref}",
        f"./homenet evidence --instance {instance_ref}",
        f"./homenet render --instance {instance_ref} --dry-run",
        f"./homenet generate --instance {instance_ref} --dry-run",
        "```",
        "",
        "## Rules",
        "",
        "- Keep Wi-Fi passwords, API tokens, proxy subscriptions, private keys, cookies, and sessions outside this directory.",
        "- Use source tools for live OpenWrt, Docker, systemd, Cloudflare, Kuma, and service-native changes until guarded apply is explicitly implemented.",
        "- Run privacy and CI gates before publishing, committing, or handing this instance to another maintainer.",
        "",
    ])
    return "\n".join(lines)


def write_instance_scaffold(
    *,
    name: str,
    profile: str,
    display_name: str | None,
    domain: str | None,
    output: Path,
) -> tuple[dict[str, Any], dict[str, Any], str]:
    template = instance_template_for_profile(profile)
    shutil.copytree(template, output)
    site_path = output / "site.yaml"
    site_doc = load_yaml(site_path)
    if not isinstance(site_doc, dict):
        raise RuntimeError(f"{site_path} is not a YAML mapping")
    site_info = site_doc.setdefault("site", {})
    if not isinstance(site_info, dict):
        site_doc["site"] = site_info = {}
    site_info["name"] = name
    site_info["display_name"] = display_name or name
    if domain:
        site_info["domain"] = domain
    if profile == "openwrt-mini-pc":
        runtime = site_doc.setdefault("runtime", {})
        if not isinstance(runtime, dict):
            site_doc["runtime"] = runtime = {}
        server = runtime.setdefault("server", {})
        if not isinstance(server, dict):
            runtime["server"] = server = {}
        server["enabled"] = True
        server["preferred"] = "mini-pc"
        server["role"] = "Server runtime on mini PC, NAS, or another higher-capacity always-on Linux host"
    site_path.write_text(yaml.safe_dump(site_doc, allow_unicode=True, sort_keys=False), encoding="utf-8")
    profile_info = profile_by_id(str(profile))
    readme_path = output / "README.md"
    readme_path.write_text(
        render_new_instance_readme(
            name=name,
            display_name=str(site_info.get("display_name") or name),
            profile=str(profile),
            profile_title=str(profile_info.get("title") or profile),
            required_inputs=as_list(profile_info.get("required_inputs")),
            output=output,
        ),
        encoding="utf-8",
    )
    reporter = Reporter()
    state = check_instance(output, reporter)
    if reporter.failed:
        raise RuntimeError("Generated instance failed validation")
    metadata = build_metadata(state, output)
    docs = render_instance_docs(metadata)
    return state, metadata, docs


def command_new(args: argparse.Namespace) -> int:
    name = str(args.name or "").strip()
    if not validate_instance_name(name):
        print("Instance name must match [a-z0-9][a-z0-9-]{1,62}", file=sys.stderr)
        return 2

    output = Path(args.output).resolve() if args.output else (ROOT / "instances" / name)
    if output.exists() and not args.force:
        print(f"{output} already exists. Use --force to replace it.", file=sys.stderr)
        return 2
    if output.exists() and args.force:
        shutil.rmtree(output)

    try:
        state, metadata, docs = write_instance_scaffold(
            name=name,
            profile=str(args.profile),
            display_name=args.display_name,
            domain=args.domain,
            output=output,
        )
    except RuntimeError as exc:
        print(str(exc), file=sys.stderr)
        return 2

    plan = build_plan(state, output)
    print(f"Created {output}")
    print(f"- profile: {plan.get('profile')}")
    print(f"- services: {len(metadata.get('service_directory', []))}")
    print(f"- capabilities: {len(plan.get('capability_matrix', []))}")
    print(f"- generated docs lines: {len(docs.splitlines())}")
    print()
    print("Next:")
    print(f"- edit {output / 'site.yaml'}")
    print(f"- edit {output / 'devices.yaml'}")
    print(f"- edit {output / 'services.yaml'}")
    print(f"- run ./homenet check --instance {output}")
    return 0


def prompt_value(prompt: str, default: str) -> str:
    value = input(f"{prompt} [{default}]: ").strip()
    return value or default


def prompt_bool(prompt: str, default: bool) -> bool:
    suffix = "Y/n" if default else "y/N"
    while True:
        value = input(f"{prompt} [{suffix}]: ").strip().lower()
        if not value:
            return default
        if value in {"y", "yes"}:
            return True
        if value in {"n", "no"}:
            return False
        print("Please answer yes or no.")


def prompt_profile(default: str) -> str:
    choices = {
        "1": "openwrt-pi",
        "2": "openwrt-only",
        "3": "openwrt-mini-pc",
        "openwrt-pi": "openwrt-pi",
        "openwrt-only": "openwrt-only",
        "openwrt-mini-pc": "openwrt-mini-pc",
    }
    print("Deployment shape:")
    print("1. openwrt-pi        OpenWrt + Pi/server runtime")
    print("2. openwrt-only      OpenWrt only")
    print("3. openwrt-mini-pc   OpenWrt + mini PC/NAS")
    while True:
        value = input(f"Choose profile [{default}]: ").strip() or default
        selected = choices.get(value)
        if selected:
            return selected
        print("Choose 1, 2, 3, or a profile id.")


def profile_runtime_defaults(profile: str) -> dict[str, str]:
    site_doc = load_yaml(instance_template_for_profile(profile) / "site.yaml")
    site_doc = site_doc if isinstance(site_doc, dict) else {}
    runtime = site_doc.get("runtime", {}) if isinstance(site_doc.get("runtime"), dict) else {}
    router = runtime.get("router", {}) if isinstance(runtime.get("router"), dict) else {}
    server = runtime.get("server", {}) if isinstance(runtime.get("server"), dict) else {}
    room_ap = runtime.get("room_ap", {}) if isinstance(runtime.get("room_ap"), dict) else {}
    return {
        "router_host": str(router.get("host") or "192.168.50.1"),
        "server_host": str(server.get("host") or ""),
        "room_ap_host": str(room_ap.get("host") or ""),
    }


def rewrite_scaffold_ipv4_values(
    value: Any,
    *,
    old_networks: dict[str, str],
    old_router_host: str,
    router_host: str,
    old_server_host: str,
    server_host: str,
    old_room_ap_host: str,
    room_ap_host: str,
) -> Any:
    try:
        old_lan = ipaddress.ip_network(old_networks.get("lan", ""), strict=False)
        new_router = ipaddress.ip_address(router_host)
    except ValueError:
        return value
    if not isinstance(new_router, ipaddress.IPv4Address):
        return value

    old_network_objs: dict[str, ipaddress.IPv4Network] = {}
    for key, cidr in old_networks.items():
        try:
            network = ipaddress.ip_network(str(cidr), strict=False)
        except ValueError:
            continue
        if isinstance(network, ipaddress.IPv4Network):
            old_network_objs[key] = network

    new_lan_octets = str(new_router).split(".")
    new_lan_prefix = ".".join(new_lan_octets[:2])
    new_lan_third = int(new_lan_octets[2])
    old_lan_third = int(str(old_lan.network_address).split(".")[2])
    exact_hosts = {
        old_router_host: router_host,
        old_server_host: server_host,
        old_room_ap_host: room_ap_host,
    }
    exact_hosts = {k: v for k, v in exact_hosts.items() if k and v}

    def map_ip(raw: str) -> str:
        if raw in exact_hosts:
            return exact_hosts[raw]
        try:
            ip = ipaddress.ip_address(raw)
        except ValueError:
            return raw
        if not isinstance(ip, ipaddress.IPv4Address):
            return raw
        for network in old_network_objs.values():
            if ip not in network:
                continue
            octets = raw.split(".")
            offset = int(str(network.network_address).split(".")[2]) - old_lan_third
            return f"{new_lan_prefix}.{new_lan_third + offset}.{octets[3]}"
        return raw

    ip_pattern = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")

    def rewrite(item: Any) -> Any:
        if isinstance(item, str):
            return ip_pattern.sub(lambda match: map_ip(match.group(0)), item)
        if isinstance(item, list):
            return [rewrite(child) for child in item]
        if isinstance(item, dict):
            return {key: rewrite(child) for key, child in item.items()}
        return item

    return rewrite(value)


def apply_init_answers(
    output: Path,
    *,
    router_host: str,
    server_host: str,
    room_ap_enabled: bool,
    room_ap_host: str,
    maintenance_wifi_enabled: bool,
    remote_access_enabled: bool,
    smart_home_enabled: bool,
) -> None:
    site_path = output / "site.yaml"
    site_doc = load_yaml(site_path)
    if not isinstance(site_doc, dict):
        raise RuntimeError(f"{site_path} is not a YAML mapping")
    runtime_before = site_doc.get("runtime", {}) if isinstance(site_doc.get("runtime"), dict) else {}
    router_before = runtime_before.get("router", {}) if isinstance(runtime_before.get("router"), dict) else {}
    server_before = runtime_before.get("server", {}) if isinstance(runtime_before.get("server"), dict) else {}
    room_ap_before = runtime_before.get("room_ap", {}) if isinstance(runtime_before.get("room_ap"), dict) else {}
    networks_before = site_doc.get("networks", {}) if isinstance(site_doc.get("networks"), dict) else {}
    old_networks = {
        key: str(row.get("cidr") or "")
        for key, row in networks_before.items()
        if isinstance(row, dict) and row.get("cidr")
    }
    rewrite_kwargs = {
        "old_networks": old_networks,
        "old_router_host": str(router_before.get("host") or ""),
        "router_host": router_host,
        "old_server_host": str(server_before.get("host") or ""),
        "server_host": server_host,
        "old_room_ap_host": str(room_ap_before.get("host") or ""),
        "room_ap_host": room_ap_host if room_ap_enabled else "",
    }
    site_doc = rewrite_scaffold_ipv4_values(site_doc, **rewrite_kwargs)
    for rel in ["devices.yaml", "services.yaml"]:
        doc_path = output / rel
        doc = load_yaml(doc_path)
        doc = rewrite_scaffold_ipv4_values(doc, **rewrite_kwargs)
        doc_path.write_text(yaml.safe_dump(doc, allow_unicode=True, sort_keys=False), encoding="utf-8")
    runtime = site_doc.setdefault("runtime", {})
    if not isinstance(runtime, dict):
        site_doc["runtime"] = runtime = {}
    router = runtime.setdefault("router", {})
    if not isinstance(router, dict):
        runtime["router"] = router = {}
    router["host"] = router_host

    server = runtime.setdefault("server", {})
    if isinstance(server, dict) and server_host:
        server["enabled"] = True
        server["host"] = server_host

    room_ap = runtime.setdefault("room_ap", {})
    if not isinstance(room_ap, dict):
        runtime["room_ap"] = room_ap = {}
    if room_ap_enabled:
        room_ap["host"] = room_ap_host
        room_ap.setdefault("type", "openwrt-ap")
    else:
        room_ap.pop("host", None)
        room_ap["type"] = "none"
        room_ap["role"] = "disabled"

    modules = site_doc.setdefault("modules", {})
    if isinstance(modules, dict):
        if "maintenance-wifi" in modules and isinstance(modules["maintenance-wifi"], dict):
            modules["maintenance-wifi"]["enabled"] = maintenance_wifi_enabled
        if "remote-access" in modules and isinstance(modules["remote-access"], dict):
            modules["remote-access"]["enabled"] = remote_access_enabled
        if "smart-home" in modules and isinstance(modules["smart-home"], dict):
            modules["smart-home"]["enabled"] = smart_home_enabled
        if "room-ap" in modules and isinstance(modules["room-ap"], dict):
            modules["room-ap"]["enabled"] = room_ap_enabled
            if not room_ap_enabled:
                modules["room-ap"]["runtime"] = "none"
                modules["room-ap"]["implementation"] = "disabled"

    networks = site_doc.get("networks", {})
    if isinstance(networks, dict) and "ops" in networks and isinstance(networks["ops"], dict):
        networks["ops"]["enabled"] = maintenance_wifi_enabled
    if not remote_access_enabled:
        site_doc["remote_ingress"] = []

    site_path.write_text(yaml.safe_dump(site_doc, allow_unicode=True, sort_keys=False), encoding="utf-8")


def command_init(args: argparse.Namespace) -> int:
    interactive = not args.yes
    name = str(args.name or "my-home").strip()
    profile = str(args.profile or "openwrt-pi")
    defaults = profile_runtime_defaults(profile)
    display_name = args.display_name or name
    domain = args.domain or "example.net"
    router_host = args.router_host or defaults["router_host"]
    server_host = args.server_host or (defaults["server_host"] if profile != "openwrt-only" else "")
    room_ap_host = args.room_ap_host or defaults["room_ap_host"] or "192.168.50.2"
    room_ap_enabled = bool(args.room_ap)
    maintenance_wifi_enabled = not args.no_maintenance_wifi
    remote_access_enabled = not args.no_remote_access
    smart_home_enabled = bool(args.smart_home)

    if interactive:
        print("HomeNet interactive init")
        print("No live network config will be changed.")
        name = prompt_value("Instance id", name)
        while not validate_instance_name(name):
            print("Use lowercase letters, numbers, and dashes; start with a letter or number.")
            name = prompt_value("Instance id", "my-home")
        display_name = prompt_value("Display name", display_name)
        domain = prompt_value("Public domain or placeholder", domain)
        profile = prompt_profile(profile)
        defaults = profile_runtime_defaults(profile)
        router_host = args.router_host or defaults["router_host"]
        server_host = args.server_host or (defaults["server_host"] if profile != "openwrt-only" else "")
        room_ap_host = args.room_ap_host or defaults["room_ap_host"] or room_ap_host
        router_host = prompt_value("OpenWrt router IP", router_host)
        if profile != "openwrt-only":
            server_host = prompt_value("Pi/server IP", server_host or "192.168.50.5")
        else:
            server_host = ""
        room_ap_enabled = prompt_bool("Use a room/bedroom AP", room_ap_enabled)
        if room_ap_enabled:
            room_ap_host = prompt_value("Room AP IP", room_ap_host)
        maintenance_wifi_enabled = prompt_bool("Create/declare Maintenance Wi-Fi rescue path", maintenance_wifi_enabled)
        remote_access_enabled = prompt_bool("Enable remote access module", remote_access_enabled)
        smart_home_enabled = prompt_bool("Enable smart-home module", smart_home_enabled)

    if not validate_instance_name(name):
        print("Instance name must match [a-z0-9][a-z0-9-]{1,62}", file=sys.stderr)
        return 2

    output = Path(args.output).resolve() if args.output else (ROOT / "instances" / name)
    with tempfile.TemporaryDirectory(prefix="homenet-init-") as tmp:
        candidate = Path(tmp) / name
        try:
            write_instance_scaffold(name=name, profile=profile, display_name=display_name, domain=domain, output=candidate)
            apply_init_answers(
                candidate,
                router_host=router_host,
                server_host=server_host,
                room_ap_enabled=room_ap_enabled,
                room_ap_host=room_ap_host,
                maintenance_wifi_enabled=maintenance_wifi_enabled,
                remote_access_enabled=remote_access_enabled,
                smart_home_enabled=smart_home_enabled,
            )
            site_doc = load_yaml(candidate / "site.yaml")
            site_info = site_doc.get("site", {}) if isinstance(site_doc, dict) and isinstance(site_doc.get("site"), dict) else {}
            profile_info = profile_by_id(profile)
            (candidate / "README.md").write_text(
                render_new_instance_readme(
                    name=name,
                    display_name=str(site_info.get("display_name") or display_name or name),
                    profile=profile,
                    profile_title=str(profile_info.get("title") or profile),
                    required_inputs=as_list(profile_info.get("required_inputs")),
                    output=output,
                ),
                encoding="utf-8",
            )
        except RuntimeError as exc:
            print(str(exc), file=sys.stderr)
            return 2

        reporter = Reporter()
        state = check_instance(candidate, reporter)
        if reporter.failed:
            reporter.print()
            return 2

        candidate_snapshot = snapshot_directory(candidate)
        existing_snapshot = snapshot_directory(output) if output.exists() else None
        changed = output.exists() and existing_snapshot != candidate_snapshot
        unchanged = output.exists() and existing_snapshot == candidate_snapshot

        if unchanged:
            action = "unchanged"
        elif output.exists() and changed and not args.force:
            if not interactive or not prompt_bool(f"{output} exists and differs. Replace it", False):
                print(f"{output} already exists and differs. Re-run with --force to replace it.", file=sys.stderr)
                return 2
            shutil.rmtree(output)
            shutil.copytree(candidate, output)
            action = "replaced"
        else:
            if output.exists():
                shutil.rmtree(output)
            shutil.copytree(candidate, output)
            action = "created"

    print(f"Init {action}: {output}")
    print(f"- profile: {profile}")
    print(f"- router: {router_host}")
    if server_host:
        print(f"- server: {server_host}")
    print(f"- modules: {len(build_module_decisions(profile, state.get('site', {})))}")
    print()
    print("Next:")
    print(f"- edit {output / 'site.yaml'}")
    print(f"- edit {output / 'devices.yaml'}")
    print(f"- edit {output / 'services.yaml'}")
    print(f"- run ./homenet deploy --instance {output} --force --check-idempotent")
    print(f"- run ./homenet check --instance {output}")
    return 0


def build_parser() -> argparse.ArgumentParser:
    prog = os.environ.get("HOMENET_PROG") or Path(sys.argv[0]).name or "homenet"
    parser = argparse.ArgumentParser(prog=prog, description="HomeNet household network tools")
    sub = parser.add_subparsers(dest="command", required=True, metavar="command")

    blueprint = sub.add_parser("blueprint", help="show product contract and active/fallback capabilities for an instance")
    blueprint.add_argument(
        "--instance",
        default=str(DEFAULT_INSTANCE),
        help="instance directory, default: private instance if present, otherwise instances/example-openwrt-pi",
    )
    blueprint.add_argument("--format", choices=["json", "markdown"], default="markdown", help="output format")
    blueprint.set_defaults(func=command_blueprint)

    profiles = sub.add_parser("profiles", help="show supported deployment profiles and capability tradeoffs")
    profiles.add_argument("--format", choices=["json", "markdown"], default="markdown", help="output format")
    profiles.set_defaults(func=command_profiles)

    quickstart = sub.add_parser("quickstart", help="show first-deployment workflow for a profile or instance")
    quickstart.add_argument("--profile", choices=PROFILE_IDS, default="openwrt-pi", help="deployment profile")
    quickstart.add_argument("--instance", help="existing instance directory; overrides --profile when present")
    quickstart.add_argument("--name", default="my-home", help="suggested instance name for scaffold commands")
    quickstart.add_argument("--format", choices=["json", "markdown"], default="markdown", help="output format")
    quickstart.set_defaults(func=command_quickstart)

    init = sub.add_parser("init", help="interactive idempotent setup for a private home instance")
