def print_short_help(prog: str) -> None:
    print("HomeNet household network tools")
    print("Use the main path first; advanced review and publishing commands are for maintainers.")
    print()
    print("Main path:")
    print(f"  {prog} init")
    print(f"  {prog} deploy --instance instances/my-home --force --check-idempotent")
    print(f"  {prog} check --instance instances/my-home")
    print(f"  {prog} status --instance instances/my-home --live")
    print()
    print("Daily troubleshooting:")
    print(f"  {prog} incident --instance instances/my-home --live")
    print(f"  {prog} doctor --instance instances/my-home --live")
    print(f"  {prog} rescue --instance instances/my-home")
    print()
    print("Release and boundaries:")
    print(f"  {prog} privacy --scope public")
    print(f"  {prog} release-candidate --instance instances/my-home --force")
    print(f"  {prog} version --instance instances/my-home")
    print(f"  {prog} workspace --instance instances/my-home")
    print()
    print("Use '<command> --help' for one command.")
    print("Use '--help-all' only when maintaining or publishing the project.")


def main(argv: list[str] | None = None) -> int:
    args_list = list(sys.argv[1:] if argv is None else argv)
    prog = os.environ.get("HOMENET_PROG") or Path(sys.argv[0]).name or "homenet"
    if not args_list or args_list in (["-h"], ["--help"]):
        print_short_help(prog)
        return 0
    parser = build_parser()
    if args_list == ["--help-all"]:
        parser.print_help()
        return 0
    args = parser.parse_args(args_list)
    return args.func(args)


if __name__ == "__main__":
    raise SystemExit(main())
